$('.sidebar-toggle').click(function () {
	if ($(this).hasClass('minimized')) {
		$(this).removeClass('minimized');
		$('.quickaccess').css('margin-top', '8%');
	} else {
		$(this).addClass('minimized');
		$('.quickaccess').css('margin-top', '6.5%');
		$('.quickaccess').css('margin-left', '3%');
	} //end if
});

$(document).on('click', '.sidemenutoggler', debounce(function () {
	setLayoutsetting();
}, 300));

$(document).on('keyup', '#dashusername', function (event) {
	if (event.which == "13") {
		$('#dashpassword').focus();
	}
});

$(document).on('keyup', '#dashpassword', function (event) {
	if (event.which == "13") {
		$(".btndashin").trigger("click");
	}
});

$(document).on('click', '.btndashin', debounce(function () {
	var user = $('#dashusername').val();
	var pass = $('#dashpassword').val();
	$('.btndashin').prop('disabled', true);

	switch (cconfig) {
		case 'KINGGEORGE':
			var initparam = checkforInitialParameters();
			var params = {
				username: user,
				password: pass,
				q: initparam.q
			};
			break;

		default:
			var params = {
				username: user,
				password: pass
			};
			break;
	} //end switch

	$.get(domain + '/admin/requestlogin', params,
		function (data) {

			if (data.msg == "") {
				$('login-errmsg').html("");
				$('.login-errmsg').css('display', 'none');
				if (data.centerselection) {
					$('.btndashin').prop('disabled', false);
					$('#smallModal').modal();
					$('#centerbox').html("");
					$.each(data.centers, function (centerindex, centername) {
						$('#centerbox').append("<option value='" + data.centers[centerindex]['id'] + "'>" + data.centers[centerindex]['name'] + "</option");
					});
				} else {
					$('.btndashin').prop('disabled', false);
					if (data.status) {
						loginSucessfullPopup();
					} else {
						generateAlert('error', data.centererror, 'ERROR');
					}
				}
			} else {
				$('.login-errmsg').css('display', 'block');
				$('.login-errmsg').html(data.msg);
				$('.btndashin').prop('disabled', false);
			}
		}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
}, 300));

$(document).on('click', '.btnselectcenter', debounce(function () {
	var centerid = $('#centerbox option:selected').val();
	$('.btnselectcenter').prop('disabled', true);
	$('.btncancelcenter').prop('disabled', true);
	$.get(domain + '/admin/setusercenter', {
			centerid: centerid
		},
		function (data) {

			if (data.status) {
				loginSucessfullPopup();
			} else {
				generateAlert('error', 'Error L101: Login Error , Please try again!', 'ERROR');
			}
		}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
}, 300));

function loginSucessfullPopup() {
	$('.btnselectcenter').prop('disabled', false);
	$('.btncancelcenter').prop('disabled', false);
	$('#smallModal').modal('hide');
	$('#overlay').css('display', 'block');
	generateAlert('information', "Please wait..You'll be redirected automatically. Thank you!", 'DEFAULT');
	var url = domain + '/admin/index';
	$(location).attr('href', url);
}

$(document).on('click', '.btn-navfirst', function () {
	var btnaction = "first";
	var btnid = $(this).attr('id').split('-');
	var moduleid = $('#viewmoduleid').val();
	$('#overlay').css('display', 'block');
	getButtonactions(moduleid, btnaction, '');
});

$(document).on('click', '.btn-navprev', function () {
	var moduleid = $('#viewmoduleid').val();
	var btnaction = "previous";
	switch (moduleid) {
		case 'customer':
		case 'supplier':
		case 'agent':
		case 'warehouse':
		case 'location':
		case 'vendor':
		case 'assetmaster':
		case 'branch':
			var clientid = $('#clientid').val(),
				client = $('.txtclient').val(),
				params = {
					client: client,
					trno: clientid
				};
			break;

		case 'stockcard':
		case 'itemprofile':
		case 'posstockcard':
		case 'FG':
			var itemid = $('#itemid').val(),
				params = {
					barcode: $('.txtbarcode').val(),
					itemid: itemid
				};
			$('#overlay').css('display', 'block');
			break;

		case 'employee':
			var clientid = $('#empid').val(),
				client = $('.txtempcode').val(),
				params = {
					client: client,
					trno: clientid
				};
			break;

		default:
			var btnid = $(this).attr('id').split('-'),
				txttrno = $('.txttrno').html().split(':'),
				params = {
					docno: $('.txtdocno').val(),
					trno: txttrno[1]
				};
			break;
	}
	$('#overlay').css('display', 'block');
	getButtonactions(moduleid, btnaction, params);
});

