//CANCEL BUTTON FUNCTION
$(document).on('click', '.stockcancelbtn', function () {
	var btnid = $(this).attr('id').split('-');
	var line = btnid[1];
	cancelStockitemedit(line);
});

function cancelStockitemedit(line) {
	var trno = $('.txtboxtrno').val();
	$('#overlay').css('display', 'block');
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/canceledit', {
			trno: trno,
			line: line
		},
		function (data) {

			switch (moduleid) {
				case 'GJ':
				case 'CR':
				case 'PV':
				case 'CV':
				case 'AP':
				case 'AR':
				case 'DS':
					$('#orgrow-' + line).removeClass('editing saveable');
					$('#detailpostdate-' + line + '.origdata').html(data.detailline[0]['postdate']);
					$('#detailcheckno-' + line + '.origdata').html(data.detailline[0]['checkno']);
					$('#detailacno-' + line + '.origdata').html(data.detailline[0]['acno']);
					$('#detailacnoname-' + line + '.origdata').html(data.detailline[0]['acnoname']);
					$('#detailclient-' + line + '.origdata').html(data.detailline[0]['client']);
					$('#detaildb-' + line + '.origdata').html(data.detailline[0]['db']);
					$('#detailcr-' + line + '.origdata').html(data.detailline[0]['cr']);
					switch (moduleid) {
						case 'AP':
						case 'PV':
						case 'CV':
						case 'GJ':
							$('#detailcostcenter-' + line + '.origdata').html(data.detailline[0]['costcenter']);
							break;
					} //end switch
					$('#detailrem-' + line + '.origdata').html(data.detailline[0]['rem']);
					$('#detailref-' + line + '.origdata').html(data.detailline[0]['ref']);
					$('#detailrefx-' + line + '.origdata').html(data.detailline[0]['refx']);
					$('#detaillinex-' + line + '.origdata').html(data.detailline[0]['linex']);
					$('#detailline-' + line + '.origdata').html(data.detailline[0]['line']);
					$('#stockbuttons-' + line + '.origdata').html('<button id="stockedit-' + line + '"class="stockbtn stockeditbtn btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></button>\
			        <button id="stockdelete-' + line + '" class="stockbtn stockdeletebtn btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-trash"></i></button>');
					break;

					//TW KEYWORD
				case 'TW':
					$('#orgrow-' + line).removeClass('editing saveable');
					$('#txttaxname-' + line + '.origdata').html(data.detailline[0]['acnoname']);
					$('#txttaxatc-' + line + '.origdata').html(data.detailline[0]['acno']);
					$('#txttaxrate-' + line + '.origdata').html(data.detailline[0]['rate']);
					$('#txttaxincome-' + line + '.origdata').html(data.detailline[0]['income']);
					$('#txttaxwheld-' + line + '.origdata').html(data.detailline[0]['wheld']);
					$('#stockline-' + line + '.origdata').html(data.detailline[0]['line']);
					$('#stockbuttons-' + line + '.origdata').html('<button id="stockedit-' + line + '"class="stockbtn stockeditbtn btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></button>\
			        <button id="stockdelete-' + line + '" class="stockbtn stockdeletebtn btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-trash"></i></button>');
					break;

				default:
					$('#orgrow-' + line).removeClass('editing saveable');
					$('#stockbarcode-' + line + '.origdata').html(data.stockdata[0]['barcode']);
					$('#stockisqty-' + line + '.origdata').html(data.stockdata[0]['isqty']);
					$('#stockisqty2-' + line + '.origdata').html(data.stockdata[0]['isqty2']);
					$('#stockrrqty-' + line + '.origdata').html(data.stockdata[0]['rrqty']);
					$('#stockuom-' + line + '.origdata').html(data.stockdata[0]['uom']);
					$('#stockitemname-' + line + '.origdata').html(data.stockdata[0]['itemname']);
					$('#stockisamt-' + line + '.origdata').html(data.stockdata[0]['isamt'], 2);
					$('#stockrrcost-' + line + '.origdata').html(data.stockdata[0]['rrcost'], 2);
					$('#stockdisc-' + line + '.origdata').html(data.stockdata[0]['disc']);
					$('#stockext-' + line + '.origdata').html(data.stockdata[0]['ext'], 2);
					$('#stockqa-' + line + '.origdata').html(data.stockdata[0]['qa']);
					$('#stockref-' + line + '.origdata').html(data.stockdata[0]['ref']);
					$('#stockloc-' + line + '.origdata').html(data.stockdata[0]['loc']);
					$('#stockloc2-' + line + '.origdata').html(data.stockdata[0]['loc2']);
					$('#stockexpiry-' + line + '.origdata').html(data.stockdata[0]['expiry']);
					$('#stockrem-' + line + '.origdata').html(data.stockdata[0]['rem']);
					$('#stockiss-' + line + '.origdata').html(data.stockdata[0]['iss']);
					$('#stockiss2-' + line + '.origdata').html(data.stockdata[0]['iss2']);
					$('#stockamt-' + line + '.origdata').html(data.stockdata[0]['amt']);
					$('#stockqty-' + line + '.origdata').html(data.stockdata[0]['qty']);
					$('#stockcost-' + line + '.origdata').html(data.stockdata[0]['cost']);
					$('#stockwhcode-' + line + '.origdata').html(data.stockdata[0]['whcode']);
					$('#stockwh-' + line + '.origdata').html(data.stockdata[0]['wh']);
					switch (moduleid) {
						case 'SP':
							$('#stockbuttons-' + line + '.origdata').html('<button id="stockedit-' + line + '"class="stockbtn stockeditbtn btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></button>\
						        <button id = "showbalance-' + data.stockdata[0]['itemid'] + '" data-toggle="tooltip" title="Show Balance" class="showbalance stockbtn stockattrbtn btn btn-social-icon btn-github" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-eye"></i></button>');
							break;

						default:
							var btns = '';
							btns += '<button id="stockedit-' + line + '"class="stockbtn stockeditbtn btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></button>';
							btns += '<button id="stockdelete-' + line + '" class="stockbtn stockdeletebtn btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-trash"></i></button>';
							if (cconfig == 'PANDATOOLS') {
								if (moduleid == 'SJ') {
									btns += '<button id="component-' + data.stockdata[0]['itemid'] + ' - ' + data.stockdata[0]['isqty'] + '" class="stockbtn thecomponentsbutton btn btn-social-icon btn-google bg-orange" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-cube"></i></button>';
								}
							}
							btns += '<button id = "showbalance-' + data.stockdata[0]['itemid'] + '" data-toggle="tooltip" title="Show Balance" class="showbalance stockbtn stockattrbtn btn btn-social-icon btn-github" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-eye"></i></button>'
							$('#stockbuttons-' + line + '.origdata').html(btns);
							break;
					} //endmodu
					break;
			}

			if (checkBodytable('stock')) {
				$('.stocksaveall').css('display', 'block');
				$('.detailsaveall').css('display', 'block');
			} else {
				$('.stocksaveall').css('display', 'none');
				$('.detailsaveall').css('display', 'none');
			}
			$('#overlay').css('display', 'none');
		}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //END CANCE STOCK ITEM EDIT
