//SEARCH DOCUMENT FROM MODAL
$(document).on('click', '.searchdocumentbtn', debounce(function () {
	var type = $('#doclookuptype').val();

	switch (type) {
		case 'RR_TO_SP':
			var myid = $(this).attr('id').split('@');
			var trno = myid[0];
			copyRRStockToSPStock(trno);
			break;

		case 'PROD_INSTRUCT':
			$('#modal-docnolookup').modal('hide');
			var myid = $(this).attr('id').split('@');
			var itemid = myid[0];
			var barcode = myid[1];
			var docno = myid[2];
			var clientcode = $('.txtclientcode').val();
			var itemname = $('#pr-clientname-' + itemid).html();
			var itemprice = 0;
			var whdefaultval = $('.txtwarehouse').val();
			var params = {
				itemid: itemid,
				barcode: barcode,
				clientcode: clientcode,
				itemname: itemname,
				itemprice: itemprice,
				wh: whdefaultval,
				docno: docno
			};
			$('#modal-enterqty').modal();
			$('.selectuompopup').html('');
			requestPrice(params);
			break;

		case 'PROD_ORDER':
			$('#modal-docnolookup').modal('hide');
			var myid = $(this).attr('id').split('@');
			var trno = myid[0];
			var docno = myid[1];
			var whdefaultval = $('.txtclientcode').val();
			var params = {
				trno: trno,
				docno: docno,
				wh: whdefaultval
			};
			retrievePDinfo(params);
			break;

		case 'RFDOCNO_LOOKUP':
			$('#modal-docnolookup').modal('hide');
			var myid = $(this).attr('id').split('@');
			var trno = myid[0];
			retrieveRFDetails(trno);
			break;

		case 'EXTERNAL_SJ_LOOKUP':
			$('#modal-docnolookup').modal('hide');
			var myid = $(this).attr('id').split('@');
			var trno = myid[0];
			tagToTXDocument(trno);
			break;

		default:
			// WTODO JAD 03-15-2019
			varstorage.removeData('doctype');

			var docno = $(this).attr('id');
			$('#modal-docnolookup').modal('hide');
			ajaxSearchDoc(docno);
			break;
	} //end switch case
}, 300));
