function retrievePDinfo(params) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/getpdinfo', {
		trno: params['trno'],
		docno: params['docno'],
		wh: params['wh']
	}, function (data) {

		var strhtml = "";
		$.each(data.primarydata, function (orderindx, orderinfo) {
			var line = $('.bodytable tr').length;
			if (data.primarydata[orderindx]['trno'] != null && data.primarydata[orderindx]['trno'] != "") {
				var datapassed = {
					primarydata: {
						0: data.primarydata[orderindx]
					}
				};
				addStockitem(line, datapassed, data.primarydata[orderindx]['rrqty']);
			} //end if null
		}); //end each
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end retrievePDINFO


