$(document).on('click', '.btncustomerlookup', debounce(function () {
	var moduleid = $('#moduleid').val(),
		ccode = $(this).attr('id');
	switch (moduleid) {
		case 'MX':
			var type = 'warehouse';
			break;
		case 'scheduler':
			var type = 'customer_scheduler';
			break;
		case 'GJ':
		case 'PV':
		case 'CV':
		case 'AR':
			var type = 'customer_supplier';
			break;
		case 'pscheme':
			var type = 'branch';
			break;
		default:
			var type = 'customer';
			break;
	}

	switch (moduleid) {
		case 'GJ':
		case 'PV':
		case 'CV':
		case 'AP':
			var client = $(this).attr('client'),
				clientname = $(this).attr('clientname'),
				lookuptype = $('body').data('coalookuptype');
			if (lookuptype == 'COADETAILPLOT') {
				$('.coaclienttxt').val(client);
				$('.coaclientnametxt').val(clientname);
			} else {
				$('.txtclientcodeunpaid').val(client);
			}
			$('body').data('coalookuptype', '');
			break;
		case 'CR':
		case 'KR':
			var lookuptype = $('body').data('coalookuptype');
			if (lookuptype == 'unpaidclient') {
				var client = $(this).attr('client');
				$('.txtclientcodeunpaid').val(client);
			} else if (lookuptype == 'COADETAILPLOT') {
				var clientname = $(this).attr('clientname'),
					client = $(this).attr('client');
				$('.coaclientnametxt').val(clientname);
				$('.coaclienttxt').val(client);
			} else {
				getmoduleClientdata(ccode, type);
			}
			break;

		case 'CK':
			var lookuptype = $('body').data('lookuptype');
			if (lookuptype == 'gridclient') {
				var client = $(this).attr('client'),
					clientname = $(this).attr('clientname'),
					trid = $('body').data('clientid'),
					prevclient = $('body').data('prevclient');
				if (client != prevclient) {
					var parentrow = $('#ckstockview #gvrow-' + trid);
					stockview.changeRowColor(parentrow);
				}
				$('#ckstockview #gvrow-' + trid + ' input[coltype=client]').val(client);
				$('#ckstockview #gvrow-' + trid + ' input[coltype=clientname]').val(clientname);
			} else {
				getmoduleClientdata(ccode, type);
			}
			break;

		case 'customer':
			var type = $('body').data('lookuptype'),
				client = $(this).attr('client');
			switch (type) {
				case 'unpaidclient':
					$('.txtclientcodeunpaid').val(client);
					break;

				case 'groupcodeplot':
					$('.txtclientgrpcode').val(client);
					break;

				default:
					getmoduleClientdata(ccode, type);
					break;
			} //end switch
			varstorage.removeData('lookuptype');
			break;

		case 'stockcard':
			var client = $(this).attr('client');
			var clientname = $(this).attr('clientname');

			$('.txtcustomerstockcard').val(client + '~' + clientname);
			break;

			//JAOSKIMOD: Added 3/10/2018 10:53:57 AM 
			//ADD SWITCH CASE FOR PLOTTING OF CUSTOMER LOOKUP ON REPORTLIST
		case 'reportlist':
			var client = $(this).attr('client');
			var clientname = $(this).attr('clientname');

			$('.reporttxtclientcode').val(client);
			//REMOVE THIS AFTER PATCHING FOR OTHER REPORTS
			$('.reporttxtclientname2').val(clientname);
			$('.reporttxtclientcode2').val(client);
			break;

		default:
			getmoduleClientdata(ccode, type);
			break;
	}
	$('#modal-clientlookup').modal('hide');
}, 300));

$(document).on('click', '.btnsupplierlookup', debounce(function () {
	var lookuptype = $('body').data('lookuptype');
	if (lookuptype == 'REPORTPLOT') {
		var ccode = $(this).attr('code');
		var cclient = $(this).attr('clientname');
		$('.reporttxtclientcode').val(ccode);
		$('.reporttxtclientcode3').val(ccode);
		$('.reporttxtclientname3').val(cclient);
	} else if (lookuptype == 'unpaidclient') {
		var ccode = $(this).attr('code');
		$('.txtclientcodeunpaid').val(ccode);
	} else if (lookuptype == 'COADETAILPLOT') {
		var ccode = $(this).attr('code'),
			clientname = $(this).attr('clientname');
		$('.coaclientnametxt').val(clientname);
		$('.coaclienttxt').val(ccode);
	} else if (lookuptype == 'USERACCSUP') {
		var ccode = $(this).attr('code');
		$('#suppname').val(ccode);
	} else if (lookuptype == 'WHCLIENT') {
		var ccode = $(this).attr('code');
		var cclient = $(this).attr('clientname');
		$('.txtclientcode').val(ccode);
		$('.txtclientname').val(cclient);
		$('.txtwarehouseview').val(ccode + '~' + cclient);
		$('.txtwarehouse').val(ccode + '~' + cclient);
	} else {
		var ccode = $(this).parent().parent().attr('id'),
			moduleid = $('#viewmoduleid').val(),
			type = '';
		ccode = ccode.split('-');
		ccode = ccode[1];
		if (moduleid == 'GJ') {
			type = $(this).attr('type');
		} else {
			type = 'supplier';
		}
		if (moduleid == 'itemprofile') {
			getfaSupplierData(ccode, type);
		} else {
			getmoduleClientdata(ccode, type);
		}
	} //end if
	$('#modal-supplier').modal('hide');
}, 300));

