function getmoduleClientdata(ccode, type) {
	var moduleid = $('#viewmoduleid').val();
	$('#overlay').css('display', 'block');
	$('.coaplotbtn').prop('disabled', true);
	$.get(domain + '/' + moduleid + '/getclientinfo', {
		clientid: ccode,
		type: type
	}, function (data) {

		var strMsg = "";

		if (moduleid == "SJ") {
			strMsg = data.clientdata[0]['crlimit_msg'];
		}

		if (strMsg != '' && strMsg != null) {
			generateAlert('error', strMsg, 'ERROR');
		} else {
			switch (moduleid) {
				case 'lanemanager':
					var line = featureditemline;
					featureditemline = "";
					$('#fitempic-' + line).prop('src', data.clientdata['head'][0]['picture']);
					$('#fitembarcode-' + line).val(data.clientdata['head'][0]['barcode']);
					break;
				case 'customer':
					$('#overlay').css('display', 'none');
					plottingClientData(data.clientdata, 'view');
					break;

				case 'supplier':
					$('#overlay').css('display', 'none');
					plottingSupplierData(data.clientdata, 'view');
					break;

				case 'branch':
					$('#overlay').css('display', 'none');
					plottingBranchData(data.clientdata, 'view');
					break;

				case 'assetmaster':
					$('#overlay').css('display', 'none');
					plottingAssetData(data.clientdata, 'view');
					break;

				case 'agent':
					$('#overlay').css('display', 'none');
					plottingAgentData(data.clientdata, 'view');
					break;

				case 'warehouse':
					$('#overlay').css('display', 'none');
					plottingWarehouseData(data.clientdata, 'view');
					break;

				case 'location':
					$('#overlay').css('display', 'none');
					plottingLocationData(data.clientdata, 'view');
					break;

				case 'vendor':
					$('#overlay').css('display', 'none');
					plottingVendorData(data.clientdata, 'view');
					break;

				case 'stockcard':
				case 'itemprofile':
				case 'posstockcard':
					$('#overlay').css('display', 'none');
					plottingItemData(data.clientdata, 'view');
					break;

				case 'FG':
					$('.txtfgcustomercode').val(data.clientdata[0]['client']);
					$('.txtclientname').val(data.clientdata[0]['clientname']);
					break;

				default:
					var type = $('body').data('clientlookuptype');
					// var type = $('.clientlookuptype').val();
					switch (type) {
						case 'CUSTOMERDETAIL':
							$('#edittxtclient-' + $('#lines').val()).val(data.clientdata[0]['client']);
							$('#edittxtclientname-' + $('#lines').val()).val(data.clientdata[0]['clientname']);
							$('#overlay').css('display', 'none');
							break;

						case 'COADETAILPLOT':
							$('.coaclientnametxt').val(data.clientdata[0]['clientname']);
							$('.coaclienttxt').val(data.clientdata[0]['client']);
							$('#overlay').css('display', 'none');
							break;

						case 'REPORTPLOT':
							$('.reporttxtclientcode').val(data.clientdata[0]['client']);
							$('#overlay').css('display', 'none');
							break;

						case 'CALENDARPLOTNEW':
							$('.calendarclientcode1').val(data.clientdata[0]['client']);
							$('#overlay').css('display', 'none');
							break;

						case 'CALENDARPLOTUPDATE':
							$('.calendarclientcode2').val(data.clientdata[0]['client']);
							$('#overlay').css('display', 'none');
							break;

						default:
							$('.txtclientname').val(data.clientdata[0]['clientname']);
							$('.txtclientcode').val(data.clientdata[0]['client']);

							if (data.clientdata[0]['agentcode'] == "" || data.clientdata[0]['agentcode'] == null) {
								switch (cconfig) {
									case 'UNIVERSE':
										if ($('.txtagentcode').val() == "") {
											$('.txtagentcode').val('');
											$('.txtagentcodeview').val('');
										} //end if
										break;

									default:
										$('.txtagentcode').val('');
										$('.txtagentcodeview').val('');
										break;
								} //end switch
							} else {
								$('.txtagentcode').val(data.clientdata[0]['agentcode'] + '~' + data.clientdata[0]['agent']);
								$('.txtagentcodeview').val(data.clientdata[0]['agentcode'] + '~' + data.clientdata[0]['agent']);
							} //end if

							$('.txtclientcodeview').val(data.clientdata[0]['client']);
							$('.txtclientaddress').val(data.clientdata[0]['addr']);
							$('.txtterms').val(data.clientdata[0]['terms']);
							$('.txttermsview').val(data.clientdata[0]['terms']);
							$('#overlay').css('display', 'none');
							if (data.clientdata[0]['terms'] != null || data.clientdata[0]['terms'] != "") {
								switch (moduleid) {
									case 'PO':
									case 'RR':
									case 'SO':
									case 'SJ':
									case 'QA':
										computeDuedate($('.txtterms').val(), $('.txtdateid').val());
										break;
								} //end switch
							}
							break;
					} //end switch

					$('.clientlookuptype').val('');
					break;
			} //end case
		} //end if
		$('.coaplotbtn').prop('disabled', false);
		$('#overlay').css('display', 'none');
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //END AJAX
} //end getmoduleclientdata

