function ajaxSearchClient(client) {
	disableForm();
	enableHeadbuttons();
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/searchdocno', {
		client: client
	}, function (data) {

		$('.modulebody').html('');
		if (data.clientdata['clientid'] == null || data.clientdata['clientid'] == '') {
			enableForm();
			$('.acctgdateid').css('display', 'none');
			plottingClientLookup(data.clientdata, 'view');
		} else {
			$('.acctgdateid').css('display', 'block');
			plottingClientLookup(data.clientdata, 'view');
		}
		$('#overlay').css('display', 'none');
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //END AJAX
} //AJAX SEARCH DOCNO

