function ajaxSearchDoc(docno) {
	arrayofvalues = {};
	disableForm();
	enableHeadbuttons();
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/searchdocno', {
		docno: docno
	}, function (data) {


		if (data.access == 0) {
			$('#overlay').css('display', 'none');
			generateAlert('error', 'Invalid Access , Please consult your administrator', 'ERROR');
			switch (moduleid) {
				case 'customer':
				case 'supplier':
				case 'agent':
				case 'warehouse':
				case 'vendor':
				case 'location':
				case 'assetmaster':
					loadlastClient();
					break;

					//EMPLOYEE
				case 'employee':
					loadlastEmployee();
					break;

				default:
					loadLastdocument();
					break;
			} //end swtich
		} else {
			if (data.moduledata['error_msg'] == "") {
				$('#overlay').css('display', 'none');
				switch (moduleid) {
					case 'assetmaster':
						$('#overlay').css('display', 'none');
						plottingAssetData(data.moduledata, 'view');
						break;
					case 'customer':
						$('#overlay').css('display', 'none');
						plottingClientData(data.moduledata, 'view');
						break;

					case 'supplier':
						$('#overlay').css('display', 'none');
						plottingSupplierData(data.moduledata, 'view');
						break;

						//EMPLOYEE
					case 'employee':
						$('#overlay').css('display', 'none');
						plottingEmployeeData(data.moduledata, 'view');
						break;

					case 'agent':
						$('#overlay').css('display', 'none');
						plottingAgentData(data.moduledata, 'view');
						break;

						//KEYWORD LOCATION&VENDOR
					case 'location':
						$('#overlay').css('display', 'none');
						plottingLocationData(data.moduledata, 'view');
						break;

					case 'vendor':
						$('#overlay').css('display', 'none');
						plottingVendorData(data.moduledata, 'view');
						break;
						//KEYWORD LOCATION&VENDOR

					case 'warehouse':
						$('#overlay').css('display', 'none');
						plottingWarehouseData(data.moduledata, 'view');
						break;

					case 'stockcard':
					case 'itemprofile':
						$('#overlay').css('display', 'none');
						plottingItemData(data.moduledata, 'view');
						break;

					case 'FG':
						$('#overlay').css('display', 'none');
						plottingItemData2(data.moduledata, 'view');
						break;

					default:
						//CONFI UPDATE - JAOSKI
						switch (moduleid) {
							case 'PO':
							case 'SP':
							case 'PR':
							case 'DM':
								if (data.moduledata['head']['groupid'] == 'CONFI') {
									if (confiaccess == 1) {
										$('#overlay').css('display', 'none');
										plottingModuleData(data.moduledata, 'view');
									} else {
										generateAlert('error', data.moduledata['head']['docno'] + ' is a CONFIDENTIAL DOCUMENT!<br>Loading last available document!', 'ERROR');
										loadLastdocument();
									} //end if
								} else {
									$('#overlay').css('display', 'none');
									plottingModuleData(data.moduledata, 'view');
								} //end if
								break;

							default:
								$('#overlay').css('display', 'none');
								plottingModuleData(data.moduledata, 'view');
								break;
						} //end switch
						break;
				} //END SWITCH
			} else {
				$('#overlay').css('display', 'none');
				generateAlert('error', data.moduledata['error_msg'], 'ERROR');
				switch (moduleid) {
					case 'customer':
					case 'supplier':
					case 'agent':
					case 'warehouse':
						loadlastClient();
						break;

						//EMPLOYEE
					case 'employee':
						loadlastEmployee();
						break;

					default:
						loadLastdocument();
						break;
				} //end swtich
			} //end if
		} //END IF
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //END AJAX
} //AJAX SEARCH DOCNO

