function getButtonactions(moduleid, btnaction, params) {
	arrayofvalues = {};
	disableForm();
	if ($(".module-btnheadcollapse").hasClass('stockedting')) {
		$('#overlay').css('display', 'block');
		$(".module-btnheadcollapse").trigger("click");
	}
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/navbuttons', {
			action: btnaction,
			params: params
		},
		function (data) {

			switch (moduleid) {
				case 'customer':
					$('#overlay').css('display', 'none');
					plottingClientData(data.customerdata, 'view');
					break;

				case 'assetmaster':
					$('#overlay').css('display', 'none');
					plottingAssetData(data.customerdata, 'view');
					break;

				case 'branch':
					$('#overlay').css('display', 'none');
					plottingBranchData(data.customerdata, 'view');
					break;

				case 'supplier':
					$('#overlay').css('display', 'none');
					plottingSupplierData(data.customerdata, 'view');
					break;

				case 'agent':
					$('#overlay').css('display', 'none');
					plottingAgentData(data.customerdata, 'view');
					break;

				case 'location':
					$('#overlay').css('display', 'none');
					plottingLocationData(data.customerdata, 'view');
					break;

				case 'vendor':
					$('#overlay').css('display', 'none');
					plottingVendorData(data.customerdata, 'view');
					break;

				case 'employee':
					$('#overlay').css('display', 'none');
					plottingEmployeeData(data.customerdata, 'view');
					break;

				case 'warehouse':
					$('#overlay').css('display', 'none');
					plottingWarehouseData(data.customerdata, 'view');
					break;

				case 'FG':
					plottingItemData2(data.itemdata, 'view');
					break;

				case 'stockcard':
				case 'itemprofile':
				case 'posstockcard':
					$('#overlay').css('display', 'none');
					plottingItemData(data.itemdata, 'view');
					break;

				default:
					$('#overlay').css('display', 'none');
					plottingModuleData(data.moduledata, 'view');
					break;
			} //end case
		}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //END GET FUNCTION
} //END Button Action

