function plottingItemData2(itemdata, type) {
	$.each(itemdata['head'][0], function (col, val) {
		$('.moduletxt').each(function () {
			if ($(this).attr('name') == col) {
				switch (col) {
					case 'fg_jowidthuom':
					case 'fg_jolengthuom':
					case 'fg_thicknessuom':
					case 'fg_actualwidthuom':
					case 'fg_actuallengthuom':
					case 'fg_treatment':
					case 'fg_repeatlengthuom':
					case 'fg_bfilmwidthuom':
					case 'fg_thickness2uom':
						$(this).html('<option>' + val + '</option>');
						break;

					default:
						$(this).val(val);
						break;
				} //end switch
			} //end if
		});
	});

	loadavailableFGUnit();
	loadavailableFGUnit_Microns();
	$('.txtitemid').html("Item ID: " + itemdata['head'][0]['itemid']);
	$('input[name=fg_customer]').val(itemdata['head'][0]['fgcustomer']).attr('fg_customer', itemdata['head'][0]['fg_customer']);
	$('#fgcolortab').click();
	$('#overlay').hide();
} //end fn

