$(document).on('click', '.selectuompop', function () {
	var moduleid = $('#viewmoduleid').val();
	var itemid = $('#itemid').val();
	$('#modal-uomlookup').modal();
	varstorage.data('uom-plotlocation', 'STOCKUOMHEAD');
	var multivoid = new GridViewGenerator(domain + '/' + moduleid + '/uomlookup', '.uomlookuptbl');
	multivoid.initializeGrid(itemid);
	$(".uomformnew").css('display', 'none');
});

$(document).on('click', '.fg_selectuompop', function () {
	var moduleid = $('#viewmoduleid').val();
	var itemid = $('#itemid').val();
	$('#modal-uomlookup').modal();

	varstorage.data('uom-plotlocation', 'FG_HEAD');
	varstorage.data('uom-plotFG', $(this).parent().siblings('.moduletxt'));

	var multivoid = new GridViewGenerator(domain + '/' + moduleid + '/uomlookup', '.uomlookuptbl');
	multivoid.initializeGrid(itemid);
	$(".uomformnew").css('display', 'none');
});



