$(document).on('click', '.module-btnsave', debounce(function () {
	verifyaccess('save', function (data) {
		if (data) {
			var moduleid = $('#viewmoduleid').val();
			switch (moduleid) {
				case 'stockcard':
				case 'posstockcard':
					switch (cconfig) {
						case 'DAVIDSALON_JOY':
							if ($('.txtcategory').val() == '') {
								generateAlert('error', 'Category required for [POS Items]!', 'ERROR');
							} else {
								saveModulehead();
							} //end switch
							break;

						default:
							saveModulehead();
							break;
					} //end switch
					break;

				case 'SO':
				case 'SJ':
				case 'CM':
					switch (cconfig) {
						case 'KINGGEORGE':
							if ($('.moduletxt.txtterms').val() == '') {
								generateAlert('error', 'Terms required for [Sales Modules]!', 'ERROR');
							} else {
								saveModulehead();
							} //end switch
							break;

						default:
							saveModulehead();
							break;
					} //end switch
					break;

				default:
					saveModulehead();
					break;
			} //end switch
		} else {
			generateAlert('error', 'Invalid Access!', 'ERROR');
		}
	});
}, 300));

$(document).on('click', '.module-btnheadcollapse', debounce(function () {
	if ($('.module-btnheadcollapse').hasClass("headediting")) { //IF EDITING HEAD THEN DISABLES HEAD FUNCTIONS x
		$('.orderbtns').css('display', 'inline');
		disableHeadbuttons();
		$('.btn-navs').css('display', 'none');
		$('#mindocno').css('display', 'inline');
		$('.module-btnheadcollapse').addClass('stockedting');
		$('.module-btnheadcollapse').removeClass('headediting');
	} else { //################################################# IF EDITING HEAD THEN DISABLES STOCK FUNCTIONS
		$('.orderbtns').css('display', 'none');
		enableHeadbuttons();
		$('.btn-navs').css('display', 'inline');
		$('#mindocno').css('display', 'none');
		$('.module-btnheadcollapse').removeClass('stockedting');
		$('.module-btnheadcollapse').addClass('headediting');
		var moduleid = $('#viewmoduleid').val();
		$('#modulestockview.' + moduleid).prop('checked', false);
	} //END IF
	stockview.saveAllButtons('hide');
	$('#overlay').css('display', 'none');
}, 300));

$(document).on('click', '.module-btnedit', debounce(function () {
	var moduleid = $('#viewmoduleid').val();
	verifyaccess('edit', function (data) {
		if (data) {
			$('.modulehead').addClass('saveable');
			$('.stockbtn').prop('disabled', true);
			$('.jaox').css('display', 'none');
			$('.stock-btnadd').css('display', 'none');
			$('.stock-btnquickadd').css('display', 'none');
			switch (moduleid) {
				case 'TR':
				case 'TS':
					loadAvailablePriceGrp();
					break;

				case 'agent':
					loadAvailablePriceGrp();
					break;

				case 'customer':
					loadAvailablePriceGrp();
					loadAvailableClientStatus();
					loadAvailableVattype();
					loadAvailableSalestype();
					break;

				case 'stockcard':
				case 'posstockcard':
					autohideObjectsonEdit('stockcard');
					loadAvailableWarranty();
					loadAvailableWarrantyPeriodExt();
					if (moduleid == 'posstockcard') {
						loadUOMnFactor();
					} //end if

					loadavailableFGUnit();
					loadavailableFGUnit_Microns();
					break;

				case 'SJ':
				case 'SJ2':
					loadAvailableVattype();
					loadAvailableSalestype();
					loadTranstype();
					break;

				case 'SO':
				case 'pscheme':
				case 'PS':
					loadAvailableSalestype();
					loadAvailableTrnxtype();
					loadAvailableRectype();
					loadTranstype();
					break;

				case 'QA':
					loadAvailableSalestype();
					loadAvailableTrnxtype();
					loadAvailableRectype();
					break;

				case 'RR':
				case 'SP':
				case 'warehouse':
				case 'SV':
					loadAvailableVattype();
					loadAvailablePurchasetype();
					break;

				case 'JB':
					loadAvailableSalestype();
					loadAvailableTrnxtype();
					loadAvailablePriceType();
					break;

				case 'FG':
					loadavailableFGTreatment();
					loadavailableFGFilmDetails();
					loadavailableFGUnit();
					loadavailableFGUnit_Microns();
					break;
			} //end switch

			switch (moduleid) {
				case 'QA':
				case 'PR':
				case 'PO':
				case 'RR':
				case 'DM':
				case 'SO':
				case 'SJ':
				case 'CM':
				case 'IS':
				case 'PC':
				case 'TS':
				case 'AJ':
				case 'TR':
				case 'AP':
				case 'PV':
				case 'CV':
				case 'AR':
				case 'CR':
				case 'KR':
				case 'GJ':
				case 'DS':
					stockview.disabledGridviewEditing(true);
					break;
			}

			enableForm();

			if (moduleid == 'stockcard') {
				$('.moduletxt.txtuom').prop('disabled', true);
			} //end if

			switch (moduleid) {
				case 'SO':
				case 'SJ':
				case 'CM':
					if (cconfig == 'KINGGEORGE') {
						$('.termslookup').css('display', 'none');
						$('.termsview').css('display', 'none');
					} else {
						$('.termslookup').css('display', 'block');
						$('.termsview').css('display', 'none');
					} //end if
					break;
			} //end switch
		} else {
			generateAlert('error', 'Invalid Access!', 'ERROR');
		} //end if verfied
	});
}, 300));


