function deleteDocument(params) {
	$('#overlay').css('display', 'block');
	var moduleid = $('#viewmoduleid').val();
	var docnoval = params['docno'];
	$.get(domain + '/' + moduleid + '/deletedoc', {
		action: 'delete',
		params: params
	}, function (data) {
		if (data == "") {
			clearModuleForm();
			$('.modulebody').html('');
			$('.productioninstrutioncobj').css('display', 'none');
			$('.btn-navs').prop('disabled', true);
			$('.module-btnedit').css('display', 'none');
			$('.module-btnedit').removeClass('btnactive');
			$('.module-btnsave').css('display', 'none');
			$('.module-btnsave').removeClass('btnactive');
			$('.module-btnprint').css('display', 'none');
			$('.module-btnprint').removeClass('btnactive');
			$('.module-btndelete').css('display', 'none');
			$('.module-btndelete').removeClass('btnactive');
			$('.module-btnlock').css('display', 'none');
			$('.module-btnlock').removeClass('btnactive');
			$('.module-btnunlock').css('display', 'none');
			$('.module-btnunlock').removeClass('btnactive');
			$('.module-btnunpost').css('display', 'none');
			$('.module-btnunpost').removeClass('btnactive');
			$('.module-btnpost').css('display', 'none');
			$('.module-btnpost').removeClass('btnactive');
			$('.module-btnlogs').css('display', 'none');
			$('.module-btnlogs').removeClass('btnactive');
			$('.stock-btnadd').prop('disabled', true);
			$('.stock-btnquickadd').prop('disabled', true);
			$('#overlay').css('display', 'none');
			$('.multiplevoidbtn').prop('disabled', true);
			$('.multiplevoidbtn').css('display', 'none');
			generateAlert('warning', "<b>Document " + docnoval + " has been deleted</b>", 'DEFAULT');
			$('.jaox').css('display', 'none');
		} else {
			if (data.istransposted) {
				var docno = $('.txtdocno').val();
				generateAlert('error', "Error modifying transaction data. <br> transaction <b>" + docno + "</b> is already posted. Data will be refreshed.", 'ERROR');
				ajaxSearchDoc(docno);
			} else {
				if (data.moduledata['head']['trno'] == null) {
					clearModuleForm();
					$('.modulebody').html('');
					$('.productioninstrutioncobj').css('display', 'none');
					$('.btn-navs').prop('disabled', true);
					$('.module-btnedit').css('display', 'none');
					$('.module-btnedit').removeClass('btnactive');
					$('.module-btnsave').css('display', 'none');
					$('.module-btnsave').removeClass('btnactive');
					$('.module-btnprint').css('display', 'none');
					$('.module-btnprint').removeClass('btnactive');
					$('.module-btndelete').css('display', 'none');
					$('.module-btndelete').removeClass('btnactive');
					$('.module-btnlock').css('display', 'none');
					$('.module-btnlock').removeClass('btnactive');
					$('.module-btnunlock').css('display', 'none');
					$('.module-btnunlock').removeClass('btnactive');
					$('.module-btnunpost').css('display', 'none');
					$('.module-btnunpost').removeClass('btnactive');
					$('.module-btnpost').css('display', 'none');
					$('.module-btnpost').removeClass('btnactive');
					$('.module-btnlogs').css('display', 'none');
					$('.module-btnlogs').removeClass('btnactive');
					$('.stock-btnadd').prop('disabled', true);
					$('.stock-btnquickadd').prop('disabled', true);
					$('#overlay').css('display', 'none');
					$('.multiplevoidbtn').prop('disabled', true);
					$('.multiplevoidbtn').css('display', 'none');
					generateAlert('warning', "<b>Document " + docnoval + " has been deleted</b>", 'DEFAULT');
					$('.jaox').css('display', 'none');
					$('#modulestockview').html('');
				} else {
					plottingModuleData(data.moduledata, 'view');
					$('.productioninstrutioncobj').css('display', 'block');
					generateAlert('warning', "<b>Document " + docnoval + " has been deleted</b>", 'DEFAULT');
				} //END IF MODULE DATA IS NULL
			}
		} //end if transposted
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end delete document

