function getSupplierPO(searchparam) {
	var moduleid = $('#viewmoduleid').val(),
		pickuptype = $('.pickup-po-format').val();

	switch (moduleid) {
		case 'customer':
			var clientcode = $('.txtclient').val(),
				whcode = '',
				whc = '';
			break;

		case 'TS':
			var clientcode = $('.txtclientcode').val(),
				whcode = $('.txtwarehouse').val().split('~'),
				whc = whcode[1];
			break;

		case 'PO':
			whcode = $('.txtwarehouse').val().split('~');
			var clientcode = whcode[1];
			break;

		default:
			var clientcode = $('.txtclientcode').val(),
				whcode = '',
				whc = '';
			break;
	}

	var strhtml = '';
	$('.tbl-pickpo-detail').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
	$('.tbl-pickpo-summary').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
	if (pickuptype == 'summary') {
		var supplierpo = new GridViewGenerator(domain + '/' + moduleid + '/requestclientposummary', '.pickpo');
	} else {
		var supplierpo = new GridViewGenerator(domain + '/' + moduleid + '/requestclientpodetailed', '.pickpo');
	}
	var addedparams = [];
	addedparams.push({
		name: "clientcode",
		value: clientcode
	});
	supplierpo.initializeGrid(searchparam, null, addedparams);
}

