function getOrderData() {
	var uv_sotagger = '';
	var qkey = $('.txtboxtrno').val();

	$('.theorderbutton').prop('disabled', true);
	var moduleid = $('#viewmoduleid').val(),
		returntype = $('.pickup-po-format').val(),
		row = 0,
		rowarr = [],
		rowid = 0,
		rowcount = 0,
		arr = [],
		rowline = 0,
		gridviewid = '';

	switch (moduleid) {
		case 'SJ':
			gridviewid = 'sjstockview';
			break;
		case 'CM':
			gridviewid = 'cmstockview';
			break;
		case 'RR':
			gridviewid = 'rrstockview';
			break;
		case 'PO':
			gridviewid = 'postockview';
			break;
		case 'DM':
			gridviewid = 'dmstockview';
			break;
		case 'TS':
			gridviewid = 'tsstockview';
			break;
		case 'MX':
			gridviewid = 'mxstockview';
			break;
		case 'SO':
			gridviewid = 'sostockview';
			break;
	}
	if (returntype == 'summary') {
		$('#clientposummarized tbody tr input.gridcheckbox:checked').each(function () {
			row += 1;
			rowid = $(this).parent().parent().attr('id');
			rowid = rowid.split('-');
			rowid = rowid[1];
			rowarr.push({
				name: 'rowid',
				value: rowid
			});

			if (cconfig == 'UNIVERSE') {
				if (moduleid == 'SJ') {
					uv_sotagger = rowid;
				} //end if
			} //end if
		});

		$.get(domain + '/' + moduleid + '/retrieveorderdatasummary', {
			params: rowarr
		}, function (data) {

			$.each(data.primarydata, function (arrkey, index) {
				rowcount = stockview.getTemprowIndex();
				stockview.addNewRow(gridviewid, rowcount);
				arr = [];
				arr['primarydata'] = index;
				stockview.plotNewRowData(rowcount, arr);

				if (cconfig == 'UNIVERSE') {
					if (moduleid == 'SJ') {
						uv_YourrefUpdater(qkey, uv_sotagger);
					} //end if
				} //end if
			});
			stockview.saveAllButtons('show');
		});
	} else {
		$('#clientpodetailed tbody tr input.gridcheckbox:checked').each(function () {
			row += 1;
			rowid = $(this).parent().parent().attr('id');
			rowid = rowid.split('-');
			rowid = rowid[1];
			rowline = $(this).parent().parent().find('td input[coltype=line]').val();
			rowarr.push({
				trno: rowid,
				line: rowline
			});

			if (cconfig == 'UNIVERSE') {
				if (moduleid == 'SJ') {
					uv_sotagger = rowid;
				} //end if
			} //end if
		});
		$.get(domain + '/' + moduleid + '/retrieveorderdatadetailed', {
			params: rowarr
		}, function (data) {

			$.each(data.primarydata, function (arrkey, index) {
				rowcount = stockview.getTemprowIndex();
				stockview.addNewRow(gridviewid, rowcount);
				arr = [];
				arr['primarydata'] = index;
				stockview.plotNewRowData(rowcount, arr);

				if (cconfig == 'UNIVERSE') {
					if (moduleid == 'SJ') {
						uv_YourrefUpdater(qkey, uv_sotagger);
					} //end if
				} //end if

			});
			stockview.saveAllButtons('show');
		});
	} //end if
	$('#modal-pick').modal('hide');
} //end get order



