$(document).on('click', '.stock-btnadd', debounce(function () {
	varstorage.data('itemlookuptype', 'DEFAULT');
	verifyaccess('clickadditem', function (data) {
		if (data) {
			var moduleid = $('#viewmoduleid').val();
			switch (moduleid) {
				case 'SP':
					switch (cconfig) {
						case 'UNIVERSE':
							$('.tbl-itemlookup').html('');
							$('#modal-itemlookup').modal();
							if ($(".module-btnheadcollapse").hasClass('headediting')) {
								$('#overlay').css('display', 'block');
								$(".module-btnheadcollapse").trigger("click");
							}
							$('#item-lookuptype').val("add");
							break;
						default:
							if ($('#doclookuptype').val() != '') {
								if ($('#doclookuptype').val() != 'RR_TO_SP') {
									$('#doclookuptype').val('RR_TO_SP');
									$('.tbl-modalsearch').html('');
								} //end if
							} else {
								$('#doclookuptype').val('RR_TO_SP');
							} //end if
							$('#modal-docnolookup').modal();
							break;
					} //end switch 2nd lvl
					break;


				case 'tpshipping':
				case 'tphandling':
					$('#modal-docnolookup').modal();
					$('body').data("doclookuptype", 'TPSHIP');
					$('#modal-docnolookup').css('z-index', '9999');
					$('.txtsearchdocno').trigger('keyup');
					break;


				case 'JB':
					$('.tbl-itemlookup').html('');
					$('#modal-itemlookup').modal();
					$('body').data('itemlookuptype', 'ITEM_FGLOOKUP');
					if ($(".module-btnheadcollapse").hasClass('headediting')) {
						$('#overlay').css('display', 'block');
						$(".module-btnheadcollapse").trigger("click");
					}
					$('#item-lookuptype').val("add");
					break;

				default:
					$('.tbl-itemlookup').html('');
					$('#modal-itemlookup').modal();
					if ($(".module-btnheadcollapse").hasClass('headediting')) {
						$('#overlay').css('display', 'block');
						$(".module-btnheadcollapse").trigger("click");
					}
					$('#item-lookuptype').val("add");

					if(moduleid == 'SJ' || moduleid == 'SO'){
						$('.itemlookup-customer-pricegrp-note').css('display','block');
						$('.itemlookup-customer-pricegrp').css('display','block');
						getCustomerPriceGroup(function(data){
							if(data.status){
								$('.itemlookup-customer-pricegrp-val').html(data.pricegrp);
							}//end fn
						});
					}else{
						$('.itemlookup-customer-pricegrp-note').css('display','none');
						$('.itemlookup-customer-pricegrp').css('display','none');
					}//end if
					break;
			} //end function
		} else {
			generateAlert('error', 'Invalid Access!', 'ERROR');
		} //end if verfied
	});
}, 300));

