$(document).on('click', '.searchcontrabtn', debounce(function () {
	var acnoid = $(this).attr('id'),
		acnoname = $(this).attr('acnoname'),
		acno = $(this).attr('acno'),
		alias = $(this).attr('alias'),
		lookuptype = $('body').data('coatype'),
		moduleid = $('#viewmoduleid').val(),
		client = $('.txtclientcode').val(),
		clientname = $('.txtclientname').val(),
		params = {
			lookuptype: lookuptype,
			alias: alias,
			acno: acno,
			acnoname: acnoname,
			acnoid: acnoid,
			refx: 0,
			linex: 0,
			client: client,
			clientname: clientname,
			postdate: '',
			ref: '',
			rem: '',
			db: 0.00,
			cr: 0.00
		};

	switch (moduleid) {
		case 'DS':
		case 'GJ':
		case 'AR':
		case 'CR':
		case 'AP':
		case 'PV':
		case 'CV':
			if (moduleid == 'CV' || moduleid == 'PV') {
				$('.coaclientnametxt').parent().parent().parent().find('h6').html('<b>Supplier:</b>');
			} else if (moduleid == 'CR') {
				$('.coaclientnametxt').parent().parent().parent().find('h6').html('<b>Customer:</b>')
			} else {
				$('.coaclientnametxt').parent().parent().parent().find('h6').html('<b>Cstmr/Supplr:</b>');
			}
			if (lookuptype == 'stock') {
				var row = $('body').data('parentrow');
				row.find('input[coltype=acno]').val(acno);
				row.find('input[coltype=acnoname]').val(acnoname);
				$('#modal-contra').modal('hide');
				row.css('background', stockview.editedcolor);
				row.addClass('edited');
				if (stockview.checkForSaveableRows()) {
					stockview.saveAllButtons();
				} else {
					stockview.saveAllButtons('hide');
				} //end if
			} else {
				if (moduleid == 'DS') {
					$('.coaclientlabel').parent().hide();
				} else {
					$('.coaclientlabel').parent().show();
				}
				var entryvalues = getAcctgEntrySum();

				//var nextval = parseFloat(entryvalues['db']) - parseFloat(entryvalues['cr']);
				//REVISED: by jaoski
				//When maximum digits of decimal exceeds to the maximum decimal that can be computed, value 
				//becomes an exponential value. - Revised (4/20/2018 4:37:16 PM by jaoski)
				//PATCHED: 12/9/2019 3:07:24 PM - JAOSKI from toPrecision() to toFixed()
				var nextval = parseFloat(entryvalues['db']).toFixed(amtdecimal) - parseFloat(entryvalues['cr']).toFixed(amtdecimal);

				if (nextval == 0) {
					params['db'] = 0.00;
					params['cr'] = 0.00;
				} else {
					if (nextval < 0) {
						params['db'] = nextval * -1;
						params['cr'] = 0.00;
					} else {
						params['db'] = 0.00;
						params['cr'] = nextval;
					}
				} //end if
				plotContra(params);
			}
			break;

		case 'branch':
			var contratype = $('body').data('contra-plotlocation');
			if (contratype == 'branchbank') {
				var rowcount = branchbankgrid.getTemprowIndex();
				branchbankgrid.addNewRow('branchbankgrid', rowcount);
				$('#branchbankgrid table tr#gvrow-' + rowcount + '.temprow').find('input[coltype=acno]').val(acno);
				$('body').data('contra-plotlocation', '');
			} else {
				$('.txtbranchacno, .txtbranchacnoview').val(acno);
			}
			$('#modal-contra').modal('hide');
			break;

		case 'quickcollect':
			$('.txtpaymenttype').val(acno + '~' + acnoname);
			$('#modal-contra').modal('hide');
			break;

		case 'colltype':
			var plothere = $('body').data('contra-plotlocation');
			$('#' + plothere + ' .collacno').val(acno);
			$('#' + plothere + ' .collacnoname').val(acnoname);
			$('body').removeData('contra-plotlocation');
			masterfilegrid.changeRowColor($('#' + plothere));
			$('#modal-contra').modal('hide');
			break;
		case 'reportlist':
			alert('xzxc');
			if (lookuptype == "CONTRABANK") {
				$('.txtcontrabank').val(acno);
				$('.txtcontrabankname').val(acnoname);
			} else {
				$('.txtcontra').val(acno);
			} //end if

			varstorage.removeData('coatype');
			$('#modal-contra').modal('hide');
			break;
		default:
			plotContra(params);
			break;
	}
}, 300));

$(document).on('click', '.coaplotbtn', debounce(function () {
	if (!$.isNumeric($('.coadb').val())) {
		$('.coadb').val('0');
	} //end if

	if (!$.isNumeric($('.coacr').val())) {
		$('.coacr').val('0');
	} //end if

	if ($('.coadb').val() != 0 && $('.coacr').val() != 0) {
		generateAlert('error', 'Invalid values, DB and CR must not have both values.', 'ERROR');
	} else {
		var acno = $('.coaacno').val(),
			acnoname = $('.coaacnoname').val(),
			client = $('.coaclienttxt').val(),
			postdate = $('.coapostdate').val(),
			checkno = $('.coacheckno').val(),
			ref = $('.coareference').val(),
			rem = $('.coanotes').val(),
			db = $('.coadb').val(),
			cr = $('.coacr').val();
		params = {
			acno: acno,
			acnoname: acnoname,
			client: client,
			postdate: postdate,
			checkno: checkno,
			db: db,
			cr: cr,
			rem: rem,
			ref: ref,
			line: 0,
			refx: 0,
			linex: 0,
			pdcline: 0
		};

		$('.coaacno').val('');
		$('.coaacnoname').val('');
		$('.coaclienttxt').val('');
		$('.coapostdate').val('');
		$('.coacheckno').val('');
		$('.coareference').val('');
		$('.coanotes').val('');
		$('.coadb').val('');
		$('.coacr').val('');

		var items = [],
			items2 = [];
		$.each(params, function (name, val) {
			item = {};
			item[name] = val;
			items.push(item);
		});
		var line = stockview.getTemprowIndex();
		items2['primarydata'] = items;

		addStockitem(line, items2, 0);
		$('#modal-entercoa').modal('hide');
	} //end if
}, 300));

