function plotContra(params) {
	var moduleid = $('#viewmoduleid').val();
	switch (params['lookuptype']) {

		case 'COAINFO':
			$('#overlay').css('display', 'block');
			getAcctgAttributes(params['acnoid']);
			$('#modal-contra').modal('hide');
			break;

		case 'ITEMASSET':
			$('.txtasset').val(params['acno']);
			$('#modal-contra').modal('hide');
			break;

		case 'ITEMLIAB':
			$('.txtliability').val(params['acno']);
			$('#modal-contra').modal('hide');
			break;

		case 'ITEMREV':
			$('.txtrevenue').val(params['acno']);
			$('#modal-contra').modal('hide');
			break;

		case 'CLIENTREV':
			$('.txtsalesaccnt').val(params['acno']);
			$('#modal-contra').modal('hide');
			break;

		case 'ITEMEXP':
			$('.txtexpense').val(params['acno']);
			$('#modal-contra').modal('hide');
			break;

		case 'DETAILPLOT':
			$('#modal-entercoa').modal();
			if (params['alias'] == "CB" || params['alias'] == "CR") {
				$('.coapostdatelbl').html('<h6><b>Check Date:</b></h6>');
				$('.coarowcheckno').css('display', 'block');
			} else {
				$('.coapostdatelbl').html('<h6><b>Post Date:</b></h6>');
				$('.coarowcheckno').css('display', 'none');
			} //end if

			if (moduleid == "AR" || moduleid == "AP") {
				$('.coaref').css('display', 'block');
			} else {
				$('.coaref').css('display', 'none');
			} //end if

			switch (moduleid) {
				case 'AP':
				case 'PV':
				case 'CV':
					$('.coaclientlabel').html('<h6><b>Supplier:</b></h6>');
					break;

				case 'AR':
				case 'CR':
					$('.coaclientlabel').html('<h6><b>Customer:</b></h6>');
					break;
			}

			$('.coapostdate').val($('.txtdateid').val());
			$('.coaclientnametxt').val(params['clientname']);
			$('.coaclienttxt').val(params['client']);
			$('.coaacnoid').val(params['acnoid']);
			$('.coaacnoname').val(params['acnoname']);
			$('.coaacno').val(params['acno']);
			$('.coadb').val(params['db']);
			$('.coacr').val(params['cr']);

			switch (cconfig) {
				case 'RTT':
					$('.coanotes').val($('.txtnotes').val());
					break;
			} //end if
			break;

		default:
			if (moduleid == 'DS') {
				$('.txtcontra').val(params['acno']);
				$('.txtbankcontraname').val(params['acnoname']);
			} else {
				$('.txtcontra').val(params['acno'] + '~' + params['acnoname']);
			} //end if
			$('.txtcontraview').val(params['acno'] + '~' + params['acnoname']);
			$('#modal-contra').modal('hide');
			break;
	} //END SWITCH
} //END PLOT CONTRA

