$(document).on('blur', '.txtcompute', function (event) {
	var parentrow = $(this).closest('tr');
	var vat = $('.txttax').val();

	var moduleid = $('#viewmoduleid').val();

	switch(moduleid){
		case 'SO': case 'SJ':
			if($(this).attr('name') == "isamt"){
				verifyaccess('changeamount', function (data) {
					if (data) {
						computeStock(parentrow, vat);
					} else {
						loadstockview(); 
						$( ".module-btnheadcollapse" ).trigger("click");
						generateAlert('error', 'Don`t have any access to change amount', 'ERROR');
					} //end if verfied
				});
			}else{
				computeStock(parentrow, vat);
			}//end if
		break;

		default:
			computeStock(parentrow, vat);
		break;
	}//end switch
});

$(document).on('click', '.selectuom', debounce(function () {
	var uom = $(this).attr('uom');
	var factor = $(this).attr('uomfactor');
	var vat = $('.txttax').val();
	switch (varstorage.data('uom-plotlocation')) {
		case 'POS_DETAILS':
			$(varstorage.data('uom-plotlocation_sp')).val(uom);
			$(varstorage.data('uom-plotlocation_sp2')).val(factor);
			varstorage.removeData('uom-plotlocation_sp');
			varstorage.removeData('uom-plotlocation_sp2');
			break;

		case 'STOCKUOMHEAD':
			$('.viewbyuom').val(uom);
			break;

		case 'VIEW_SHOWBAL':
			$('.showbal-viewuom').val(uom);
			getItembalance(varstorage.data('showbalance-itemid'), factor);
			break;

		case 'STOCKUOMBUTTOM':
			var line = varstorage.data('uom-plotlocation_line');
			$('#gvrow-' + line + ' input[coltype=uom]').val(uom);
			$('#gvrow-' + line + ' input[coltype=uomfactor]').val(factor);
			varstorage.removeData('uom-plotlocation_line');
			$('#gvrow-' + line).addClass('edited').css('background', componentmenugrid.editedcolor);
			break;

		case 'ADD_ITEM_SELECTION':
			$('.txtuomitem_add').val(uom);
			$('.txtuomfactoritem_add').val(factor);
			break;

		case 'REPORTPLOT':
			$('.uomtxt').val(uom);
			break;

		case 'FG_HEAD':
			varstorage.data('uom-plotFG').val(uom);
			varstorage.removeData('uom-plotFG');
			break;

		default:
			var parentrow = varstorage.data('uom-plotlocation');
			var parentid = parentrow.prop('id');

			if (varstorage.data('uom-plotlocation').hasClass('temprow')) {
				$('#' + parentid + '.temprow input[coltype="uom"]').val(uom);
				$('#' + parentid + '.temprow input[coltype="uomfactor"]').val(factor);
			} else {
				$('#' + parentid).addClass('edited').css('background', stockview.editedcolor);
				$('#' + parentid + ':not(.temprow) input[coltype="uom"]').val(uom);
				$('#' + parentid + ':not(.temprow) input[coltype="uomfactor"]').val(factor);
			} //end f

			//TODO: JAOSKIMODS (UOM COMPUTATIONS)
			var moduleid = $('#viewmoduleid').val();
			switch (moduleid) {
				case 'SO':
				case 'QA':
				case 'pscheme':
				case 'PS':
				case 'CM':
				case 'DM':
				case 'SJ2':
				case 'SJ':
				case 'TS':
				case 'MI':
				case 'MX':
					var txtobj = parentrow.children('td').children('input[coltype="isamt"]');
					var displayamt = txtobj.val().replace(/,/g, "");
					break;

				default:
					var txtobj = parentrow.children('td').children('input[coltype="rrcost"]');
					var displayamt = txtobj.val().replace(/,/g, "");
					break;
			}//end

			if (parseFloat(factor) > parseFloat(varstorage.data('prevstockuom'))) {
				var newamt = parseFloat(displayamt) * parseFloat(factor);
			} else {
				var newamt = parseFloat(displayamt) / parseFloat(varstorage.data('prevstockuom'));
			} //end if

			txtobj.val(newamt);

			varstorage.removeData('prevstockuom');
			computeStock(parentrow, vat);

			if (stockview.checkForSaveableRows()) {
				stockview.saveAllButtons();
			} else {
				stockview.saveAllButtons('hide');
			} //end f
			break;
	}
	varstorage.removeData('uom-plotlocation');
	modulemodals.popdown('modal-uomlookup');
}, 300));


$(document).on('click', '.stockcanceladdbtn', debounce(function () {
	var rowparent = $(this).closest("tr");
	removeStocktemprow(rowparent);
}, 300));


function computeStock(parentrow, vat) {
	if (typeof vat === "undefined" || vat === null) {
		vat = 0;
	} else {
		if (vat == "") {
			vat = 0;
		} else {
			vat = vat.replace(/,/g, "");
		}
	} //end if


	//TODO: CONTINUE 
	var moduleid = $('#viewmoduleid').val(),
		uomfactor = parentrow.children('td').children('input[coltype="uomfactor"]').val();

	switch (moduleid) {
		case 'RR':
		case 'PO':
		case 'DM':
			var forex = $('.txtforex').val();
			break;
		default:
			var forex = 1;
			break;
	} //end if


	var isqty = parentrow.children('td').children('input[coltype="isqty"]').val(),
		isamt = parentrow.children('td').children('input[coltype="isamt"]').val(),
		rrqty = parentrow.children('td').children('input[coltype="rrqty"]').val(),
		rrcost = parentrow.children('td').children('input[coltype="rrcost"]').val(),
		discount = parentrow.children('td').children('input[coltype="disc"]').val();

	$('#overlay').css('display', 'block');

	switch (moduleid) {

		case 'SO':
		case 'QA':
		case 'pscheme':
		case 'PS':
		case 'quotation':
		case 'QT':
		case 'JB':
			isamt = isamt.replace(/,/g, "");
			isqty = isqty.replace(/,/g, "");

			switch (cconfig) {
				case 'KINGGEORGE':
					var kgs = parentrow.children('td').children('input[coltype="kgs"]').val();
					var params = {
						displayamt: isamt,
						displayqty: isqty,
						disc: discount,
						uomfactor: uomfactor,
						kgs: kgs
					};
					break;

				default:
					var params = {
						displayamt: isamt,
						displayqty: isqty,
						disc: discount,
						uomfactor: uomfactor
					};
					break;
			} //end switch 

			$.get(domain + '/' + moduleid + '/computestock', params, function (data) {

				parentrow.children('td').children('input[coltype="qa"]').val(data.computeddata['qa']);
				parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
				parentrow.children('td').children('input[coltype="iss"]').val(data.computeddata['iss']);
				parentrow.children('td').children('input[coltype="amt"]').val(data.computeddata['amt']);
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			});
			break;

		case 'TR':
		case 'IS':
		case 'PC':
		case 'PR':
			rrcost = rrcost.replace(/,/g, "");
			rrqty = rrqty.replace(/,/g, "");

			switch (cconfig) {
				case 'KINGGEORGE':
					var kgs = parentrow.children('td').children('input[coltype="kgs"]').val();
					var params = {
						displayamt: rrcost,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor,
						kgs: kgs
					};
					break;

				default:
					var params = {
						displayamt: rrcost,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor
					};
					break;
			} //end switch 

			$.get(domain + '/' + moduleid + '/computestock', params, function (data) {

				parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
				parentrow.children('td').children('input[coltype="qty"]').val(data.computeddata['qty']);
				parentrow.children('td').children('input[coltype="cost"]').val(data.computeddata['cost']);
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			});
			break;

		case 'SP':
			switch (cconfig) {
				case 'UNIVERSE':

					rrcost = rrcost.replace(/,/g, "");
					rrqty = 1.00;

					$.get(domain + '/' + moduleid + '/computestock', {
						vat: vat,
						displayamt: rrcost,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor
					}, function (data) {

						parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
						parentrow.children('td').children('input[coltype="qty"]').val(data.computeddata['qty']);
						parentrow.children('td').children('input[coltype="cost"]').val(data.computeddata['cost']);
						$('#overlay').css('display', 'none');
					}).fail(function (jqXHR, textStatus, error) {
						generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
					});
					break;

				default:

					forex = forex.replace(/,/g, "");
					rrcost = rrcost.replace(/,/g, "");
					rrqty = rrqty.replace(/,/g, "");
					$.get(domain + '/' + moduleid + '/computestock', {
						vat: vat,
						forex: forex,
						displayamt: rrcost,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor
					}, function (data) {

						parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
						parentrow.children('td').children('input[coltype="qty"]').val(data.computeddata['qty']);
						parentrow.children('td').children('input[coltype="cost"]').val(data.computeddata['cost']);
						$('#overlay').css('display', 'none');
					}).fail(function (jqXHR, textStatus, error) {
						generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
					});
					break;
			}
			break; //SP

		case 'RR':
		case 'PO':
		case 'PI':
		case 'SP':
			forex = forex.replace(/,/g, "");
			rrcost = rrcost.replace(/,/g, "");
			rrqty = rrqty.replace(/,/g, "");

			switch (cconfig) {
				case 'KINGGEORGE':
					var kgs = parentrow.children('td').children('input[coltype="kgs"]').val();
					var params = {
						vat: vat,
						forex: forex,
						displayamt: rrcost,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor,
						kgs: kgs
					};
					break;

				default:
					var params = {
						vat: vat,
						forex: forex,
						displayamt: rrcost,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor
					};
					break;
			} //end switch 

			$.get(domain + '/' + moduleid + '/computestock', params, function (data) {

				parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
				parentrow.children('td').children('input[coltype="qty"]').val(data.computeddata['qty']);
				parentrow.children('td').children('input[coltype="cost"]').val(data.computeddata['cost']);
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			});
			break;

		case 'AJ':
		case 'PK':
			rrcost = rrcost.replace(/,/g, "");
			rrqty = rrqty.replace(/,/g, "");

			switch (cconfig) {
				case 'KINGGEORGE':
					var kgs = parentrow.children('td').children('input[coltype="kgs"]').val();
					var params = {
						displayamt: rrcost,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor,
						kgs: kgs
					};
					break;

				default:
					var params = {
						displayamt: rrcost,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor
					};
					break;
			} //end switch 

			$.get(domain + '/' + moduleid + '/computestock', params, function (data) {

				if (rrqty > 0) {
					parentrow.children('td').children('input[coltype="qty"]').val(data.computeddata['qty']);
					parentrow.children('td').children('input[coltype="ajiss"]').val(0);
				} else {
					parentrow.children('td').children('input[coltype="iss"]').val(data.computeddata['iss']);
					parentrow.children('td').children('input[coltype="qty"]').val(0);
				}
				parentrow.children('td').children('input[coltype="cost"]').val(data.computeddata['cost']);
				parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			});
			break;

		case 'CM':
			isamt = isamt.replace(/,/g, "");
			rrqty = rrqty.replace(/,/g, "");

			switch (cconfig) {
				case 'KINGGEORGE':
					var kgs = parentrow.children('td').children('input[coltype="kgs"]').val();
					var params = {
						displayamt: isamt,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor,
						kgs: kgs
					};
					break;

				default:
					var params = {
						displayamt: isamt,
						displayqty: rrqty,
						disc: discount,
						uomfactor: uomfactor
					};
					break;
			} //end switch 

			$.get(domain + '/' + moduleid + '/computestock', params, function (data) {

				parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
				parentrow.children('td').children('input[coltype="qty"]').val(data.computeddata['qty']);
				parentrow.children('td').children('input[coltype="amt"]').val(data.computeddata['amt']);
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			});
			break;

		case 'SJ':
		case 'TS':
		case 'MI':
		case 'MX':
			isamt = isamt.replace(/,/g, "");
			isqty = isqty.replace(/,/g, "");

			switch (cconfig) {
				case 'TENPLUS':
					switch (moduleid) {
						case 'SJ':
							if ($('.txtagentcode').val() == '' || $('.txtagentcode').val() == '~') {
								var computevars = {
									'displayamt': isamt,
									'displayqty': isqty,
									'disc': discount,
									'uomfactor': uomfactor,
									'itemhandling': '',
									'itemcomm': ''
								};
							} else {
								var str = $('.txtagentcode').val().split('~');
								var agcode = str[0];

								if (agcode == 'AG0000000000001') {
									var itemhandling = parentrow.children('td').children('input[coltype="itemhandling"]').val();
									var itemcomm = parentrow.children('td').children('input[coltype="itemcomm"]').val();
									var computevars = {
										'displayamt': isamt,
										'displayqty': isqty,
										'disc': discount,
										'uomfactor': uomfactor,
										'itemhandling': itemhandling,
										'itemcomm': itemcomm
									};
								} else {
									var computevars = {
										'displayamt': isamt,
										'displayqty': isqty,
										'disc': discount,
										'uomfactor': uomfactor,
										'itemhandling': '',
										'itemcomm': ''
									};
								} //END IF
							} //end if
							break;
					} //end switch
					break;

				case 'KINGGEORGE':
					var kgs = parentrow.children('td').children('input[coltype="kgs"]').val();
					var computevars = {
						'displayamt': isamt,
						'displayqty': isqty,
						'disc': discount,
						'uomfactor': uomfactor,
						kgs: kgs
					};
					break;

				default:
					var computevars = {
						'displayamt': isamt,
						'displayqty': isqty,
						'disc': discount,
						'uomfactor': uomfactor
					};
					break;
			} //end switch

			$.get(domain + '/' + moduleid + '/computestock', computevars, function (data) {

				parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
				parentrow.children('td').children('input[coltype="iss"]').val(data.computeddata['iss']);
				parentrow.children('td').children('input[coltype="amt"]').val(data.computeddata['amt']);
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			});
			break;

		case 'SJ2':
			isamt = isamt.replace(/,/g, "");
			isqty = isqty.replace(/,/g, "");
			isqty2 = isqty2.replace(/,/g, "");
			var isqty2 = $(txtclass + '#txtisqty2-' + line).val();
			$.get(domain + '/' + moduleid + '/computestock2', {
				displayamt: isamt,
				displayqty: isqty,
				displayqty2: isqty2,
				disc: discount,
				uomfactor: uomfactor
			}, function (data) {

				parentrow.children('td').children('input[coltype="iss2"]').val(data.computeddata['iss2']);
				parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
				parentrow.children('td').children('input[coltype="iss"]').val(data.computeddata['iss']);
				parentrow.children('td').children('input[coltype="amt"]').val(data.computeddata['amt']);
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			});
			break;

		case 'DM':
			forex = forex.replace(/,/g, "");
			isamt = isamt.replace(/,/g, "");
			isqty = isqty.replace(/,/g, "");

			switch (cconfig) {
				case 'KINGGEORGE':
					var kgs = parentrow.children('td').children('input[coltype="kgs"]').val();
					var params = {
						forex: forex,
						displayamt: isamt,
						displayqty: isqty,
						disc: discount,
						uomfactor: uomfactor,
						kgs: kgs
					};
					break;

				default:
					var params = {
						forex: forex,
						displayamt: isamt,
						displayqty: isqty,
						disc: discount,
						uomfactor: uomfactor
					};
					break;
			} //end switch 

			$.get(domain + '/' + moduleid + '/computestock', params, function (data) {

				parentrow.children('td').children('input[coltype="ext"]').val(data.computeddata['ext']);
				parentrow.children('td').children('input[coltype="iss"]').val(data.computeddata['iss']);
				parentrow.children('td').children('input[coltype="amt"]').val(data.computeddata['amt']);
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			});
			break;

		default:
			console.log("ERR_DEV_COMPUTATE: NO SWITCH MODULE FOR FOR COMPUTATION");
			break;
	}
}

