$(document).on('click', '.invoicesavebtn', debounce(function () {
	// console.log('qwe');
	var btnsave = $(this),
		parentrow = btnsave.parent().parent().prop('id'),
		savedarray,
		moduleid = $('#viewmoduleid').val();

	orig_stockarraydata = {};
	orig_detailarraydata = {};


	if (btnsave.parent().parent().hasClass('temprow') || btnsave.parent().parent().hasClass('edited')) {
		verifyaccess('save', function (data) {
			if (data) {

				if (btnsave.parent().parent().hasClass('temprow')) {
					var formvalues = $("#" + parentrow + ".temprow .bodytextbox").serializeArray();
				} else {
					var formvalues = $("#" + parentrow + ":not(.temprow) .bodytextbox").serializeArray();
				}

				savedarray = formvalues;

				var arrval = {};
				$.each(savedarray, function (indexx, datum) {
					arrval[datum['name']] = datum['value'];
				});

				orig_stockarraydata[parentrow] = arrval;

				saveStockpart(orig_stockarraydata, function (result) {

					saveStockResponse(result);
				});
			} else {
				generateAlert('error', 'Invalid Access!', 'ERROR');
			} //end if verfied
		});
	}
}, 300));

//SAVES ADDED ITEM ROW
$(document).on('click', '.stocksavebtn', debounce(function () {
	var btnsave = $(this),
		parentrow = btnsave.parent().parent().prop('id'),
		savedarray,
		moduleid = $('#viewmoduleid').val();
	var expirychecking = true;

	orig_stockarraydata = {};
	orig_detailarraydata = {};
	if (btnsave.parent().parent().hasClass('temprow') || btnsave.parent().parent().hasClass('edited')) {
		verifyaccess('save', function (data) {
			if (data) {
				if (btnsave.parent().parent().hasClass('temprow')) {
					var istemp = 1;
					var getstring = '.temprow';
				} else {
					var istemp = 0;
					var getstring = ':not(.temprow)';
				} //end if

				searchRowCheckboxes(parentrow, istemp);
				var formvalues = $("#" + parentrow + getstring + " .bodytextbox").serializeArray();

				formvalues.push({
					name: "trno",
					value: $('.txtboxtrno').val()
				});
				savedarray = formvalues;

				var arrval = {};
				$.each(savedarray, function (indexx, datum) {
					switch (cconfig) {
						case 'UNIVERSE':
							switch (moduleid) {
								case 'SO':
								case 'PO':
									expirychecking = true;
									break;

								default:
									if (datum['name'] == "expiry") {
										let strexpiry = datum['value'];
										if (strexpiry.match(/([12]\d{3}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01]))/)) {
											expirychecking = true;
										} else {
											expirychecking = false;
										} //end if
									} //end if
									break;
							} //end swithc
							break;
					} //END FN
					arrval[datum['name']] = datum['value'];
				});

				orig_stockarraydata[parentrow] = arrval;

				if (expirychecking) {
					saveStockpart(orig_stockarraydata, function (result) {
						saveStockResponse(result);
					});
				} else {
					generateAlert('error', 'Please enter a valid expiry date.', 'ERROR');
				} //end if
			} else {
				generateAlert('error', 'Invalid Access!', 'ERROR');
			} //end if verfied
		});
	}
}, 300));


