function removeStockitem(params) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/stockdelete', {
		line: params['index'],
		trno: params['trno']
	}, function (data) {

		if (data.istransposted) {
			var docno = $('.txtdocno').val();
			generateAlert('error', "Error modifying transaction data. <br> transaction <b>" + docno + "</b> is already posted. Data will be refreshed.", 'ERROR');
			ajaxSearchDoc(docno);
		} else {
			if (moduleid == 'KR') {
				$('#gvrow-' + params['trno'] + '-' + params['index']).remove();
			} //END IF

			$('#gvrow-' + params['index'] + ':not(.temprow)').remove();

			switch (moduleid) {
				case 'GJ':
				case 'CR':
				case 'PV':
				case 'CV':
				case 'AP':
				case 'AR':
				case 'DS':
					if (data.runningcr == null) {
						$('.txttotalcr').html("TOTAL CREDIT: 0.00");
					} else {
						$('.txttotalcr').html("TOTAL CREDIT: " + data.runningcr);
					}
					if (data.runningdb == null) {
						$('.txttotaldb').html("TOTAL DEBIT: 0.00");
					} else {
						$('.txttotaldb').html("TOTAL DEBIT: " + data.runningdb);
					}
					break;

				case 'TW':
					if (data.grandtotal == null) {
						$('.txtgrandtotal').html("GRAND TOTAL: 0.00");
					} else {
						$('.txtgrandtotal').html("GRAND TOTAL: " + data.grandtotal);
					}
					if (data.itemcount == null) {
						$('.txtitemcount').html("NUMBER OF ITEMS: 0");
					} else {
						$('.txtitemcount').html("NUMBER OF ITEMS: " + data.itemcount);
					}
					break;

				default:
					if (moduleid == 'RR') {
						if (data.forexgrandtotal == null) {
							$('.txtforexgrandtotal').html('FOREX: 0.00');
						} else {
							$('.txtforexgrandtotal').html('FOREX: ' + data.forexgrandtotal);
						}
					}
					if (data.itemcount == null) {
						$('.txtitemcount').html("NUMBER OF ITEMS: 0");
					} else {
						$('.txtitemcount').html("NUMBER OF ITEMS: " + data.itemcount);
					}

					if (data.grandtotal == null) {
						$('.txtgrandtotal').html("GRAND TOTAL: 0.00");
					} else {
						$('.txtgrandtotal').html("GRAND TOTAL: " + data.grandtotal);
					}

					if (data.totalcbm == null) {
						$('.txttotalcbm').html("TOTAL CBM: 0.00");
					} else {
						$('.txttotalcbm').html("TOTAL CBM: " + data.totalcbm);
					}
					if (data.totaltonnage == null) {
						$('.txttotaltonnage').html("TOTAL TONNAGE: 0.00");
					} else {
						$('.txttotaltonnage').html("TOTAL TONNAGE: " + data.totaltonnage);
					}

					if (data.totalkilo == null) {
						$('.txttotalkilo').html("TOTAL QTY: 0.00");
					} else {
						$('.txttotalkilo').html("TOTAL QTY: " + data.totalkilo);
					}
					break;
			} //end switch

			if (stockview.checkForSaveableRows()) {
				stockview.saveAllButtons();
			} else {
				stockview.saveAllButtons('hide');
			} //end if
		} //end if trans posted
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //END REMOVE STOCKITEM


