function posting(trno) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/post', {
		trno: trno
	}, function (data) {

		if (data.istransposted) {
			var docno = $('.txtdocno').val();
			generateAlert('error', "Error modifying transaction data. <br> transaction <b>" + docno + "</b> is already posted. Data will be refreshed.", 'ERROR');
			ajaxSearchDoc(docno);
		} else {
			if (data.status == "1") {
				if (data.isposted) {

					if (moduleid == "SJ") {
						$('.module-btnprint').css('display', 'none');
						$('.module-btnprint').removeClass('btnactive');
					} //end if

					$('.posted-flag').css('display', 'block');
					$('.module-btndelete, .module-btnunlock, .module-btnpost, .module-btnlock, .module-btnedit').css('display', 'none').removeClass('btnactive');
					$('.module-btnunpost, .module-adjust').css('display', 'block').addClass('btnactive');
					$('.stock-btnadd, .stock-btnquickadd, .detail-btnaddentries, .detail-btnunpaid, .detail-btncoalookup, .stock-btnPO, .detail-btnchecks').prop('disabled', true);

					$(stockview.initdiv).attr('poststatus', '1');

					switch (moduleid) {
						case 'JB':
							var docno = $('.txtdocno').val();
							showprocesstab.disabledGridviewEditing(true);
							showmaterialtab.disabledGridviewEditing(true);
							$('.jb_addmaterials').css('display', 'none');
							$('.jb_addprocess').css('display', 'none');
							$('.jb_generatemi').css('display', 'block');
							$('.jb_generatets').css('display', 'block');

							ajaxSearchDoc(docno);
							break;
					} //end switch

					switch (cconfig) {
						case 'SOUTHCENTRAL':
							if (data.isapproved == 1) {
								$('.approved-flag').css('display', 'block');
								$('.disapproved-flag').css('display', 'none');
							} else {
								$('.disapproved-flag').css('display', 'block');
								$('.approved-flag').css('display', 'none');
							}
							break;
					}
				}
				$('.stockcopybtns').prop('disabled', true);
				generateAlert('information', '<b>' + data.error_msg + '</b>', 'DEFAULT');
				$('#overlay').css('display', 'none');
				if (moduleid == 'CK' || moduleid == 'PO' || moduleid == 'SO') {
					$(stockview.initdiv + ' table tbody tr input[coltype=tr]').val('P');
					checkifvoidPosted();
				} else {
					stockview.disabledGridviewEditing(true);
				}
			} else {
				generateAlert('error', data.error_msg, 'ERROR');
				$('#overlay').css('display', 'none');
			}
		} //end if transposted
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //END FUNCTION POSTING

function unposting(trno) {
	var moduleid = $('#viewmoduleid').val();
	if (moduleid == 'PC') {
		if ($('.txtyourref').val() != '') {
			generateAlert('error', 'Sorry Already Adjusted...', 'ERROR');
			$('#overlay').css('display', 'none');
			return 0;
		} //end if
	} //end if

	$.get(domain + '/' + moduleid + '/unpost', {
		trno: trno
	}, function (data) {

		if (data.status == "1") {
			$('.posted-flag, .disapproved-flag, .approved-flag').css('display', 'none');

			if (moduleid == "SJ") {
				$('.module-btnprint').css('display', 'block');
				$('.module-btnprint').addClass('btnactive');
			} //end if

			if (data.islocked) {
				$('.module-btndelete, .module-btnedit, .module-btnlock').css('display', 'none').removeClass('btnactive');
				$('.module-btnunlock').css('display', 'block').addClass('btnactive');
				$('.stockbtn, .stockcopybtns').prop('disabled', true);
				$(stockview.initdiv).attr('poststatus', '0');
				$(stockview.initdiv).attr('lockedstatus', '1');

				switch (moduleid) {
					case 'JB':
						showprocesstab.disabledGridviewEditing(false);
						showmaterialtab.disabledGridviewEditing(false);
						$('.jb_addmaterials').css('display', 'inline');
						$('.jb_addprocess').css('display', 'inline');
						$('.jb_generatemi').css('display', 'none');
						$('.jb_generatets').css('display', 'none');
						$('.txtmatbarcode').val('');
						break;
				} //end switch

				if (moduleid == 'SO' || moduleid == 'PO') {
					$(stockview.initdiv + ' table tbody tr input[coltype=tr]').val('');
					checkifvoidPosted();
				} else {
					stockview.disabledGridviewEditing(true);
				} //end f
			} else {
				$('.stock-btnadd, .stock-btnquickadd, .detail-btnaddentries,.detail-btngenerateending, .detail-btnunpaid, .detail-btncoalookup, .stock-btnPO, .detail-btnchecks').prop('disabled', false);
				$('.module-btndelete, .module-btnedit, .module-btnlock').css('display', 'block').addClass('btnactive');
				$('.module-adjust').css('display', 'none');
				$('.module-btnunlock').css('display', 'none').removeClass('btnactive');
				$('.stockcopybtns').prop('disabled', false);
				$(stockview.initdiv).attr('poststatus', '0');
				$(stockview.initdiv).attr('lockedstatus', '0');

				switch (moduleid) {
					case 'JB':
						showprocesstab.disabledGridviewEditing(false);
						showmaterialtab.disabledGridviewEditing(false);
						$('.jb_addmaterials').css('display', 'inline');
						$('.jb_addprocess').css('display', 'inline');
						$('.jb_generatemi').css('display', 'none');
						$('.jb_generatets').css('display', 'none');
						$('.txtmatbarcode').val('');
						break;
				} //end switch

				if (moduleid == 'SO' || moduleid == 'PO') {
					$(stockview.initdiv + ' table tbody tr input[coltype=tr]').val('');
					checkifvoidPosted();
				} else {
					stockview.disabledGridviewEditing(false);
				}
			}
			// $('.multiplevoidbtn').prop("disabled",true);
			$('.module-btnpost').css('display', 'block').addClass('btnactive');
			$('.module-btnunpost').css('display', 'none').removeClass('btnactive');
			generateAlert('information', '<b>' + data.error_msg + '</b>', 'DEFAULT');
			$('#overlay').css('display', 'none');
		} else {
			generateAlert('error', data.error_msg, 'ERROR');
			$('#overlay').css('display', 'none');
		}
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
}


