function locking(trno) {
	var action = "lock";
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/lockunlock', {
		trno: trno,
		action: action
	}, function (data) {

		if (data.istransposted) {
			var docno = $('.txtdocno').val();
			generateAlert('error', "Error modifying transaction data. <br> transaction <b>" + docno + "</b> is already posted. Data will be refreshed.", 'ERROR');
			ajaxSearchDoc(docno);
		} else {
			if (data.error_msg == "") {
				$('#overlay').css('display', 'none');
				$('.module-btnlock').css('display', 'none');
				$('.module-btnlock').removeClass('btnactive');

				$('.module-btnunlock').css('display', 'block');
				$('.module-btnunlock').addClass('btnactive');

				$('.module-btnedit').css('display', 'none');
				$('.module-btnedit').removeClass('btnactive');

				$('.module-btndelete').css('display', 'none');
				$('.module-btndelete').removeClass('btnactive');

				$('.locked-flag').css('display', 'block');
				$('.stockbtn').prop('disabled', true);
				stockview.disabledGridviewEditing(true);
				$(stockview.initdiv).attr('lockedstatus', 1);

				switch (moduleid) {
					case 'JB':
						showprocesstab.disabledGridviewEditing(true);
						showmaterialtab.disabledGridviewEditing(true);
						$('.jb_addmaterials').css('display', 'none');
						$('.jb_addprocess').css('display', 'none');
						break;
				} //end switch

				$('.stockcopybtns').prop('disabled', true);
			} else {
				generateAlert('error', data.error_msg, 'ERROR');
				$('#overlay').css('display', 'none');
			}
		} //end if transposted
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end function locking

