$(document).on('click', '.stockaddthisitem', debounce(function () {
	var moduleid = $('#viewmoduleid').val();
	var itemid = $(this).attr('ukey');

	switch (moduleid) {
		case 'FG':
			switch ($('body').data('itemlookuptype')) {
				case 'ITEM_FGEQUIP':
					var fg_itemid = $('#itemid').val();
					var itemname = $(this).attr('itemname');

					insertinToFGEquipmentTab(fg_itemid, itemid, itemname);
					break;

				default:
					var barcode = $(this).attr('barcode');
					$('#modal-itemlookup').modal('hide');
					$('.txtbarcode').val(barcode);
					ajaxSearchDoc(barcode);
					break;
			} //end switch
			break;

		case 'managefdeals':
			$('#modal-flashsetprice').modal();
			$('#txtflashitemid_setprice').val(itemid);
			break;

		case 'fhighlights':
			insertItemToHighlight(itemid);
			break;

		case 'managedod':
			$('#modal-dodsetprice').modal();
			$('#txtdoditemid_setprice').val(itemid);
			$('#txtdoditemprice').val('0.00');
			break;

		case 'manageitem':
			var type = $('body').data('manageitemtype'),
				barcode = $(this).attr('barcode'),
				itemname = $(this).attr('itemname'),
				uom = $(this).attr('uom');

			if (type == 'component') {
				var rowcount = componentmenugrid.getTemprowIndex();
				componentmenugrid.addNewRow('componentitemsgrid', rowcount);
				$('#componentitemsgrid tr#gvrow-' + rowcount + '.temprow input[coltype=barcode]').val(barcode);
				$('#componentitemsgrid tr#gvrow-' + rowcount + '.temprow input[coltype=itemname]').val(itemname);
				$('#componentitemsgrid tr#gvrow-' + rowcount + '.temprow input[coltype=uom]').val(uom);
			} else if (type == 'addchoicemenu') {
				var itemname = $(this).attr('itemname');
				addchoicemenuitem(itemid, itemname);
			} else {

			}
			$('#modal-itemlookup').modal('hide');
			break;


		case 'quotation':
			var rowcount = stockview.getTemprowIndex();
			var line = $('body').data('line'),
				barcode = $(this).attr('barcode'),
				itemname = $(this).attr('itemname'),
				uom = $(this).attr('uom');

			$('#quotestockview tr#' + line + ' input[coltype=itemid]').val(itemid);
			$('#quotestockview tr#' + line + ' input[coltype=barcode]').val(barcode);
			$('#quotestockview tr#' + line + ' input[coltype=itemname]').val(itemname);
			$('#quotestockview tr#' + line + ' input[coltype=uom]').val(uom);
			$('#quotestockview tr#' + line + ' input[coltype=uomfactor]').val(1);
			stockview.changeRowColor($('#quotestockview tr#' + line));

			$('#modal-itemlookup').modal('hide');
			break;

		case 'posstockcard':
			var type = $('body').data('lookuptype');
			switch (type) {
				case 'docnolookup':
					getmoduleClientdata(itemid, 'item');
					$('#modal-itemlookup').modal('hide');
					break;

				case 'component':
					var rowcount = componentmenugrid.getTemprowIndex(),
						barcode = $(this).attr('barcode'),
						itemname = $(this).attr('itemname'),
						uom = $(this).attr('uom');
					componentmenugrid.addNewRow('componentitemsgrid', rowcount);
					$('#componentitemsgrid tr#gvrow-' + rowcount + '.temprow input[coltype=barcode]').val(barcode);
					$('#componentitemsgrid tr#gvrow-' + rowcount + '.temprow input[coltype=itemname]').val(itemname);
					$('#componentitemsgrid tr#gvrow-' + rowcount + '.temprow input[coltype=uom]').val(uom);
					$('#modal-itemlookup').modal('hide');
					break;

				default:
					var line = $('body').data('line'),
						barcode = $(this).attr('barcode'),
						itemname = $(this).attr('itemname'),
						uom = $(this).attr('uom');
					$('#itemcomponentsgrid tr#' + line + ' input[coltype=itemid]').val(itemid);
					$('#itemcomponentsgrid tr#' + line + ' input[coltype=barcode]').val(barcode);
					$('#itemcomponentsgrid tr#' + line + ' input[coltype=itemname]').val(itemname);
					$('#itemcomponentsgrid tr#' + line + ' input[coltype=uom]').val(uom);
					$('#modal-itemlookup').modal('hide');
					break;
			} //end switch
			break;

		case 'stockcard':
		case 'itemprofile':
		case 'lanemanager':
			var type = $('body').data('lookuptype');

			switch (type) {
				case 'docnolookup':
					getmoduleClientdata(itemid, 'item');
					$('#modal-itemlookup').modal('hide');
					break;

				case 'component':
					var rowcount = componentmenugrid.getTemprowIndex(),
						barcode = $(this).attr('barcode'),
						itemname = $(this).attr('itemname'),
						uom = $(this).attr('uom');
					componentmenugrid.addNewRow('componentitemsgrid', rowcount);
					$('#componentitemsgrid tr#gvrow-' + rowcount + '.temprow input[coltype=barcode]').val(barcode);
					$('#componentitemsgrid tr#gvrow-' + rowcount + '.temprow input[coltype=itemname]').val(itemname);
					$('#componentitemsgrid tr#gvrow-' + rowcount + '.temprow input[coltype=uom]').val(uom);
					$('#modal-itemlookup').modal('hide');
					break;

				default:
					var line = $('body').data('line'),
						barcode = $(this).attr('barcode'),
						itemname = $(this).attr('itemname'),
						uom = $(this).attr('uom');
					$('#itemcomponentsgrid tr#' + line + ' input[coltype=itemid]').val(itemid);
					$('#itemcomponentsgrid tr#' + line + ' input[coltype=barcode]').val(barcode);
					$('#itemcomponentsgrid tr#' + line + ' input[coltype=itemname]').val(itemname);
					$('#itemcomponentsgrid tr#' + line + ' input[coltype=uom]').val(uom);
					$('#modal-itemlookup').modal('hide');
					break;
			} //end switch
			break;

		case 'reportlist':
			var barcode = $(this).attr('barcode');
			var itemname = $(this).attr('itemname');
			var shortname = $(this).attr('shortname')

			$('.reportitemfilter').val(barcode);
			$('.reportitemcode').val(barcode);
			$('.reportitemname').val(shortname);

			$('#modal-itemlookup').modal('hide');
			break;

		case 'TW':
			var taxname = $(this).attr('namer');
			var taxatc = $(this).attr('atc');
			var taxrate = $(this).attr('rate');

			$('#modal-twenter').modal();

			loadAvailableTaxMonth();

			$('.twtaxname').val(taxname);
			$('.twtaxatc').val(taxatc);
			$('.twtaxrate').val(taxrate);
			$('.twincome').focus().val(0.00);
			$('.twtaxwithheld').val(0.00);
			break;

		default:
			if (checkInvoiceLimit()) {
				generateAlert('error', 'Cannot exceed Invoice Limit. Max limit is ' + invoicelimiting, 'ERROR');
			} else {
				if (checkMaxEditableRows()) {
					generateAlert('error', 'MAX Editable rows reached. Max editable rows is ' + maxeditables + '. Please save first before adding or editing again', 'ERROR');
				} else {
					var plottype = $('#item-lookuptype').val();
					var barcode = $(this).attr('barcode');
					var itemname = $(this).attr('itemname');
					var itemprice = $(this).attr('amt');
					var uom = $(this).attr('uom');

					switch (plottype) {
						case 'PROD_HEAD':
							$('.txtclientname').val(itemname);
							$('.txtclientcodeview').val(barcode);
							$('.txtclientcode').val(barcode);
							$('#modal-itemlookup').modal('hide');
							break;

						default:
							var whdefaultval = $('.txtwarehouse').val();
							var clientcode = $('.txtclientcode').val();

							if (!whdefaultval) {
								var whdefaultval = $('.txtwarehousehidden').val();
							} //end if

							switch (cconfig) {
								case 'TENPLUS':
									var moduleid = $('#viewmoduleid').val();
									switch (moduleid) {
										case 'SJ':
											var str = $('.txtagentcode').val().split('~');
											var agcode = str[0];
											break;

										default:
											var agcode = ''
											break;
									} //end switch

									var params = {
										uom: uom,
										factor: 1,
										itemid: itemid,
										barcode: barcode,
										clientcode: clientcode,
										itemname: itemname,
										itemprice: itemprice,
										wh: whdefaultval,
										agcode: agcode
									};
									break;

								default:
									var params = {
										uom: uom,
										factor: 1,
										itemid: itemid,
										barcode: barcode,
										clientcode: clientcode,
										itemname: itemname,
										itemprice: itemprice,
										wh: whdefaultval
									};
									break;
							} //end switch

							$('#modal-enterqty').modal().css('zIndex', 8000);

							switch (cconfig) {
								case 'UNIVERSE':
									switch (moduleid) {
										case 'SP':
											$('.location-qtydisplay').css('display', 'none');
											$('.expiry-qtydisplay').css('display', 'none');
											$('.itemqtywh').css('display', 'none');
											$('.txtwarehouseitem').css('display', 'none');
											$('.enteredqty').css('display', 'none');
											$('.lblqty').css('display', 'none');
										break;
									}
									break;
							} //eend switch
							requestPrice(params);
							break;
					} //end switch case
				} //end if
			} //end if rowcount
			break;
	} //end switch
}, 300));


