$(document).on('click', '.itemplotbtn', debounce(function () {
	var moduleid = $('#viewmoduleid').val();
	var strexpiry = $('#itemtxtexpiry').val();
	var expirychecking = false;

	if (moduleid == "SP") {
		strexpiry = "";
	} //end if

	switch (cconfig) {
		case 'UNIVERSE':
			strexpiry = strexpiry.replace(/\./g, '-');
			if (strexpiry == "") {
				expirychecking = true;
			} else {
				if (strexpiry.match(/([12]\d{3}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01]))/)) {
					expirychecking = true;
				} else {
					expirychecking = false;
				} //end if
			} //end if
			$('#itemtxtexpiry').val(strexpiry);
			break;

		default:
			expirychecking = true;
			break;
	} //end switch

	if (expirychecking) {
		var type = $('body').data('lookuptype');
		if (type == 'componentitem') {} else {
			var plottype = $('#doclookuptype').val(),
				moduleid = $('#viewmoduleid').val();
			if ($('.enteredqty').val() == "") {
				$('.enteredqty').val("1");
			} else {
				if (!$.isNumeric($('.enteredqty').val())) {
					$('.enteredqty').val("1");
				}
			}
			if ($('.qtyitemamt').val() == "") {
				$('.qtyitemamt').val("0.00");
			} else {
				if (!$.isNumeric($('.qtyitemamt').val())) {
					$('.qtyitemamt').val("0.00");
				}
			}

			switch (moduleid) {
				case 'PD':
					var instruction = $('#prodins').val();
					retrieveProdInstruction(instruction, $('.enteredqty').val());
					break;

				default:
					var params = {};
					params['primarykey'] = $('.qtyitemid').val();
					var lookupid = $('.qtyeditid').val().split('-');
					params['lookuptype'] = lookupid[0];
					params['line'] = lookupid[1];
					if (moduleid == 'TS') {
						var whinfo = $('.txtwarehouseview').val().split('~');
					} else {
						var whinfo = $('.txtwarehouseitem').val().split('~');
					} //end if
					params['warehousename'] = whinfo[0];
					params['warehousecode'] = whinfo[1];
					params['itemamt'] = $('.qtyitemamt').val();
					params['qty'] = $('.enteredqty').val();
					params['type'] = "item";
					params['rowcount'] = stockview.getTemprowIndex();
					params['moduleid'] = $('#viewmoduleid').val();
					params['rem'] = $('#hiddenitemrem').val();
					params['uom'] = $('.selectuompopup').val();
					params['uomfactor'] = $('.selectuompopup').attr('factor');
					params['trno'] = $('.txtboxtrno').val();
					params['disc'] = $('.qtydisc').val();
					params['location'] = $('#itemtxtlocation').val();
					params['expiry'] = $('#itemtxtexpiry').val();


					if (moduleid == "TS") {
						params['location2'] = $('#itemtxtlocation2').val();
					} else {
						params['location2'] = "";
					} //end if


					switch (moduleid) {
						case 'RR':
						case 'PO':
						case 'DM':
							params['forex'] = $('.txtforex').val();
							params['vat'] = $('.txttax').val();
							break;

						default:
							params['forex'] = 1;
							params['vat'] = 0;
							break;
					} //end switch

					switch (cconfig) {
						case 'UNIVERSE': {
							params['rem'] = $('.txtNotes').val();
						} //universe
						break;
					} //config


					switch (cconfig) {
						case 'UNIVERSE':
							if (moduleid == "SJ" || moduleid == "TS" || moduleid == "MX" || moduleid == "MI") {
								if (varstorage.data('universe-changedexpiry')) {
									plotItemdata(params, function (data) {
										addStockitem(data.line, data, params['qty']);
									});
								} else {
									passed_qty = params['qty'];
									getavailableInventories(params['primarykey'], params['warehousecode'], function (data) {
										if (data.status) {
											for (i = 0; i < data.inv.length; i++) {
												if (data.inv[i].bal >= (passed_qty * params['uomfactor'])) {
													params['qty'] = passed_qty;
													params['expiry'] = data.inv[i].expiry;
													params['location'] = data.inv[i].loc;

													plotItemdata(params, function (data) {
														addStockitem(data.line, data, params['qty']);
													});

													break; //exits loop
												} else {
													var bef_qty = passed_qty;
													passed_qty = parseFloat(data.inv[i].bal / params['uomfactor']);
													params['qty'] = passed_qty;
													params['expiry'] = data.inv[i].expiry;
													params['location'] = data.inv[i].loc;

													plotItemdata(params, function (data) {
														addStockitem(data.line, data, params['qty']);
													});

													passed_qty = parseFloat((bef_qty * params['uomfactor'])) - parseFloat(data.inv[i].bal);

													if (parseFloat(passed_qty) != 0) {
														generateAlert('error', 'Insufficient Balance, pulling inventory from next expiry', 'ERROR');
													} //end if

													passed_qty = parseFloat((passed_qty / params['uomfactor']));
												} //end if	
											}; //end loop
										} else {
											generateAlert('error', 'Item out of stock. Please try again.', 'ERROR');
										} //end if
									}); //end get avail inv
								} //end if
							} else {
								plotItemdata(params, function (data) {
									addStockitem(data.line, data, params['qty']);
								});
							} //end if
							break; //END CCCONFIG FOR ADD ITEM

						default:
							plotItemdata(params, function (data) {
								addStockitem(data.line, data, params['qty']);
							});
							break;
					} //end switch

					$('#modal-enterqty').modal('hide');
					$('.selectuompopup').val('');
					$('.selectuompopup').attr('factor', 1);
					break;
			} //end switch

			switch (cconfig) {
				case 'UNIVERSE':
					$('.txtquickadd').focus().select();
					break;
			} //end switch
		} //end if
	} else {
		generateAlert('error', 'Please enter a valid expiry date.', 'ERROR');
	} //end if
}, 300));

