function debounce(func, wait, immediate) {
	var timeout;
	return function () {
		var context = this,
			args = arguments;
		var later = function () {
			timeout = null;
			if (!immediate) func.apply(context, args);
		};
		var callNow = immediate && !timeout;
		clearTimeout(timeout);
		timeout = setTimeout(later, wait);
		if (callNow) func.apply(context, args);
	};
};


function getItembalance(itemid, factor) {

	if (typeof factor === "undefined" || factor === null) {
		factor = 1;
	} else {
		factor = factor;
	} //end if

	var moduleid = $('#viewmoduleid').val(),
		type = $('body').data('itemlookuptype');
	if (type == 'ITEM_INQUIRY') {
		var url = domain + '/admin/getitembalance',
			url2 = domain + '/admin/loaditembal';
	} else {
		var url = domain + '/' + moduleid + '/getitembalance',
			url2 = domain + '/' + moduleid + '/loaditembal';
	} //end if

	addedparams = [];
	addedparams.push({
		name: 'factor',
		value: factor
	});

	$.get(url, {
		itemid: itemid,
		factor: factor
	}, function (data) {

		var showbal = new GridViewGenerator(url2, '.showbalancetbl');
		showbal.initializeGrid(itemid, null, addedparams);

		$('.showbalance-totalitembal').html('TOTAL ITEM BALANCE: ' + $.number(data.bal, qtydecimal));
		$('.unpostedpobal').html('UNPOSTED PO: ' + $.number(data.unpostedpobal, qtydecimal));
		$('.postedpobal').html('POSTED PO: ' + $.number(data.postedpobal, qtydecimal));
		$('.unpostedsobal').html('UNPOSTED SO: ' + $.number(data.unpostedsobal, qtydecimal));
		$('.postedsobal').html('POSTED SO: ' + $.number(data.postedsobal, qtydecimal));
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //END GET ITEM BALANCE

