//JAOSKIMOD: REVISED SAVE STOCKPART
//added some Queue functions so ajax request wont overtake each other
//added 3/23/2018 12:22:04 PM
function saveStockpart(formvalues, callback) {
	$('#overlay').css('display', 'block');
	var moduleid = $('#viewmoduleid').val();

	switch (moduleid) {
		case 'GJ':
		case 'DS':
		case 'AP':
		case 'PV':
		case 'CV':
		case 'TW':
		case 'AR':
		case 'CR':
			urlto = domain + '/' + moduleid + '/savedetail';
			break;
		default:
			urlto = domain + '/' + moduleid + '/savestock';
			break;
	} //end for each

	dopostqueue.queue(function () {
		$.ajax({
			type: "POST",
			url: urlto,
			data: formvalues,
			success: function (result) {
				dopostqueue.dequeue();

				callback(result);
			}
		});
	});
} //END STOCK PART

//JAOSKIMOD: FIX FOR JUMBLING ROWS GROUPS ON SAVEALLSTOCK ITEMS
//CREATED A PROMISE FUNCTION SO THAT IT WOULD RESPONSE OR SAVE FIRST THE FIRST BATCH OF SAVED ITEMS
//Added on 3/23/2018 10:07:04 AM
function saveStockResponse(result) {
	var moduleid = $('#viewmoduleid').val();
	if (result.istransposted) {
		var docno = $('.txtdocno').val();
		generateAlert('error', "Error modifying transaction data. <br> transaction <b>" + docno + "</b> is already posted. Data will be refreshed.", 'ERROR');
		$(".module-btnheadcollapse").trigger("click");
		ajaxSearchDoc(docno);
	} else {
		$.each(result.stockline, function (stocklineindex, stocklinedata) {
			if (stocklinedata['status'] === false) {
				generateAlert('error', "<b>" + stocklinedata['msg'] + "</b>", 'ERROR');
				$('#overlay').fadeOut(300);
				if (stockview.checkForSaveableRows()) {
					stockview.saveAllButtons();
				} else {
					stockview.saveAllButtons('hide');
				} //end if
			} else {
				if (stocklinedata['msg'] != '') {
					generateAlert('error', "<b>" + stocklinedata['msg'] + "</b>", 'ERROR');
				}
				// total tonnage/cbm southcentral - JAD
				if (cconfig == 'SOUTHCENTRAL') {
					if (stocklinedata.totalcbm == null) {
						$('.txttotalcbm').html('TOTAL CBM: 0.00');
					} else {
						$('.txttotalcbm').html('TOTAL CBM: ' + stocklinedata.totalcbm);
					}
					if (stocklinedata.totaltonnage == null) {
						$('.txttotaltonnage').html('TOTAL TONS: 0.00');
					} else {
						$('.txttotaltonnage').html('TOTAL TONS: ' + stocklinedata.totaltonnage);
					}
				}
				// total tonnage/cbm southcentral - JAD

				stockview.plotUpdatedRowData(stocklineindex, stocklinedata);

				switch (moduleid) {
					case 'GJ':
					case 'CR':
					case 'PV':
					case 'CV':
					case 'AP':
					case 'AR':
					case 'DS':
					case 'KR':
						if (stocklinedata.runningcr == null) {
							$('.txttotalcr').html("TOTAL CREDIT: 0.00");
						} else {
							$('.txttotalcr').html("TOTAL CREDIT: " + stocklinedata.runningcr);
						}
						if (stocklinedata.runningdb == null) {
							$('.txttotaldb').html("TOTAL DEBIT: 0.00");
						} else {
							$('.txttotaldb').html("TOTAL DEBIT: " + stocklinedata.runningdb);
						}
						break;

					case 'MI':
					case 'MX':
					case 'QA':
					case 'PR':
					case 'PO':
					case 'RR':
					case 'CM':
					case 'SO':
					case 'SJ':
					case 'DM':
					case 'IS':
					case 'PC':
					case 'TS':
					case 'AJ':
					case 'TR':
					case 'pscheme':
					case 'PS':
					case 'quotation':
					case 'QT':

						if (moduleid == 'RR') {
							if (stocklinedata.totalforex == 0 || stocklinedata.totalforex == null) {
								$('.txtforexgrandtotal').html('FOREX: 0.00');
							} else {
								$('.txtforexgrandtotal').html('FOREX: ' + stocklinedata.totalforex);
							}
						}

						if (stocklinedata.itemcount == 0 || stocklinedata.itemcount == null) {
							$('.txtitemcount').html('NUMBER OF ITEMS: 0.00');
						} else {
							$('.txtitemcount').html('NUMBER OF ITEMS: ' + stocklinedata.itemcount);
						}
						if (stocklinedata.grandtotal == 0 || stocklinedata.grandtotal == null) {
							$('.txtgrandtotal').html('GRAND TOTAL: 0.00');
						} else {
							$('.txtgrandtotal').html('GRAND TOTAL: ' + stocklinedata.grandtotal);
						} //end if


						switch (cconfig) {
							case 'MLCP':
								switch (moduleid) {
									case 'SJ':
										var totalfreight = 0;

										if (stocklinedata.grandtotal == null) {
											var gtotal = 0;
										} else {
											var gtotal = stocklinedata.grandtotal;
										} //end if

										if ($('.txtfreightcharge').val() == '' || !$.isNumeric($('.txtfreightcharge').val())) {
											var freight = 0;
										} else {
											var freight = $('.txtfreightcharge').val();
											freight = freight.replace(/,/g, "");
										} //end if


										totalfreight = parseFloat(gtotal) + parseFloat(freight);
										totalfreight = $.number(totalfreight, amtdecimal);
										$('.txtfreightchargetotal').val(totalfreight);
										break;
								} //end switch
								break;
						} //end switch for mlcp

						break;
				} //end swtich
			} //end if
		}); //end for each

		if (moduleid == 'PV' || moduleid == 'DS') {
			loadstockview();
		} //END IF

		//DECLARATION OF DATEPICKERS
		$('.dpYears').datepicker();
		$('.dpMonths').datepicker();

		if (stockview.checkForSaveableRows()) {
			stockview.saveAllButtons();
		} else {
			stockview.saveAllButtons('hide');
		} //end if
	} //end if trans posted
} //end function

