function checkHeader() {
	if ($('.modulehead').hasClass('saveable')) {
		return true;
	} else {
		return false;
	} //END IF
} //end check header

function checkbeforeShifting() {
	if (checkBodytable('stock') || checkHeader()) {
		//CHECKING IF THERE IS ANYTHING NEED TO BE SAVED ON STOCK
		return false;
	} else {
		return true;
	} //END IF CHECK BODY TABLE
} //END CHECKDATA

$(document).on('click', '.jaox', debounce(function () {
	if (checkbeforeShifting()) {
		$('#overlay').css('display', 'block');
		$(".module-btnheadcollapse").trigger("click");
	} else {
		if (checkBodytable('stock')) {
			var params = {
				shiftfrom: 'stock'
			};
			generateMessagebox("Do you want to save your changes on stock part?", "SHIFTING", params);
		}
		//CHECKING IF THERE IS ANYTHING NEED TO BE SAVED ON HEAD
		if (checkHeader()) {
			var params = {
				shiftfrom: 'head'
			};
			generateMessagebox("Do you want to save your changes on header part?", "SHIFTING", params);
		}
	} //END CHECKBEFORESHIFTING
}, 300));

function saveAllStockitems() {
	var moduleid = $('#viewmoduleid').val(),
		initdiv = stockview.getProperty('initdiv'),
		savedarray,
		savedarray2,
		params = {},
		flagready = true,
		countloop1 = 0,
		countloop2 = 0;
	orig_stockarraydata = {};
	temp_stockarraydata = {};
	var expirychecking = true;

	$(initdiv + ' table tbody tr.temprow').each(function () {
		var thisrow = $(this).prop('id');

		searchRowCheckboxes(thisrow, 1);
		var formvalues = $("#" + thisrow + ".temprow .bodytextbox").serializeArray(),
			arrval = {};
		formvalues.push({
			name: "trno",
			value: $('.txtboxtrno').val()
		});
		savedarray = formvalues;

		$.each(savedarray, function (indexx, datum) {
			switch (cconfig) {
				case 'UNIVERSE':
					if (datum['name'] == "expiry") {
						let strexpiry = datum['value'];
						if (strexpiry.match(/([12]\d{3}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01]))/)) {
							expirychecking = true;
						} else {
							expirychecking = false;
						} //end if
					} //end if
					break;
			} //END FN
			arrval[datum['name']] = datum['value'];
		});
		temp_stockarraydata[thisrow] = arrval;
	});

	if (!expirychecking) {
		generateAlert('error', 'Please enter a valid expiry date.', 'ERROR');
	} else {
		if (!$.isEmptyObject(temp_stockarraydata)) {
			saveStockpart(temp_stockarraydata, function (result) {
				saveStockResponse(result);
			});
		} //end if
	} //end if

	$(initdiv + ' table tbody tr:not(.temprow).edited').each(function () {
		var thisrow = $(this).prop("id");
		searchRowCheckboxes(thisrow, 0);
		var formvalues = $("#" + thisrow + ".edited .bodytextbox").serializeArray(),
			arrval = {};


		switch (moduleid) {
			case 'tpshipping':
				savedarray2 = formvalues;
				break;

			default:
				formvalues.push({
					name: "trno",
					value: $('.txtboxtrno').val()
				});
				savedarray2 = formvalues;
				break;
		} //end switch

		$.each(savedarray2, function (indexx, datum) {
			switch (cconfig) {
				case 'UNIVERSE':
					if (datum['name'] == "expiry") {
						let strexpiry = datum['value'];
						if (strexpiry.match(/([12]\d{3}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01]))/)) {
							expirychecking = true;
						} else {
							expirychecking = false;
						} //end if
					} //end if
					break;
			} //END FN
			arrval[datum['name']] = datum['value'];
		});

		orig_stockarraydata[thisrow] = arrval;
	});

	if (!expirychecking) {
		generateAlert('error', 'Please enter a valid expiry date.', 'ERROR');
	} else {
		if (!$.isEmptyObject(orig_stockarraydata)) {
			saveStockpart(orig_stockarraydata, function (result) {
				saveStockResponse(result);
			});
		} //end if 
	} //end if
} //end fn


function saveAllDetailentries() {
	var savedarray;
	var savedarray2;
	var moduleid = $('#viewmoduleid').val();
	var bothdbcr = 0;
	var bothdbcr_msg_org = '';
	var bothdbcr_msg_temp = '';
	var bothdbcr_msg = '';
	var tempcount = 0;
	var orgcount = 0;

	temp_detailarraydata = {};
	orig_detailarraydata = {};

	//SAVE ALL TEMPORARY ROWS
	$('.temprow').each(function () {
		var txtclass = ".temptxt";
		var btnid = $(this).prop("id").split('-');
		var index = btnid[1];

		if ($(txtclass + '#txtdb-' + index).val() != 0 && $(txtclass + '#txtcr-' + index).val() != 0) {
			tempcount += 1;
			bothdbcr += 1;
			if (bothdbcr_msg_temp == '') {
				bothdbcr_msg_temp = '[(T)Line ' + index;
			} else {
				bothdbcr_msg_temp = bothdbcr_msg_temp.concat(',(T)Line ' + index);
			} //end if
		} else {
			$(txtclass + ".bodytextbox-" + index).prop('disabled', false);
			var formvalues = $(txtclass + ".bodytextbox-" + index).serializeArray();
			var postdate = $('.txtdateid').val();
			formvalues.push({
				name: "trno",
				value: $('.txtboxtrno').val()
			});
			formvalues.push({
				name: "headdate",
				value: postdate
			});
			formvalues.push({
				name: "templine",
				value: index
			});
			savedarray = formvalues;

			var arrval = {};
			$.each(savedarray, function (indexx, datum) {
				arrval[datum['name']] = datum['value'];
			});

			temp_detailarraydata[index] = arrval;
		}
	}); //end for each for temporary

	if (tempcount != 0) {
		bothdbcr_msg_temp = bothdbcr_msg_temp.concat(']<br>');
		bothdbcr_msg = bothdbcr_msg.concat(bothdbcr_msg_temp);
	} //end if org count

	//SAVE ALL ORGINAL ROWS
	$('.orgrow.editing').each(function () {
		var txtclass = ".origtxt";
		var btnid = $(this).prop("id").split('-');
		var index = btnid[1];

		if ($(txtclass + '#txtdb-' + index).val() != 0 && $(txtclass + '#txtcr-' + index).val() != 0) {
			orgcount += 1;
			bothdbcr += 1;
			if (bothdbcr_msg_org == '') {
				bothdbcr_msg_org = '[Line ' + index;
			} else {
				bothdbcr_msg_org = bothdbcr_msg_org.concat(',Line ' + index);
			} //end if
		} else {
			$(txtclass + ".bodytextbox-" + index).prop('disabled', false);
			var formvalues = $(txtclass + ".bodytextbox-" + index).serializeArray();
			var postdate = $('.txtdateid').val();
			formvalues.push({
				name: "trno",
				value: $('.txtboxtrno').val()
			});
			formvalues.push({
				name: "headdate",
				value: postdate
			});
			formvalues.push({
				name: "templine",
				value: index
			});
			savedarray2 = formvalues;

			var arrval = {};
			$.each(savedarray2, function (indexx, datum) {
				arrval[datum['name']] = datum['value'];
			});

			orig_detailarraydata[index] = arrval;
		} //end if
	});

	if (orgcount != 0) {
		bothdbcr_msg_org = bothdbcr_msg_org.concat(']<br>');
		bothdbcr_msg = bothdbcr_msg.concat(bothdbcr_msg_org);
	} //end if org count

	if (bothdbcr != 0) {
		bothdbcr_msg = 'The ff: cant be saved. <br> DB and CR must not have both values.<br>' + bothdbcr_msg
		generateAlert('error', bothdbcr_msg, 'ERROR');
	} //END BOTDBCR MESSAGE

	if (!$.isEmptyObject(temp_detailarraydata)) {
		switch (moduleid) {
			case 'TW':
				saveDetailparttax(temp_detailarraydata);
				break;

			default:
				saveDetailpart(temp_detailarraydata);
				break;
		} //end end switch
	}

	if (!$.isEmptyObject(orig_detailarraydata)) {
		switch (moduleid) {
			case 'TW':
				saveDetailparttax(orig_detailarraydata);
				break;

			default:
				saveDetailpart(orig_detailarraydata);
				break;
		} //end end switch
	}
} //END SAVE ALL STOCK ITEMS


