function buttonsOnlookup(params) {
	var moduleid = $('#viewmoduleid').val();
	if (params['isposted']) { //FOR TRANSACTION IS POSTED

		switch (cconfig) {
			case 'SOUTHCENTRAL':
				switch (moduleid) {
					case 'SO':
						if (params['isapproved'] == 1) {
							$('.approved-flag').css('display', 'block');
							$('.disapproved-flag').css('display', 'none');
						} else {
							$('.approved-flag').css('display', 'none');
							$('.disapproved-flag').css('display', 'block');
						} //end if
						break;
				} //end switch
				break;
		} //end switch
		$('.tx-createsj').prop('disabled', true);
		$('.posted-flag').css('display', 'block');

		$('.module-adjust').css('display', 'block');
		$('.module-adjust').addClass('btnactive');

		if (moduleid == "SJ") {
			$('.module-btnprint').css('display', 'none');
			$('.module-btnprint').removeClass('btnactive');
		} //end if

		$('.module-btnpost').css('display', 'none');
		$('.module-btnpost').removeClass('btnactive');

		$('.module-btnedit').css('display', 'none');
		$('.module-btnedit').removeClass('btnactive');

		$('.module-btnlock').css('display', 'none');
		$('.module-btnlock').removeClass('btnactive');

		$('.module-btnunlock').css('display', 'none');
		$('.module-btnunlock').removeClass('btnactive');

		$('.module-btndelete').css('display', 'none');
		$('.module-btndelete').removeClass('btnactive');

		$('.module-btnunpost').css('display', 'block');
		$('.module-btnunpost').addClass('btnactive');

		$('.stockbtn').prop('disabled', true);
		$('.stockcopybtns').prop('disabled', true);
	} else { // IF TRANSACTION IS NOT POSTED
		$('.posted-flag').css('display', 'none');
		$('.approved-flag').css('display', 'none');
		$('.disapproved-flag').css('display', 'none');

		$('.module-btndelete').css('display', 'block');
		$('.module-btndelete').addClass('btnactive');

		if (moduleid == "SJ") {
			$('.module-btnprint').css('display', 'block');
			$('.module-btnprint').addClass('btnactive');
		} //end if

		$('.module-btnpost').css('display', 'block');
		$('.module-btnpost').addClass('btnactive');

		$('.module-adjust').css('display', 'none');
		$('.module-adjust').removeClass('btnactive');

		if (params['islocked']) { //IF TRANSACTION IS LOCKED
			$('.module-btnedit').css('display', 'none');
			$('.module-btnedit').removeClass('btnactive');

			$('.module-btnlock').css('display', 'none');
			$('.module-btnlock').removeClass('btnactive');

			$('.module-btnunlock').css('display', 'block');
			$('.module-btnunlock').addClass('btnactive');

			$('.stockbtn').prop('disabled', true);
			$('.stockcopybtns').prop('disabled', true);
			$('.tx-createsj').prop('disabled', true);
		} else { //IF TRANSACTION IS NOT LOCKED
			$('.module-btnedit').css('display', 'block');
			$('.module-btnedit').addClass('btnactive');

			$('.module-btnlock').css('display', 'block');
			$('.module-btnlock').addClass('btnactive');

			$('.module-btnunlock').css('display', 'none');
			$('.module-btnunlock').removeClass('btnactive');

			$('.stockbtn').prop('disabled', false);
			$('.stockcopybtns').prop('disabled', false);

			if (moduleid == "TX") {
				if (params['isinvoiced'] == 1) {
					$('.tx-createsj').prop('disabled', true);
				} else {
					$('.tx-createsj').prop('disabled', false);
				} //end if
			} //end if doc TX AND IS INVOICED

		} //end if

		$('.module-btnunpost').css('display', 'none');
		$('.module-btnunpost').removeClass('btnactive');
	} //END ELSE

	if (params['islocked']) {
		$('.locked-flag').css('display', 'block');
	} else {
		$('.locked-flag').css('display', 'none');
	}

	$('.modulehead').removeClass('saveable');
	$('.stocksaveall').css('display', 'none');
} // END BUTTONS ON LOOKUP

