function clientHeadCancel() {
	var clientid = $('#clientid').val();
	var type = 'customer';
	var moduleid = $('#viewmoduleid').val();

	if (moduleid == "employee") {
		var clientid = $('#empid').val();
		var type = 'employee';
	} else if (moduleid == 'assetmaster') {
		var clientid = $('#clientid').val(),
			type = 'assetmaster';
	} else {
		var clientid = $('#clientid').val();
		var type = 'customer';
	}

	if (clientid == "") {
		if (moduleid == "employee") {
			loadlastEmployee();
		} else {
			loadlastClient();
		} //END IF EMPLOYYE
	} else {
		$('#overlay').css('display', 'block');
		$.get(domain + '/' + moduleid + '/getclientinfo', {
			clientid: clientid,
			type: type
		}, function (data) {

			$('#overlay').css('display', 'none');
			switch (moduleid) {
				case 'customer':
					plottingClientData(data.clientdata, 'view');
					break;

				case 'supplier':
					plottingSupplierData(data.clientdata, 'view');
					break;

				case 'agent':
					plottingAgentData(data.clientdata, 'view');
					break;

				case 'warehouse':
					plottingWarehouseData(data.clientdata, 'view');
					break;

				case 'assetmaster':
					plottingAssetData(data.clientdata, 'view');
					break;

				case 'branch':
					plottingBranchData(data.clientdata, 'view');
					break;
			} //end swithc
		}).fail(function (jqXHR, textStatus, error) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		}); //end ajax

		disableForm();
		enableHeadbuttons();
		//		buttonsOnlookup(params);
	}
} //end clienthead cancel

function moduleHeadCancel() {
	var trno = $('.txtboxtrno').val();
	var docno = $(".txtdocno").val();
	var moduleid = $('#viewmoduleid').val();
	$('.rfdocnoblock').css('display', 'block');
	$('.jonumnum').css('display', 'block');
	//TO TRIGGER WHAT DATA TO LOAD
	//(IF TRNO = "" THEN IT MEANS ITS A NEW DOCUMENT IT WOULD REDIRECT TO THE LAST DOCUMENT)
	//(IF TRNO != "" THEN IT MEANS USER IS EDITING AN EXISTING DATA AND IT WOULD LOAD IT AGAIN)
	if (trno == "") {
		$('#overlay').css('display', 'block');
		loadLastdocument();
	} else {
		var params = {
			isposted: 0,
			islocked: 0
		};
		$('#overlay').css('display', 'block');
		$.get(domain + '/' + moduleid + '/searchdocno', {
			docno: docno
		}, function (data) {

			if (data.access == 0) {
				$('#overlay').css('display', 'none');
				generateAlert('error', 'Invalid Access , Please consult your administrator', 'ERROR');
				loadLastdocument();
			} else {
				if (data.moduledata['head']['trno'] == null) {
					$('.btn-navs').prop('disabled', true);
					$('.productioninstrutioncobj').css('display', 'none');
					$('.module-btnedit').css('display', 'none');
					$('.module-btnedit').removeClass('btnactive');
					$('.module-btnsave').css('display', 'none');
					$('.module-btnsave').removeClass('btnactive');
					$('.module-btnprint').css('display', 'none');
					$('.module-btnprint').removeClass('btnactive');
					$('.module-btndelete').css('display', 'none');
					$('.module-btndelete').removeClass('btnactive');
					$('.module-btnlock').css('display', 'none');
					$('.module-btnlock').removeClass('btnactive');
					$('.module-btnunlock').css('display', 'none');
					$('.module-btnunlock').removeClass('btnactive');
					$('.module-btnunpost').css('display', 'none');
					$('.module-btnunpost').removeClass('btnactive');
					$('.module-btnpost').css('display', 'none');
					$('.module-btnpost').removeClass('btnactive');
					$('.module-btnlogs').css('display', 'none');
					$('.module-btnlogs').removeClass('btnactive');
					$('.stock-btnadd').prop('disabled', true);
					$('.stock-btnquickadd').prop('disabled', true);
					$('#overlay').css('display', 'none');
				} else {
					$('.productioninstrutioncobj').css('display', 'block');
					plottingModuleData(data.moduledata, 'view');
				} //END IF MODULE DATA IS NULL
			} //end if data accaess
		}).fail(function (jqXHR, textStatus, error) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		}); //end ajax
		disableForm();
		enableHeadbuttons();
	} //end if

	$('.modulehead').removeClass('saveable');
	$('.stock-btnadd').css('display', 'block');
	$('.stock-btnquickadd').css('display', 'block');
	$('.jaox').css('display', 'block');
} //END MODULE HEAD CANCEL


function checkforDuplicates(table, string) {
	var moduleid = $('#viewmoduleid').val(),
		tableid = '';
	switch (moduleid) {
		case 'DS':
			tableid = '#dsstockview';
			break;
		case 'GJ':
			tableid = '#gjstockview';
			break;
		case 'SO':
			tableid = '#sostockview';
			break;
		case 'SJ':
			tableid = '#sjstockview';
			break;
		case 'QA':
			tableid = '#qastockview';
			break;
		case 'CM':
			tableid = '#cmstockview';
			break;
		case 'MI':
			tableid = '#mistockview';
			break;
		case 'IS':
			tableid = '#isstockview';
			break;

		case 'QA':
			tableid = '#qastockview';
			break;

		case 'MX':
			tableid = '#mxstockview';
			break;
		case 'PC':
			tableid = '#pcstockview';
			break;
		case 'TS':
			tableid = '#tsstockview';
			break;
		case 'TR':
			tableid = '#trstockview';
			break;
		case 'AJ':
			tableid = '#ajstockview';
			break;
		case 'PR':
			tableid = '#prstockview';
			break;
		case 'PO':
			tableid = '#postockview';
			break;
		case 'RR':
			tableid = '#rrstockview';
			break;
		case 'DM':
			tableid = '#dmstockview';
			break;
		case 'AP':
			tableid = '#apstockview';
			break;
		case 'PV':
			tableid = '#pvstockview';
			break;
		case 'CV':
			tableid = '#cvstockview';
			break;
		case 'AR':
			tableid = '#arstockview';
			break;
		case 'CR':
			tableid = '#crstockview';
			break;
		case 'KR':
			tableid = '#krstockview';
			break;
		default:
			tableid = '';
			break;
	}
	var matched = 0;
	$(tableid + ' tbody tr').each(function () {
		if ($(this).find('td input[coltype=barcode]').val() == string) {
			matched += 1;
		}
	});
	if (matched == 0) {
		return false;
	} else {
		return true;
	}
} // END CHECK FOR DUPLICATES

function getIssAmt(line) {
	var uomfactor = $('#txtuom-' + line + ' option:selected').val();
	var uom = $('#txtuom-' + line + ' option:selected').text();
	var iss = parseFloat($('#txtisqty-' + line).val()) * parseFloat(uomfactor);
	var amt = parseFloat($('#txtisamt-' + line).val()) / parseFloat(uomfactor);
	$('#txtiss-' + line).val(iss);
	$('#txtamt-' + line).val(amt);
};


function compareStocklinedata(data, line) {
	var moduleid = $('#viewmoduleid').val();
	$.ajax({
		type: "POST",
		url: domain + '/' + moduleid + '/comparestocklines',
		data: data,
		success: function (result) {

			var params = {
				docno: $('.txtdocno').val()
			};
			if (result.ischanged) {
				//IF CHANGED
				generateMessagebox("Module data is not latest, do you want to <b>SAVE</b> all your changes and <b>REFRESH</b> module data?", "REFRESH", params);
			} else {
				//IF NOT CHANGED
				stocklineTotextbox(result.stockdata[0]['line'], result.stockdata[0]);
			}
		}
	});
} //END COMPARE STOCKLINE DATA

