$(document).on('keydown', '.txtquickadd', function (event) {
	var barcode = $(this).val();
	if (event.which == "13") {
		switch (cconfig) {
			case 'TONRENTANG':
				if (barcode != '') {
					$('#modal-quickadditem').modal().css('zIndex', 9999);
					$('#quickadditembarcode').val(barcode);
				} //END IF
				break;

			case 'UNIVERSE':
				if (typeof varstorage.data('quickaddtype') === "undefined" || varstorage.data('quickaddtype') === null) {
					quickaddtype = '';
				} else {
					quickaddtype = varstorage.data('quickaddtype');
				} //end if

				if (quickaddtype != '') {
					getQuickProdInqDetails(barcode, function (data) {
						$('.quickinqitemname').html(data.head[0]['itemname']);
						$('.quickinqprincipal').html(data.head[0]['uvprincipal']);
						$('.quickinqdivision').html(data.head[0]['division']);
						$('#modal-quickinquiry').modal();
						getQuickProdInqInv(barcode);
					});
				} else {
					if (checkInvoiceLimit()) {
						generateAlert('error', 'Cannot exceed Invoice Limit. Max limit is ' + invoicelimiting, 'ERROR');
					} else {
						if (checkMaxEditableRows()) {
							generateAlert('error', 'MAX Editable rows reached. Max editable rows is ' + maxeditables + '. Please save first before adding or editing again', 'ERROR');
						} else {
							universe_Getiteminfo(barcode, function (data) {
								if (data.itemid == '') {
									generateAlert('error', 'Item not found.', 'ERROR');
								} else {
									var itemid = data.itemid;
									var itemname = data.itemname;
									var itemprice = data.amt;
									var uom = data.uom;
									var whdefaultval = $('.txtwarehouse').val();
									var clientcode = $('.txtclientcode').val();

									if (!whdefaultval) {
										var whdefaultval = $('.txtwarehousehidden').val();
									} //end if

									var params = {
										uom: uom,
										factor: 1,
										itemid: itemid,
										barcode: barcode,
										clientcode: clientcode,
										itemname: itemname,
										itemprice: itemprice,
										wh: whdefaultval
									};

									$('#modal-enterqty').modal().css('zIndex', 8000);

									switch (cconfig) {
										case 'UNIVERSE':
											switch (moduleid) {
												case 'SP':
													$('.location-qtydisplay').css('display', 'none');
													$('.expiry-qtydisplay').css('display', 'none');
													$('.itemqtywh').css('display', 'none');
													$('.txtwarehouseitem').css('display', 'none');
													$('.enteredqty').css('display', 'none');
													$('.lblqty').css('display', 'none');
													break;
											} //END SWITCH CConfig
											break;
									} //eend switch

									requestPrice(params);
								} //end if
							}); //end universe get item info
						} //end if
					} //end if rowcount
				} //end if
				break;

			default:
				if (checkInvoiceLimit()) {
					generateAlert('error', 'Cannot exceed Invoice Limit. Max limit is ' + invoicelimiting, 'ERROR');
				} else {
					if (checkMaxEditableRows()) {
						generateAlert('error', 'MAX Editable rows reached. Max editable rows is ' + maxeditables + '. Please save first before adding or editing again', 'ERROR');
					} else {
						quickaddItem(barcode);
					} //end if
				} //end if
				break;
		} //end switch
	} //END KEYPRESS 13
});

$(document).on('keydown', '.txtquickadditem', function (event) {
	if (event.which == "13") {
		$('.txtamountitem').focus();
	} //end fn
});

function itemInfo() {
	var barcode = $('#quickadditembarcode').val();

	$.get(domain + '/admin/iteminfo', {
		barcode: barcode
	}, function (data) {

		console.log(data);
		if (data.status) {
			$('.txtamountitem').val(data.amount);
		} else {
			generateAlert('error', 'No Barcode Exist!', 'ERROR');
			$('#modal-quickadditem').modal('hide');
		}

	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
}

$(document).on('keydown', '.txtamountitem', function (event) {
	var barcode = $('#quickadditembarcode').val(),
		qty = $('.txtquickadditem').val(),
		amt = $('.txtamountitem').val();
	if (event.which == "13") {
		if (checkInvoiceLimit()) {
			generateAlert('error', 'Cannot exceed Invoice Limit. Max limit is ' + invoicelimiting, 'ERROR');
		} else {
			if (checkMaxEditableRows()) {
				generateAlert('error', 'MAX Editable rows reached. Max editable rows is ' + maxeditables + '. Please save first before adding or editing again', 'ERROR');
			} else {
				if (checkifNumber(qty) && checkifNumber(amt)) {
					quickaddItem(barcode, qty, amt);
				} //end if	
			} //end if
		} //end if
	} //END KEYPRESS 13
});

function checkifNumber(number) {
	if (isNaN(number)) {
		generateAlert('error', 'Please Enter Number Only!', 'ERROR');
		return false;
	} else {
		return true;

	}
} //end fn

function quickaddItem(barcode, qty = 1, amt = 0) {
	if (typeof qty === "undefined" || qty === null) {
		qty = 1;
	} //end if

	if (typeof amt === "undefined" || amt === null) {
		amt = 0.00;
	} //end if

	var moduleid = $('#viewmoduleid').val();
	var trno = $('.txtboxtrno').val()

	switch (moduleid) {
		case 'PC':
		case 'IS':
		case 'AJ':
		case 'TS':
		case 'PK':
			var warehousecode = $('.txtclientcode').val();
			var warehousename = $('.txtclientname').val();
			break;

		default:
			var whinfo = $('.txtwarehouse').val().split('~');
			var warehousecode = whinfo[1];
			var warehousename = whinfo[0];
			break;
	}

	$.get(domain + '/' + moduleid + '/quickadditem', {
		trno: trno,
		barcode: barcode,
		whname: warehousename,
		whcode: warehousecode,
		qty: qty,
		amt: amt
	}, function (data) {

		if (!data.errmsg) {
			addStockitem(data.line, data, data.qty);
			$('.txtquickadd').val('');
		} else {
			$('.quickadderr, .quickadderr h6').css('display', 'block');
		} //end if

		$('#modal-quickadditem').modal('hide');
		$('.txtquickadd').focus();
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //END FUNCTION QUICK ADD ITEM


