function loadcheckaccounts() {
	var moduleid = $('#viewmoduleid').val();
	var clientcode = $('.txtclientcode').val();
	$('.tbl-checks').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
	$.get(domain + '/' + moduleid + '/loadchecks', {
		clientcode: clientcode
	}, function (data) {

		$('.tbl-checks').html('');
		$.each(data.checks, function (checksindex) {
			$('.tbl-checks').append('<tr>\
				<td class="col-min">\
				<input class="checktaker" type ="checkbox" id="' + data.checks[checksindex]['trno'] + '-' + data.checks[checksindex]['line'] + '"/>\
				</td>\
				<td class="aimslabelstock col-description">' + data.checks[checksindex]['acnoname'] + '</td>\
				<td class="aimslabelstock col-codes">' + data.checks[checksindex]['checkno'] + '</td>\
				<td class="aimslabelstock col-min">' + data.checks[checksindex]['checkdate'] + '</td>\
				<td class="aimslabelstock col-codes">' + data.checks[checksindex]['docno'] + '</td>\
				<td class="aimslabelstock col-codes">' + data.checks[checksindex]['db'] + '</td>\
				<td class="aimslabelstock col-codes">' + data.checks[checksindex]['cr'] + '</td>\
				</tr>');
		}); //END EACH
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end load client unpaid accounts


$(document).on('click', '.checktaker', function () {
	var myid = $(this).prop('id');
	var btnid = $(this).prop('id').split('-');
	if ($(this).is(":checked")) {
		//ADD VALUES ON ARRAY
		var arrval = {
			trno: btnid[0],
			line: btnid[1]
		};
		arrayofvalues[myid] = arrval;
	} else {
		//REMOVE VALUES ON ARRAY
		delete arrayofvalues[myid];
	} //END IF
});

$(document).on('click', '.thechecktaker', debounce(function () {
	var arrayofvalues = [];
	$('#checkslookuptbl tbody tr input.gridcheckbox:checked').each(function () {
		trno = $(this).parent().parent().attr('id').split('-'),
			trno = trno[1],
			line = $(this).parent().parent().find('input[coltype=line]').val();
		arrayofvalues.push({
			trno: trno,
			line: line
		});
	});
	if (arrayofvalues != null) {
		getCheckdata(arrayofvalues);
	}
}, 300));


function getCheckdata(arrayofvalues) {
	var moduleid = $('#viewmoduleid').val();
	switch (moduleid) {
		case 'GJ':
			var ccode = $('.txtclientcode').val(),
				tableid = 'gjstockview';
			break;
		case 'DS':
			var ccode = '',
				tableid = 'dsstockview';
			break;
	}
	$.get(domain + '/' + moduleid + '/retrievechecks', {
		params: arrayofvalues,
		ccode: ccode
	}, function (data) {
		$('#modal-checks').modal('hide');

		$.each(data.primarydata, function (arrkey, index) {
			rowcount = stockview.getTemprowIndex();
			stockview.addNewRow(tableid, rowcount);
			arr = [];
			arr['primarydata'] = index;
			stockview.plotNewRowData(rowcount, arr);
		});
		stockview.saveAllButtons('show');
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //END get unpaid data


function setKRreference() {
	var row = 0,
		rowarr = [],
		rowid = 0,
		moduleid = $('#viewmoduleid').val();
	$('#clientunpaidtbl tbody tr input.gridcheckbox:checked').each(function () {
		row += 1;
		rowid = $(this).parent().parent().attr('id');
		rowid = rowid.split('-');
		rowid = rowid[1];
		var line = $(this).parent().parent().find('input[coltype=line]').val();
		rowarr.push({
			trno: rowid,
			line: line
		});
	});
	var kr = $('.txtboxtrno').val();
	$.get(domain + '/' + moduleid + '/setkrreference', {
		data: rowarr,
		kr: kr
	}, function (data) {

		$('#modal-unpaid').modal('hide');
		if (data.stat) {
			$('#modulestockview').html('');
			reinitgrid = new GridViewGenerator(domain + '/' + moduleid + '/buildstockview', '#modulestockview');
			reinitgrid.initializeGrid(kr);
		}
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //END get unpaid data






