function computeAcctgs(clientid, date, type) {
	var moduleid = $('#viewmoduleid').val(),
		addedparams = [];

	addedparams.push({
		name: 'clientid',
		value: clientid
	});
	addedparams.push({
		name: 'date',
		value: date
	});
	addedparams.push({
		name: 'type',
		value: type
	});
	$('.acctg-modulebody').html('');
	$.get(domain + '/' + moduleid + '/getcomputeacctg', {
		clientid: clientid,
		date: date,
		type: type
	}, function (data) {

		$('.acctgdebit').html('DEBIT: ' + $.number(data.totaldb, amtdecimal));
		$('.acctgdebit').css('display', 'block');
		$('.acctgcredit').html('CREDIT: ' + $.number(data.totalcr, amtdecimal));
		$('.acctgcredit').css('display', 'block');
		$('.acctgbal').html('BALANCE: ' + $.number(data.totalbal, amtdecimal));
		$('.acctgbal').css('display', 'block');
	});

	var acct = new GridViewGenerator(domain + '/' + moduleid + '/computeacctg', '.accttable');
	acct.initializeGrid('', false, addedparams);
} //FUNCTION COMPUTE ACCTGS

