$(document).on('click', '#btninventory', debounce(function () {
	var clientid = $('#clientid').val();
	var date = $('#xdateid').val();
	var filter = $('.txtinventorysearch').val();
	computeInventorys(clientid, date, filter);
}, 300));


function computeInventorys(clientid, date, filter) {
	var moduleid = $('#viewmoduleid').val(),
		addedparams = [];
	addedparams.push({
		name: 'clientid',
		value: clientid
	});
	addedparams.push({
		name: 'date',
		value: date
	});
	addedparams.push({
		name: 'filter',
		value: filter
	});
	var computeinv = new GridViewGenerator(domain + '/' + moduleid + '/computeinventory', '.computeinvdiv');
	computeinv.initializeGrid('', false, addedparams);
} //FUNCTION COMPUTE ACCTGS

function plotCStock(customerdata, view_costing) {
	$('.inventory-modulebody').html('');
	var strhtml = '';
	$.each(customerdata, function (dataindx, datainfo) {
		strhtml = strhtml.concat('<tr>');
		strhtml = strhtml.concat('<td class="col-codes aimslabel">' + customerdata[dataindx]['docno'] + '</td>');
		strhtml = strhtml.concat('<td class="col-min aimslabel">' + customerdata[dataindx]['dateid'] + '</td>');
		strhtml = strhtml.concat('<td class="col-codes aimslabel">' + customerdata[dataindx]['barcode'] + '</td>');
		strhtml = strhtml.concat('<td class="col-description aimslabel">' + customerdata[dataindx]['itemname'] + '</td>');
		strhtml = strhtml.concat('<td class="col-min aimslabel">' + customerdata[dataindx]['uom'] + '</td>');
		strhtml = strhtml.concat('<td class="col-min aimslabel">' + customerdata[dataindx]['disc'] + '</td>');
		if (view_costing == 1) {
			strhtml = strhtml.concat('<td class="col-currency aimslabel">' + $.number(customerdata[dataindx]['cost'], amtdecimal) + '</td>');
		} //end if
		strhtml = strhtml.concat('<td class="col-currency aimslabel">' + $.number(customerdata[dataindx]['isamt'], amtdecimal) + '</td>');
		strhtml = strhtml.concat('<td class="col-quantity aimslabel">' + $.number(customerdata[dataindx]['rrqty'], qtydecimal) + '</td>');
		strhtml = strhtml.concat('<td class="col-quantity aimslabel">' + $.number(customerdata[dataindx]['isqty'], qtydecimal) + '</td>');
		switch (cconfig) {
			case 'DAVIDSALON_JOY':
				strhtml = strhtml.concat('<td class="col-codes aimslabel">' + customerdata[dataindx]['salestype'] + '</td>');
				strhtml = strhtml.concat('<td class="col-codes aimslabel">' + customerdata[dataindx]['agent'] + '</td>');
				strhtml = strhtml.concat('<td class="col-codes aimslabel">' + customerdata[dataindx]['agent2'] + '</td>');
				break;
		} //end switch case
		switch (cconfig) {
			case 'YULICK':
				strhtml = strhtml.concat('<td class="nobody aimslabel">' + customerdata[dataindx]['loc'] + '</td>');
				break;

			default:
				strhtml = strhtml.concat('<td class="col-codes aimslabel">' + customerdata[dataindx]['loc'] + '</td>');
				break;
		} //end switch
		strhtml = strhtml.concat('</tr>');
	});
	$('.inventory-modulebody').append(strhtml);
} // end function plotpdc


