function getUserAccessinfo(id) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/edituseraccess', {
		id: id
	}, function (data) {

		$('#txtusernameaccess').val(data.usersdata['username']);
		$('#txtpasswordaccess').val(data.usersdata['pwd']);
		$('#txtnameaccess').val(data.usersdata['name']);
		$('#txtadminpassaccess').val(data.usersdata['administrator_pass']);
		$('#userid').val(data.usersdata['userid']);
		$('#txttime1').val(data.usersdata['starttime']);
		$('#txttime2').val(data.usersdata['endtime']);
		$('#suppname').val(data.usersdata['supplier']);

		if (data.usersdata['picture'] == null) {
			var pic = domain + '/fimages/inventee/png/placeholder.png';
			$('.recordpicture').prop('src', pic);
		} else {
			$('.recordpicture').prop('src', data.usersdata['picture']);
		} //

		if (data.usersdata['isinactive'] == null) {
			$('.userisinactive').prop('checked', false);
		} else {
			if (data.usersdata['isinactive'] == 1) {
				$('.userisinactive').prop('checked', true);
			} else {
				$('.userisinactive').prop('checked', false);
			}
		} //end if
		if (data.usersdata['isTime'] == 0) {
			$('.usertime').prop('checked', false);
			$('.txttime').prop('disabled', true);
		} else {
			$('.usertime').prop('checked', true);
			$('.txttime').prop('disabled', false);
		}

	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end function

