$(document).on('click', '.allowedbtn', debounce(function () {
	var moduleid = $('#viewmoduleid').val();
	var allowed = $(this).prop("id").split('-');
	switch (moduleid) {
		case 'schedmanager':
			var key = allowed[1];
			var key2 = allowed[2];
			setClientNotAllowed(key, key2);
			break;

		default:
			var code = allowed[1];
			var attribute = allowed[2];
			var idno = $('#idno').val();
			var parent = $('.selectsecondlevel option:selected').prop("id").split('-');
			var attri = parent[0];
			var codeload = parent[1];
			$('#overlay').css('display', 'block');
			$.get(domain + '/' + moduleid + '/setnotallowed', {
				code: code,
				attribute: attribute,
				idno: idno
			}, function (data) {

				reloadGrpAccess(idno, codeload, attri);
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			}); //end ajax
			break;
	} ///end swtich case
}, 300));

