$(document).on('click', '.selectloc', debounce(function () {
	var trid = $('body').data('trid'),
		loc = $(this).attr('loc'),
		expiry = $(this).attr('expiry'),
		whcode = $(this).attr('whcode'),
		whname = $(this).attr('whname');
	var loctype = $('body').data('loc-plotlocation');
	if (typeof (whcode) === 'undefined') {
		whcode = $(this).attr('wh');
	} //end if

	if (loctype == 'LOCITEM') {
		$('.txtwarehouseitem').val(whname + '~' + whcode);
		$('#itemtxtlocation').val(loc);
		$('#itemtxtexpiry').val(expiry);
	} else if (loctype == 'STOCKCARD_REP') {
		$('.stockcardwhfilter').val(whname + '~' + whcode);
		$('.txtstockcard-reploc').val(loc);
	} else {
		var trrid = loctype.prop('id');
		$(stockview.initdiv + ' table tbody tr#' + trrid + ' input[coltype=loc]').val(loc);
		$(stockview.initdiv + ' table tbody tr#' + trrid + ' input[coltype=expiry]').val(expiry);
		$(stockview.initdiv + ' table tbody tr#' + trrid + ' input[coltype=whcode]').val(whcode);
		stockview.changeRowColor(varstorage.data('loc-plotlocation'));
		stockview.saveAllButtons();
	} //end if

	varstorage.removeData('loc-plotlocation');
	varstorage.data('universe-changedexpiry', true);
	$('#modal-loclookup').modal('hide');
}, 300));

