$(document).on('keyup', '.txtsearchagent', debounce(function () {
	var txt = $(this).val(),
		moduleid = $('#viewmoduleid').val();

	var url = '';

	switch (varstorage.data('agent_look')) {
		case 'uv_picker':
			url = domain + '/' + moduleid + '/pickerlookupsearch';
			agentlookup = new GridViewGenerator(url, '.agentlookupdiv');
			agentlookup.initializeGrid(txt);
			break;

		case 'uv_checker':
			url = domain + '/' + moduleid + '/checkerlookupsearch';
			agentlookup = new GridViewGenerator(url, '.agentlookupdiv');
			agentlookup.initializeGrid(txt);
			break;

		case 'picker':
			url = domain + '/' + moduleid + '/agentpickerlookupsearch';
			agentlookup = new GridViewGenerator(url, '.pickerlookupdiv');
			agentlookup.initializeGrid(txt);
			break;

		case 'checker':
			url = domain + '/' + moduleid + '/agentcheckerlookupsearch';
			agentlookup = new GridViewGenerator(url, '.checkerlookupdiv');
			agentlookup.initializeGrid(txt);
			break;

		default:
			url = domain + '/' + moduleid + '/agentlookupsearch';
			agentlookup = new GridViewGenerator(url, '.agentlookupdiv');
			agentlookup.initializeGrid(txt);
			break;
	} //end switch
}, 300));


$(document).on('click', '.btnagentlookup', debounce(function () {
	var moduleid = $('#viewmoduleid').val(),
		btnid = $(this).attr('id'),
		agcode = $(this).attr('agcode'),
		agname = $(this).attr('agname');
	switch (moduleid) {
		case 'agent':
			var ccode = $(this).prop('id'),
				type = 'agent';
			getmoduleClientdata(ccode, type);
			break;

		case 'branch':
			var rowcount = branchagentgrid.getTemprowIndex();
			branchagentgrid.addNewRow('branchagentgrid', rowcount);
			$('#branchagentgrid table tr#gvrow-' + rowcount + '.temprow').find('input[coltype=client]').val(agcode);
			$('#branchagentgrid table tr#gvrow-' + rowcount + '.temprow').find('input[coltype=clientname]').val(agname);
			$('#modal-agentlookup').modal('hide');
			break;

		case 'reportlist':
			var ccode = $(this).attr('agcode');
			$('.agentfilter').val(ccode);
			$('.reporttxtagentcode2').val(ccode);
			$('.reporttxtagentname2').val(agname);
			break;

		default:
			switch (varstorage.data('agent_look')) {
				case 'uv_picker':
					$('.txtpickcode').val(agcode + '~' + agname);
					$('.txtpickcodeview').val(agcode + '~' + agname);
					break;


				case 'stockagentlook':
					var row = varstorage.data('agent_stockline');
					$('#modulestockview table tr#gvrow-' + row).find('input[coltype=agent]').val(agcode);
					stockview.changeRowColor($('#modulestockview table tr#gvrow-' + row));
					stockview.saveAllButtons();
					break;

				case 'uv_checker':
					$('.txtcheckcode').val(agcode + '~' + agname);
					$('.txtcheckcodeview').val(agcode + '~' + agname);
					break;

				case 'picker':
					$('.txtpicker').val(agcode + '~' + agname);
					$('.txtpickerview').val(agcode + '~' + agname);
					break;

				case 'checker':
					$('.txtchecker').val(agcode + '~' + agname);
					$('.txtcheckerview').val(agcode + '~' + agname);
					break;

				default:
					$('.txtagentcode').val(agcode + '~' + agname);
					$('.txtagentcodeview').val(agcode + '~' + agname);
					$('.txtagentcodeview2').val(agcode + '~' + agname);
					$('.commagent').val(agcode + '~' + agname);
					$('.reporttxtagentcode').val(agcode);
					break;
			} //end switch
			//ALVIN END
			varstorage.removeData('agent_look');
			break;
	}
	$('#modal-agentpickerlookup').modal('hide');
	$('#modal-agentcheckerlookup').modal('hide');
	$('#modal-agentlookup').modal('hide');
}, 300));

