function computeledger(itemid, datefilter, uom, wh) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/getledgertotal', {
		itemid: itemid,
		wh: wh,
		uom: uom
	}, function (data) {

		$('.txttotalin').html('TOTAL IN: ' + data.totin);
		$('.txttotalout').html('TOTAL OUT: ' + data.totout);
		$('.txttotalbal').html('BALANCE: ' + data.totbal);
		var stockcardledger = new GridViewGenerator(domain + '/' + moduleid + '/computeledger', '.stockcardledger'),
			addedparams = [];
		addedparams.push({
			name: "itemid",
			value: itemid
		});
		addedparams.push({
			name: "date",
			value: datefilter
		});
		addedparams.push({
			name: "uom",
			value: uom
		});
		addedparams.push({
			name: "wh",
			value: wh
		});
		stockcardledger.initializeGrid(null, null, addedparams);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR')
	});
}

