$(document).on('click', '.uomformsave', debounce(function () {
	var btnsave = $(this),
		parentrow = btnsave.parent().parent().prop('id'),
		moduleid = $('#viewmoduleid').val();
	if (btnsave.parent().parent().hasClass('temprow') || btnsave.parent().parent().hasClass('edited')) {
		verifyaccess('save', function (data) {
			if (data) {
				if (btnsave.parent().parent().hasClass('temprow')) {
					var formvalues = $("#" + parentrow + ".temprow .txtuomlookup").serializeArray();
				} else {
					var formvalues = $("#" + parentrow + ".edited .txtuomlookup").serializeArray();
				}
				var barcode = $('.txtbarcode').val(),
					itemid = $('#itemid').val();
				formvalues.push({
					name: 'barcode',
					value: barcode
				});
				formvalues.push({
					name: 'itemid',
					value: itemid
				});
				formvalues.push({
					name: 'parentrow',
					value: parentrow
				});
				insertStockcardUOM(formvalues);
			} else {
				generateAlert('error', 'Invalid Access!', 'ERROR');
			} //end if verfied
		});
	}
}, 300));
// END XANDA

function insertStockcardUOM(params) {
	var moduleid = $('#viewmoduleid').val(),
		parentrow = '',
		prevuom = '';
	$.each(params, function (index, val) {
		if (val['name'] == 'parentrow') {
			parentrow = val['value'];
		}
		if (val['name'] == 'prevuom') {
			prevuom = val['value'];
		}
	});
	$.get(domain + '/' + moduleid + '/insertuom', params, function (data) {

		if (data.status) {
			generateAlert('information', data.msg, 'DEFAULT');
			if (data.type == 'add') {
				$('#uomlookup tr#' + parentrow + '.temprow .gv-options').html(uomlookup.availablebtns);
				$('#uomlookup tr#' + parentrow + '.temprow .gv-options .uomformdelete').attr('uom', data.data[0].uom).attr('line', data.data[0].line);
				$('#uomlookup tr#' + parentrow + '.temprow').css('background', uomlookup.savedrowcolor);
				$('#uomlookup tr#' + parentrow + ' input[coltype=line]').val(data.data[0].line);
				$('#uomlookup tr#' + parentrow + '.temprow').prop('id', 'gvrow-' + data.data[0].itemid);
				$('#uomfactor tr#' + parentrow + '.temprow').removeClass();
			} else {
				if (prevuom == $('.moduletxt.txtuom').val()) {
					$('.moduletxt.txtuom').val(data.data[0].uom);
				}
				if (prevuom == $('.moduletxt.viewbyuom').val()) {
					$('.moduletxt.viewbyuom').val(data.data[0].uom);
				}
				$('#uomlookup tr#' + parentrow + '.edited .gv-options .uomformdelete').attr('uom', data.data[0].uom);
				$('#uomlookup tr#' + parentrow).css('background', uomlookup.savedrowcolor).removeClass();
			}
		} else {
			generateAlert('error', data.msg, 'ERROR');
		}
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
}


