function getUnpaidData(arrayofvalues, ccode) {
	var moduleid = $('#viewmoduleid').val(),
		rowcount = stockview.getTemprowIndex(),
		tableid = '';
	switch (moduleid) {
		case 'GJ':
			tableid = 'gjstockview';
			break;
		case 'PV':
			tableid = 'pvstockview';
			break;
		case 'CV':
			tableid = 'cvstockview';
			break;
		case 'CR':
			tableid = 'crstockview';
			break;
		case 'AR':
			tableid = 'arstockview';
			break;
	} //end switch

	if (typeof varstorage.data('unpaidlookuptype') === "undefined" || varstorage.data('unpaidlookuptype') === null) {
		var unpaidlookuptype = 'single';
	} else {
		var unpaidlookuptype = varstorage.data('unpaidlookuptype');
	} //end if

	$.get(domain + '/' + moduleid + '/retrieveunpaid', {
		params: arrayofvalues,
		ccode: ccode,
		lookuptype: unpaidlookuptype
	}, function (data) {

		$.each(data.primarydata, function (arrkey, index) {
			rowcount = stockview.getTemprowIndex();
			stockview.addNewRow(tableid, rowcount);
			arr = [];
			arr['primarydata'] = index;

			//UPDATE JAOSKI
			$.each(arr['primarydata'], function (i, x) {
				if (x.cr != 0) {
					x.db = parseFloat(x.bal);
					x.cr = 0;
				} else {
					x.cr = parseFloat(x.bal);
					x.db = 0;
				} //end if
				x.ewtcode = $('.txtheadewt').val();
				x.ewtrate = $('.txtheadewtrateewt').val();
			}); //end each

			stockview.plotNewRowData(rowcount, arr);
		});
		stockview.saveAllButtons('show');
		$(".detailsaveall").click();
		$('#modal-unpaid').modal('hide');
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //END get unpaid data


