function lookforReports(parent, attribute, code) {
	var moduleid = $('#viewmoduleid').val();
	if (parent != '') {
		parent.addClass("open");
	}
	$('#child' + attribute).html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:5px;' width='5%'/>");
	$('#overlay').css('display', 'block');
	$.get(domain + '/' + moduleid + '/getreportchildren', {
		code: code
	}, function (data) {
		$('#child' + attribute).html("");
		$.each(data.child, function (childindex, childname) {
			if (data.child[childindex]['isallowed'] == 1) {
				if (data.child[childindex]['seq'] == 1) {
					$('#child' + attribute).append('\
						<li><a class="reportstinger clickable" id="' + data.child[childindex]['attribute'] + '-' + data.child[childindex]['code'] + '">' + data.child[childindex]['description'] + '</a></li>');
				} else {
					$('#child' + attribute).append('\
					<li disabled><i class="indicator glyphicon glyphicon-chevron-down"></i>\
					<a class="reportparents clickable" id="' + data.child[childindex]['attribute'] + '-' + data.child[childindex]['code'] + '">' + data.child[childindex]['description'] + '</a>\
					<ul id="child' + data.child[childindex]['attribute'] + '"></ul>\
					</li>');
				} //end child
			} //end
		}); //END EACH
		$('#overlay').css('display', 'none');
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end FUNCTION


