function getAcctgEntrySum() {
	var acctgval = {};
	acctgval['db'] = 0;
	acctgval['cr'] = 0;
	var moduleid = $('#viewmoduleid').val();
	switch (moduleid) {
		case 'GJ':
			var tableid = 'gjstockview';
			break;
		case 'DS':
			var tableid = 'dsstockview';
			break;
		case 'PV':
			var tableid = 'pvstockview';
			break
		case 'AP':
			var tableid = 'apstockview';
			break;
		case 'CR':
			var tableid = 'crstockview';
			break;
		case 'CV':
			var tableid = 'cvstockview';
			break;
		case 'AR':
			var tableid = 'arstockview';
			break;
	}
	if (stockview.getTemprowIndex() == 1) {
		if (!$('#' + tableid + ' tbody tr:first td div').hasClass('empty')) {
			$('#' + tableid + ' tbody tr').each(function () {
				var myid = $(this).attr('id').split('-');
				var line = myid[1];
				var db = $(this).find('input[coltype=db]').val().replace(/,/g, ""),
					cr = $(this).find('input[coltype=cr]').val().replace(/,/g, "");
				if (db == '') {
					db = 0;
				}
				if (cr == '') {
					cr = 0;
				}
				acctgval['db'] = parseFloat(acctgval['db']) + parseFloat(db);
				acctgval['cr'] = parseFloat(acctgval['cr']) + parseFloat(cr);
				acctgval['db'] = acctgval['db'].toFixed(amtdecimal);
				acctgval['cr'] = acctgval['cr'].toFixed(amtdecimal);
			});
			return acctgval;
		} else {
			return acctgval;
		}
	} else {
		if (!$('#' + tableid + ' tbody tr:first td div').hasClass('empty')) {
			$('#' + tableid + ' tbody tr').each(function () {
				var myid = $(this).attr('id').split('-');
				var line = myid[1];
				var db = $(this).find('input[coltype=db]').val().replace(/,/g, ""),
					cr = $(this).find('input[coltype=cr]').val().replace(/,/g, "");
				if (db == '') {
					db = 0;
				}
				if (cr == '') {
					cr = 0;
				}
				acctgval['db'] = parseFloat(acctgval['db']) + parseFloat(db);
				acctgval['cr'] = parseFloat(acctgval['cr']) + parseFloat(cr);
				acctgval['db'] = acctgval['db'].toFixed(amtdecimal);
				acctgval['cr'] = acctgval['cr'].toFixed(amtdecimal);
			});
			return acctgval;
		} else {
			$('#' + tableid + ' tbody tr').not(':first').each(function () {
				var myid = $(this).attr('id').split('-');
				var line = myid[1];
				var db = $(this).find('input[coltype=db]').val().replace(/,/g, ""),
					cr = $(this).find('input[coltype=cr]').val().replace(/,/g, "");
				if (db == '') {
					db = 0;
				}
				if (cr == '') {
					cr = 0;
				}
				acctgval['db'] = parseFloat(acctgval['db']) + parseFloat(db);
				acctgval['cr'] = parseFloat(acctgval['cr']) + parseFloat(cr);
				acctgval['db'] = acctgval['db'].toFixed(amtdecimal);
				acctgval['cr'] = acctgval['cr'].toFixed(amtdecimal);
			});
			return acctgval;
		}
	}
} //END GET ACCTG

