function getmodelrep() {
	var moduleid = $('#viewmoduleid').val(),
		modelreplookup = new GridViewGenerator(domain + '/' + moduleid + '/getmodelrep', '.modellookupdiv');
	modelreplookup.initializeGrid();
}

$(document).on('click', '.pickmodelrep', debounce(function () {
	var moduleid = $('#viewmoduleid').val();
	var id = $(this).attr('id'),
		name = $(this).attr('model');
	$('.reporttxtmodel').val(name);
	$('.reportidmodel').val(id);
	$('#modal-model').modal('hide');
}, 300));

