$(document).on('click', '.pickbrand', debounce(function () {
	var moduleid = $('#viewmoduleid').val();
	switch (moduleid) {
		case 'manageitem':
			var brandid = $(this).attr('brandid'),
				brand = $(this).attr('brand');
			$('.txtmenumajcat').val(brand).attr('brandid', brandid);
			break;

		case 'branch':
			var line = branchbrandgrid.getTemprowIndex(),
				brandid = $(this).attr('brandid'),
				brand = $(this).attr('brand');
			branchbrandgrid.addNewRow('branchbrandgrid', line);
			$('#branchbrandgrid tr#gvrow-' + line + '.temprow input[coltype=brand]').val(brand);
			$('#branchbrandgrid tr#gvrow-' + line + '.temprow input[coltype=brandid]').val(brandid);
			break;

		case 'changeitem':
			var line = $('body').data('changeitemline'),
				brand = $(this).attr('brand');
			$('#gvrow-' + line + ' input[coltype=brand]').val(brand);
			changeitemgrid.changeRowColor($('#gvrow-' + line));
			break;
		case 'stockcard':
		case 'posstockcard':
			var brand = $(this).attr('brand');
			$('.txtbrand').val(brand);
			break;
		case 'reportlist':
			var brand = $(this).attr('brand');
			$('.reporttxtbrand').val(brand);
			break;
		default:
			var lookuptype = $('.brandtype').val();
			if (lookuptype != 0) {
				var changeline = lookuptype.split('-');
			}
			var line = $(this).attr('id'),
				brand = $('#brand-' + line).html();
			$('.txtbrand').val(brand);
			$('.reporttxtbrand').val(brand);
			if (lookuptype != 0) {
				$('.changetxt#txtbrand-' + changeline[1]).val(brand);
			}
			break;
	}
	$('#modal-brand').modal('hide');
}, 300));

