$(document).on('click', '.changecancelbtn', debounce(function () {
	var moduleid = $('#viewmoduleid').val();
	var thisid = $(this).prop('id').split('-');
	var itemid = thisid[1];
	$('#overlay').css('display', 'block');
	$.get(domain + '/' + moduleid + '/getiteminfo', {
		itemid: itemid
	}, function (data) {

		changedItemPlotting(data.changeditem[0], itemid);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
}, 300));

$(document).on('click', '.changesavebtn', debounce(function () {
	var thisid = $(this).prop('id').split('-');
	var line = thisid[1];
	$('#changebarcode-' + line).prop('disabled', false);
	$('#changeuom-' + line).prop('disabled', false);
	var formvalues = $(".bodytextbox-" + line).serializeArray();
	$('#changebarcode-' + line).prop('disabled', true);
	$('#changeuom-' + line).prop('disabled', true);
	formvalues.push({
		name: "itemid",
		value: line
	});


	changeitemSaving(formvalues, line);
}, 300));

function changeitemSaving(formvalues, index) {
	var moduleid = $('#viewmoduleid').val();
	$('#overlay').css('display', 'block');
	$.ajax({
		type: "POST",
		url: domain + '/' + moduleid + '/changeitemsaving',
		data: formvalues,
		success: function (result) {

			$('#orgrow-' + index).removeClass('saveable');
			changedItemPlotting(result.changeditem[0], index);
		}
	});
} //CHANGE ITEM SAVING END

function changedItemPlotting(changeditem, index) {
	$('#changebuttons-' + index + '.origdata').html('<button id="changeedit-' + index + '" class="changeeditbtn btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;">\
       	<i style="font-size:12px;margin-top:-8px;" class="fa fa-pencil"></i></button>');
	$('#changebarcode-' + index + '.origdata').html(changeditem['barcode']);
	$('#changeitemname-' + index + '.origdata').html(changeditem['itemname']);
	$('#changeuom-' + index + '.origdata').html(changeditem['uom']);
	$('#changebrand-' + index + '.origdata').html(changeditem['brand']);
	$('#changegroupid-' + index + '.origdata').html(changeditem['groupid']);
	$('#changemodel-' + index + '.origdata').html(changeditem['model']);
	$('#changepart-' + index + '.origdata').html(changeditem['part']);
	$('#changesizeid-' + index + '.origdata').html(changeditem['sizeid']);
	$('#changeamt-' + index + '.origdata').html(changeditem['amt']);
	$('#changecost-' + index + '.origdata').html(changeditem['cost']);
	$('#changemax-' + index + '.origdata').html(changeditem['maximum']);
	$('#changemin-' + index + '.origdata').html(changeditem['minimum']);
	$('#overlay').css('display', 'none');
} //end function



