$(document).on('submit', '#picupload', function (e) {
	e.preventDefault();
	var moduleid = $('#viewmoduleid').val();
	var formvalues = new FormData(this);

	switch (moduleid) {
		case 'stockcard':
		case 'itemprofile':
		case 'posstockcard':
			formvalues.append("codeid", $('#itemid').val());
			break;

		case 'fhighlights':
			formvalues.append("codeid", $('.modifyhighkey').val());
			break;

		case 'managedod':
			formvalues.append("codeid", $('.modifydodkey').val());
			break;

		case 'managefdeals':
			formvalues.append("codeid", $('.modifyfdkey').val());
			break;

		case 'themer':
			formvalues.append("codeid", 0);
			break;

			//employee
		case 'employee':
			formvalues.append("codeid", $('#empid').val());
			break;

		case 'useraccess':
			formvalues.append("codeid", $('#userid').val());
			break;

		case 'fbrmanager':
			formvalues.append("codeid", $('#brandmanagecode').val());
			break;

		default:
			formvalues.append("codeid", $('#clientid').val());
			break;
	} //end switch

	$('#overlay').css('display', 'block');
	$.ajax({
		type: "POST",
		url: domain + '/' + moduleid + '/uploadpic',
		data: formvalues,
		processData: false,
		contentType: false,
		success: function (result) {


			/*if(result.error != ""){
			generateAlert('error',result.error,'ERROR');
		}else{
*/
			switch (moduleid) {
				case 'themer':
					generateAlert('information', "<b>Wallpaper has been changed!</b>", 'DEFAULT');
					break;

				case 'useraccess':
					$('.recordpicture').prop('src', result.picture);
					$('.userpictopbar').prop('src', result.picture);
					break;

				case 'stockcard':
				case 'posstockcard':
					$('.recordpicture').prop('src', result.picture + "?" + new Date().valueOf());
					break;

				default:
					$('.recordpicture').prop('src', result.picture + "?" + new Date().valueOf());
					break;
			} //end switch

			//}//end if result.error

			$('#overlay').css('display', 'none');
			$('.uploadsave').css('display', 'none');
			$('.uploadcancel').css('display', 'none');
			//$('.uploadedpicture').val('');
		}
	});
});

