$(document).on('keyup', '.txtadministrator-pin', debounce(function (event) {
	var moduleid = $('#viewmoduleid').val();
	if (event.which == 13) {
		$('#overlay').css('display', 'block');
		if (verifyAdministratorPassword($(this).val(), function (data) {
				if (data) {
					var approvedby = $('.pincode-userlist option:selected').text();
					$('#overlay').css('display', 'none');
					$('#modal-adminpass').modal('hide');
					switch (moduleid) {
						case 'frontendlogs':
							var params = {
								logid: '',
								type: 'SWIPE'
							};
							generateMessagebox("<b style='color:red;'>Swiping all logs will delete all logs from beginning of time, CONTINUE?</b>", "DELETE_FLOG", params);
							break;

						case 'SO':
						case 'PO':
						case 'PR':
						case 'QA':
						case 'TR':
							if ($('.txtadministrator-voidstyle').val() == 'MULTIPLE') {
								multipleVoid();
							} else {
								var line = $('.txtadministrator-line').val(),
									trno = $('.txtadministrator-trno').val(),
									voidval = $('.txtadministrator-void').val();
								stockItemVoid(trno, line, voidval, approvedby);
							}
							break;

						case 'SJ':
						case 'RR':
						case 'SJ2':
							var line = $('.txtadministrator-line').val(),
								trno = $('.txtadministrator-trno').val(),
								voidval = $('.txtadministrator-void').val();
							stockItemVoid(trno, line, voidval, approvedby);
							break;
					}
				} else {
					$('#overlay').css('display', 'none');
					generateAlert('error', "Error , please Re-enter your administrator password.", 'ERROR');
				}
			}));
	}
}, 300));

