function deleteFrontendLogs(logid, type) {
	$('#overlay').css('display', 'block');
	switch (type) {
		case 'SWIPE':
		case 'SINGLE':
		case 'SELECTED':
			$.get(domain + '/frontendlogs/removelogs', {
				logid: logid,
				type: type
			}, function (data) {

				if (data.status) {
					arrayofvalues = {};
					generateAlert('information', "<b>" + data.msg + "</b>", 'DEFAULT');
					loadFrontendLogs();
				} else {
					generateAlert('error', data.msg, 'ERROR');
				}
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			}); //end ajax
			break;

		case 'FILTERED':
			var date1 = $('.txtdateid1').val();
			var date2 = $('.txtdateid2').val();
			var logtype = $('.front-logs option:selected').text();
			$.get(domain + '/frontendlogs/removelogs', {
				logid: '',
				type: type,
				date1: date1,
				date2: date2,
				logtype: logtype
			}, function (data) {

				if (data.status) {
					generateAlert('information', "<b>" + data.msg + "</b>", 'DEFAULT');
					loadFrontendLogs();
				} else {
					generateAlert('error', data.msg, 'ERROR');
				}
				$('#overlay').css('display', 'none');
			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			}); //end ajax
			break;
	} //end switch case
} //end deletefrontendlogs function

function loadFrontendLogs(date1, date2, type) {
	var date1 = $('.txtdateid1').val();
	var date2 = $('.txtdateid2').val();
	var type = $('.fronttype option:selected').text();
	$('#overlay').css('display', 'block');
	$('.flog-modulebody').html('');
	$.get(domain + '/frontendlogs/loadflogs', {
		dateone: date1,
		datetwo: date2,
		type: type
	}, function (data) {
		$('#overlay').css('display', 'none');

		var concatter = "";

		$.each(data.logdata, function (dataindx, dataname) {

			concatter = concatter.concat('<tr>');
			concatter = concatter.concat('<td class="col-min aimslabel">');
			if (arrayofvalues[data.logdata[dataindx]['logid']]) {
				concatter = concatter.concat('<input id = "' + data.logdata[dataindx]['logid'] + '" class="logtaker" type="checkbox" checked/>');
			} else {
				concatter = concatter.concat('<input id = "' + data.logdata[dataindx]['logid'] + '" class="logtaker" type="checkbox"/>');
			}
			concatter = concatter.concat('</td>');
			concatter = concatter.concat('<td class="col-min aimslabel"><button id="logdelete-' + data.logdata[dataindx]['logid'] + '" class="btnlogdelete btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-trash"></i></button></td>');
			concatter = concatter.concat('<td class="col-description aimslabel">' + data.logdata[dataindx]['username'] + '</td>');
			concatter = concatter.concat('<td class="col-description aimslabelstock">' + data.logdata[dataindx]['logtype'] + '</td>');
			concatter = concatter.concat('<td class="col-description aimslabelstock">' + data.logdata[dataindx]['occurance'] + '</td>');
			concatter = concatter.concat('<td class="col-codes aimslabelstock">' + data.logdata[dataindx]['iplog'] + '</td>');
			concatter = concatter.concat('<td class="col-codes aimslabelstock">' + data.logdata[dataindx]['refcode'] + '</td>');
			concatter = concatter.concat('</tr>');
		});
		$('.flog-modulebody').append(concatter);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end function


function verifyAdministratorPassword(enteredpassword, callback) {
	var username = $('.pincode-userlist option:selected').text();
	$.get(domain + '/admin/verifyadministratorpass', {
		password: enteredpassword,
		username: username
	}, function (data) {

		callback(data.verified);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end

