function setNotAllowedAll() {
	var moduleid = $('#viewmoduleid').val();
	$('#overlay').css('display', 'block');
	$('.allowedbtn').each(function (i, obj) {
		switch (moduleid) {
			case 'schedmanager':
				var allowed = $(this).prop("id").split('-');
				var key = allowed[1];
				var key2 = allowed[2];
				setClientNotAllowed(key, key2);
				break;

			default:
				var allowed = $(this).prop("id").split('-');
				var code = allowed[1];
				var attribute = allowed[2];
				var idno = $('#idno').val();
				var parent = $('.selectsecondlevel option:selected').prop("id").split('-');
				var attri = parent[0];
				var codeload = parent[1];

				$('#overlay').css('display', 'block');
				$.get(domain + '/' + moduleid + '/setnotallowed', {
					code: code,
					attribute: attribute,
					idno: idno
				}, function (data) {

					reloadGrpAccess(idno, codeload, attri);
				}).fail(function (jqXHR, textStatus, error) {
					generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
				}); //end ajax
				break;
		} //end switch case
	}); //end each

} //end function

function setAllowedAll() {
	var moduleid = $('#viewmoduleid').val();
	$('.notallowedbtn').each(function (i, obj) {
		switch (moduleid) {
			case 'schedmanager':
				var allowed = $(this).prop("id").split('-');
				var key = allowed[1];
				var key2 = allowed[2];
				setClientAllowed(key, key2);
				break;

			default:
				var allowed = $(this).prop("id").split('-');
				var code = allowed[1];
				var attribute = allowed[2];
				var idno = $('#idno').val();
				var parent = $('.selectsecondlevel option:selected').prop("id").split('-');
				var attri = parent[0];
				var codeload = parent[1];

				$('#overlay').css('display', 'block');
				$.get(domain + '/' + moduleid + '/setallowed', {
					code: code,
					attribute: attribute,
					idno: idno
				}, function (data) {

					reloadGrpAccess(idno, codeload, attri);
				}).fail(function (jqXHR, textStatus, error) {
					generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
				}); //end ajax
				break;
		} //end switch case
	}); //end each

} //end set allowed all

