$(document).on('click', '.pickuser2', debounce(function () {
	var userid = $(this).attr('id'),
		username = $(this).attr('username'),
		lookuptype = $('body').data('lookuptypeuser');
	$('#overlay').hide();
	switch (lookuptype) {
		case 'TIMEDATA':
			$('.timeinuser').val(username).attr('value', username);
			$('#timeoxd').val(userid).attr('value', userid);
			break;
		case 'SCHEDULE':
			var month = $('#calendar').fullCalendar('getDate').format('MM');
			$('.scheduleruser').val(username);
			retrieveMemberSchedule(userid, month);
			break;
		case 'OVERALLSCHED':
			$('.overallscheduser').val(username);
			$('#useroxd').val(userid);
			break;
		case 'REPORTPLOT':
			$('.reporttxtuser').val(username);
			break;
	}
	$('#modal-users').modal('hide');
}, 300));


$(document).on('click', '.pickuser', debounce(function () {
	var moduleid = $('#viewmoduleid').val(),
		line = $(this).attr('userid'),
		username = $(this).attr('username');
	// username = $('#user-'+line).html();
	switch (moduleid) {
		case 'scheduler':
			$('#overlay').css('display', 'none');
			var lookuptype = $('.lookuptypeuser').val();
			switch (lookuptype) {
				case 'TIMEDATA':
					$('.timeinuser').val(username);
					$('#timeoxd').val(line);
					break;

				case 'OVERALLSCHED':
					$('.overallscheduser').val(username);
					$('#useroxd').val(line);
					break;

				case 'SCHEDULE':
					var month = $('#calendar').fullCalendar('getDate').format('MM');
					$('.scheduleruser').val(username);
					retrieveMemberSchedule(line);
					break;
			}
			break;

		case 'reportlist':
			$('.reporttxtuser').val(username);
			break;

		default:

			break;
	}
	$('#modal-users').modal('hide');
}, 300));


