function retrievePriceHistory(ccode, barcode) {
	$('.tbl-pricehistory').html('');
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/retrievepricehistory', {
		ccode: ccode,
		barcode: barcode
	}, function (data) {
		$('#modal-pricehistory').modal();

		$.each(data.pricehistory, function (priceindex) {
			$('.tbl-pricehistory').append('<tr> \
					<td class="col-min aimslabelstock">' + data.pricehistory[priceindex]['dateid'] + '</td> \
					<td class="col-currency aimslabelstock">' + data.pricehistory[priceindex]['amt'] + '</td> \
					<td class="col-currency aimslabelstock">' + data.pricehistory[priceindex]['qty'] + '</td> \
					<td class="col-currency aimslabelstock">' + data.pricehistory[priceindex]['disc'] + '</td> \
					<td class="col-currency aimslabelstock">' + data.pricehistory[priceindex]['ext'] + '</td> \
					<td class="col-description aimslabelstock">' + data.pricehistory[priceindex]['docno'] + '</td> \
					<td class="col-description aimslabelstock">' + data.pricehistory[priceindex]['clientname'] + '</td> \
	              	<td class="col-codes aimslabelstock">' + data.pricehistory[priceindex]['loc'] + '</td> \
	              	<td class="col-codes aimslabelstock">' + data.pricehistory[priceindex]['expiry'] + '</td> \
	            </td> \
	       	</tr>');
		});
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end function

