function plotbrecondata(brecon) {
	$('.brecon-modulebody').html('');
	var dcBal = 0;
	$.each(brecon, function (dataindx, datainfo) {
		if (brecon[dataindx]['sort'] == 2) {
			dcBal = parseFloat(brecon[dataindx]['db']);
		} else {
			dcBal = dcBal + (parseFloat(brecon[dataindx]['db']) - parseFloat(brecon[dataindx]['cr']));
		}
		if (brecon[dataindx]['clearday'] == "") {
			$('.brecon-modulebody').append('<tr>\
		<td class="col-codes aimslabel"><input class="breconselect" type ="checkbox" id="' + brecon[dataindx]['trno'] + '-' + brecon[dataindx]['line'] + '" /></td>\
		<td class="col-codes aimslabel">' + brecon[dataindx]['dateid'] + '</td>\
		<td class="col-codes aimslabel">' + brecon[dataindx]['clearday'] + '</td>\
		<td class="col-codes aimslabel">' + brecon[dataindx]['postdate'] + '</td>\
		<td class="col-description aimslabel">' + brecon[dataindx]['checkno'] + '</td>\
		<td class="col-codes aimslabel">' + $.number(brecon[dataindx]['cr'], 2) + '</td>\
		<td class="col-codes aimslabel">' + $.number(brecon[dataindx]['db'], 2) + '</td>\
		<td class="col-codes aimslabel">' + $.number(dcBal, 2) + '</td>\
		<td class="col-description aimslabel">' + brecon[dataindx]['docno'] + '</td>\
		<td class="col-codes aimslabel">' + brecon[dataindx]['clientname'] + '</td>\
		<td class="col-description aimslabel">' + brecon[dataindx]['rem'] + '</td>\
		</tr>');
		} else {
			$('.brecon-modulebody').append('<tr>\
		<td class="col-codes aimslabel"><input class="breconselect" type ="checkbox" id="' + brecon[dataindx]['trno'] + '-' + brecon[dataindx]['line'] + '" disabled /></td>\
		<td class="col-codes aimslabel">' + brecon[dataindx]['dateid'] + '</td>\
		<td class="col-codes aimslabel">' + brecon[dataindx]['clearday'] + '</td>\
		<td class="col-codes aimslabel">' + brecon[dataindx]['postdate'] + '</td>\
		<td class="col-description aimslabel">' + brecon[dataindx]['checkno'] + '</td>\
		<td class="col-codes aimslabel">' + $.number(brecon[dataindx]['cr'], 2) + '</td>\
		<td class="col-codes aimslabel">' + $.number(brecon[dataindx]['db'], 2) + '</td>\
		<td class="col-codes aimslabel">' + $.number(dcBal, 2) + '</td>\
		<td class="col-description aimslabel">' + brecon[dataindx]['docno'] + '</td>\
		<td class="col-codes aimslabel">' + brecon[dataindx]['clientname'] + '</td>\
		<td class="col-description aimslabel">' + brecon[dataindx]['rem'] + '</td>\
		</tr>');
		}

	}); //END EACH
} //end plotting

