function searchBankbook(mode) {
	var moduleid = $('#moduleid').val();
	var contra = $('#contra2').val();
	var start = $('#startdate2').val();
	var end = $('#enddate2').val();
	var gatherby = $('#gatherby').val();
	var searchby = $('#searching').val();

	$.get(domain + '/' + moduleid + '/getbankbook', {
		start: start,
		end: end,
		contra: contra,
		gatherby: gatherby,
		mode: mode,
		searchby: searchby
	}, function (data) {

		$('.banksum-modulebody').html('');
		if (data.err != 'success') {
			generateAlert('error', data.err, 'ERROR');
		}
		plotbankbook(data.bankbook);
		$('.txtunclearbal').val($.number(data.unclear, 2));
		$('.txtasof').val(data.brdate);
		$('.txtbreconbal').val($.number(data.begbal, 2));
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
}

