function loadFrontendCategories(type) {
	var moduleid = $('#viewmoduleid').val();
	$('#fcatlookuptype').val(type);
	$('.fcatlist-body').html('');
	var strhtml = "";
	$.get(domain + '/' + moduleid + '/getfcatparents', {
		type: type
	}, function (data) {
		$('#modal-frontendcatlist').modal();

		$.each(data.fcatlist, function (dataindx, datainfo) {
			strhtml = strhtml.concat('<tr><td class="col-min">');
			strhtml = strhtml.concat('<button id="btnfcatpickparent~' + datainfo['peanuts'] + '" class="btnfcatpickparent btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;">');
			strhtml = strhtml.concat('<i style="font-size:12px;margin-top:-8px;" class="fa fa-sign-in"></i></button>&nbsp');
			strhtml = strhtml.concat('<button id="btnfcatviewchild~' + datainfo['peanuts'] + '" class="btnfcatviewchild btn btn-social-icon btn-github" style="width:18px;height:18px;margin-top:-2px;">');
			strhtml = strhtml.concat('<i style="font-size:12px;margin-top:-8px;" class="fa fa-eye"></i></button>');
			strhtml = strhtml.concat('</td>');
			strhtml = strhtml.concat('<td class="fcatdescription-' + datainfo['peanuts'] + ' col-description aimslabel">' + datainfo['description'] + '</td>');
			strhtml = strhtml.concat('<td class="col-description aimslabel">' + datainfo['mparent'] + '</td>');
			strhtml = strhtml.concat('<td class="col-description aimslabel">' + datainfo['isenabled'] + '</td>');
			strhtml = strhtml.concat('</tr>');
		}); //end for each
		$('.fcatlist-body').append(strhtml);
	});
} //end function

