function insertFrontendCategory(category, type, isenable, isparent, fparent) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/insertcategory', {
		category: category,
		type: type,
		p1: isenable,
		p2: isparent,
		p3: fparent
	}, function (data) {

		if (data.status) {
			generateAlert('information', '<b>Saved data, sucessfully!</b>', 'DEFAULT');
			$('#modal-frontendcategories').modal('hide');
		} else {
			generateAlert('error', 'Error adding new category. Please try again.', 'ERROR');
		} //end function
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end function


