function plotDoubleColumn(rightside, leftside) {
	var moduleid = $('#viewmoduleid').val();
	$('#allowed').html('');
	$('#notallowed').html('');

	switch (moduleid) {
		case 'schedmanager':
			$.each(rightside, function (dataindx, datainfo) {
				if ($('#accesslisting').hasClass('editmode')) {
					$("#allowed").append('<button id ="notallowed-' + rightside[dataindx]['clientid'] + '-' + rightside[dataindx]['userid'] + '" class="allowedbtn btn btn-flat btn-info settings-btn" style="width:100%;margin-top:3px;"><b>' + rightside[dataindx]['clientname'] + '</b></button>');
				} else {
					$("#allowed").append('<button id ="notallowed-' + rightside[dataindx]['clientid'] + '-' + rightside[dataindx]['userid'] + '" class="allowedbtn btn btn-flat btn-info settings-btn" style="width:100%;margin-top:3px;" disabled="true"><b>' + rightside[dataindx]['clientname'] + '</b></button>');
				} //end if
			});

			$.each(leftside, function (dataindx, datainfo) {
				if ($('#accesslisting').hasClass('editmode')) {
					$("#notallowed").append('<button id ="allowed-' + leftside[dataindx]['clientid'] + '-' + leftside[dataindx]['userid'] + '"class="notallowedbtn btn btn-flat btn-info settings-btn" style="width:100%;margin-top:3px;"><b>' + leftside[dataindx]['clientname'] + '</b></button>');
				} else {
					$("#notallowed").append('<button id ="allowed-' + leftside[dataindx]['clientid'] + '-' + leftside[dataindx]['userid'] + '"class="notallowedbtn btn btn-flat btn-info settings-btn" style="width:100%;margin-top:3px;" disabled="true"><b>' + leftside[dataindx]['clientname'] + '</b></button>');
				} //end if
			});

			$('#overlay').css('display', 'none');
			break;
	} //end switch

	$("#allowed").append('</br>');
	$("#notallowed").append('</br>');
	$('#overlay').css('display', 'none');
} // end function plotthirdlevel

