					strhtml = strhtml.concat('<button id="comprefixedit-' + data.comprefs[comindex]['line'] + '" data-toggle="tooltip" title="Edit" class="btneditcomprefix btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-pencil"></i></button>');
