$(document).on('mouseover', '.orgrow,.temprow,.origtxt,.temptxt', function () {
	var thisobj = $(this);
	getStockTooltip(thisobj, 'stockmodule');
});

function getStockTooltip(obj, type) {
	var obj_id = obj.prop('id').split('-');
	var line = obj_id[1];
	var tooltip = "";

	switch (type) {
		case 'stockmodule':
			if (obj.hasClass('orgrow')) {
				if (obj.hasClass('editing')) {
					tooltip = 'Barcode: ' + $('#stockbarcode-' + line + ' #txtbarcode-' + line).val();
					tooltip = tooltip.concat(' - Itemname: ' + $('#stockitemname-' + line + ' #txtitemname-' + line).val());
				} else {
					tooltip = 'Barcode: ' + $('#stockbarcode-' + line).html();
					tooltip = tooltip.concat(' - Itemname: ' + $('#stockitemname-' + line).html());
				} //end if
			} else {
				tooltip = 'Barcode: ' + $('#stockbarcode-' + line + ' #txtbarcode-' + line).val();
				tooltip = tooltip.concat(' - Itemname: ' + $('#stockitemname-' + line + ' #txtitemname-' + line).val());
			} //end function
			break;

		case 'detailmodule':

			break;

		case 'scheduler':
			tooltip = '';
			break;
	} //end switch
} //end function


