function setVoidButtons(isvoid, isposted, line) {
	var moduleid = $('#viewmoduleid').val();
	if (isposted) {
		switch (moduleid) {
			case 'SO':
			case 'PO':
			case 'QA':
			case 'TR':
				if (isvoid) {
					if (line != '') {
						$('.btnstockopt.origdata#stockbuttons-' + line).html('<button id="stockunvoid-' + line + '" class="stockunvoidbtn btn btn-social-icon btn-twitter" style="width:60px;height:18px;margin-top:-2px;"><span style="font-size:12px;margin-top:-10px;font-weight:bold;">Unvoid</span></button>');
						$('#orgrow-' + line).addClass('voidrow');
					} else {
						generateAlert('error', 'Void and unvoiding params error', 'ERROR');
					} //end if
				} else {
					if (line != '') {
						$('.btnstockopt.origdata#stockbuttons-' + line).html('<button id="stockvoid-' + line + '" class="stockvoidbtn btn btn-social-icon btn-google" style="width:60px;height:18px;margin-top:-2px;"><span style="font-size:12px;margin-top:-10px;font-weight:bold;">Void</span></button>');
						$('#orgrow-' + line).removeClass('voidrow');
					} else {
						//if posted and not voided or unvoided [UPDATES ALL BUTTONS TO VOID BUTTONS]
						$.each($('.btnstockopt'), function (indx, dtx) {
							var rowcreds = $(this).prop('id').split('-');
							var line = rowcreds[1];
							$(this).html('<button id="stockvoid-' + line + '" class="stockvoidbtn btn btn-social-icon btn-google" style="width:60px;height:18px;margin-top:-2px;"><span style="font-size:12px;margin-top:-10px;font-weight:bold;">Void</span></button>');
						}); //end function
					} //end if
				} //end set void button
				break;
		} //end switch case
	} else {
		switch (moduleid) {
			case 'SO':
			case 'PO':
			case 'QA':
			case 'TR':
				var strhtml = '';
				$.each($('.btnstockopt'), function (indx, dtx) {
					strhtml = '';
					var rowcreds = $(this).prop('id').split('-');
					var line = rowcreds[1];
					strhtml = strhtml.concat('<button id="stockedit-' + line + '"class="stockbtn stockeditbtn btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></button>&nbsp');
					strhtml = strhtml.concat('<button id="stockdelete-' + line + '" class="stockbtn stockdeletebtn btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-trash"></i></button>&nbsp');
					strhtml = strhtml.concat('<button id="showbalance-' + line + '" data-toggle="tooltip" title="Show Balance" class="showbalance stockbtn stockattrbtn btn btn-social-icon btn-github" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-eye"></i></button>');
					$(this).html(strhtml);
				}); //end function
				break;
		} //end switch case
	} //end if
} //end function

function stockItemVoid(trno, line, isvoid, approvedby) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/voiditem', {
		trno: trno,
		line: line,
		voidval: isvoid,
		approvedby: approvedby
	}, function (data) {

		if (data.voiding['status']) {
			switch (moduleid) {
				case 'SO':
				case 'PO':
				case 'PR':
				case 'QA':
				case 'TR':
					if (isvoid == 1) {
						$('#gvrow-' + line + ' .gv-options .voidbtn').remove();
						$('#gvrow-' + line + ' .gv-options').append(stockview.voidbtns['unvoid']);
						$('#gvrow-' + line + ' .gv-options .unvoidbtn').attr('btnid', line);
						$('#gvrow-' + line + ' input[coltype=void]').val('1');
						$('#gvrow-' + line).addClass('voidrow').css({
							'background': voidcolor
						});
					} else {
						$('#gvrow-' + line + ' .gv-options .unvoidbtn').remove();
						$('#gvrow-' + line + ' .gv-options').append(stockview.voidbtns['void']);
						$('#gvrow-' + line + ' .gv-options .voidbtn').attr('btnid', line);
						$('#gvrow-' + line + ' input[coltype=void]').val('0');
						$('#gvrow-' + line).removeClass('voidrow').css('background', '');
					}
					break;

				case 'SJ':
				case 'RR':
				case 'SJ2':
					getSupplierPO('');
					break;
			}
			generateAlert('information', data.voiding['msg'], 'DEFAULT');
		} else {
			generateAlert('error', data.voiding['msg'], 'ERROR');
		}
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end function

$(document).on('click', '.reporttype', function () {
	var slct = $(this).val();

	switch (slct) {
		case 'postdelivery':
			$('.modal-bodypostdel').css('display', 'block');
			$('.modal-bodypatch').css('display', 'none');
			$('.modal-bodytrans').css('display', 'none');

			break;

		case 'dispatch':
			$('.modal-bodypatch').css('display', 'block');
			$('.modal-bodypostdel').css('display', 'none');
			$('.modal-bodytrans').css('display', 'none');

			break;

		case 'default':
			$('.modal-bodytrans').css('display', 'block');
			$('.modal-bodypostdel').css('display', 'none');
			$('.modal-bodypatch').css('display', 'none');

			break;
	}
});

