$(document).on('change', '#salestype', function () {
	var moduleid = $('#viewmoduleid').val();
	switch (moduleid) {
		case 'SJ':
		case 'SJ2':
			var salestype = $('#salestype option:selected').text();
			changeContraBasedOnSalestype(salestype);
			break;
	} //end switch
});

function changeContraBasedOnSalestype(salestype) {
	var moduleid = $('#viewmoduleid').val();
	$('#overlay').css('display', 'none');
	$.get(domain + '/' + moduleid + '/stypecontra', {
		salestype: salestype
	}, function (data) {


		switch (salestype) {
			case 'CHECK':
			case 'DEPOSIT':
				$('.contracheck').css('display', 'block');
				break;

			default:
				$('.contracheck').css('display', 'none');
				break;
		} //end switch

		if (data.contradata['status']) {
			$('.txtcontra').val('');
			$('.txtcontraview').val('');
			$('.txtcontra').val(data.contradata['contra'][0]['acno'] + '~' + data.contradata['contra'][0]['acnoname']);
			$('.txtcontraview').val(data.contradata['contra'][0]['acno'] + '~' + data.contradata['contra'][0]['acnoname']);
		} else {
			generateAlert('error', data.msg, 'ERROR');
		} //end if
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function

function hideInvoiceCheckno(salestype) {
	switch (salestype) {
		case 'CHECK':
		case 'DEPOSIT':
			$('.contracheck').css('display', 'block');
			$('.contracheck').prop('disabled', false);
			break;

		default:
			$('.contracheck').prop('disabled', true);
			$('.contracheck').css('display', 'none');
			break;
	} //end switch
} //end if

function checkInvoiceLimit() {
	if (invoicelimiting == 0) {
		return false;
	} else {
		var rowcount = $('.bodytable tr').length;
		var moduleid = $('#viewmoduleid').val();
		rowcount = rowcount - 1;
		switch (moduleid) {
			case 'SJ':
			case 'SJ2':
			case 'SO':
			case 'QA':
				if (rowcount > invoicelimiting) {
					return true;
				} else {
					return false;
				} //end function
				break;

			default:
				return false;
				break;
		} //end switch
	} //end function
} //end function

function checkMaxEditableRows() {
	if (maxeditables == 0) {
		return false;
	} else {
		var initdiv = stockview.getProperty('initdiv');
		var newrows = $(initdiv + ' table tbody tr.temprow').length;
		var editedrows = $(initdiv + ' table tbody tr:not(.temprow).edited').length;
		var totaleditables = parseFloat(newrows) + parseFloat(editedrows);

		if (totaleditables == maxeditables) {
			return true;
		} else {
			return false;
		} //end if
	} //end if
} //end function

