function plotpdctable(pdcdata) {
	$.each(pdcdata, function (dataindx, datainfo) {
		var strhtml = "";
		if (pdcdata[dataindx]['void'] == 1) {
			strhtml = strhtml.concat('<tr class="voidrow">');
		} else {
			strhtml = strhtml.concat('<tr>');
		}

		strhtml = strhtml.concat('<td id="stockbuttons-' + pdcdata[dataindx]['line'] + '" style="margin-bottom:-5px;" class="origdata btnstockopt col-xs-2 aimslabelstock">');
		strhtml = strhtml.concat('<button id="pdcedit-' + pdcdata[dataindx]['line'] + '" data-toggle="tooltip" title="Edit" class="pdcbtns btneditpdc btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-pencil" disabled></i></button>&nbsp');
		strhtml = strhtml.concat('<button id="pdcdelete-' + pdcdata[dataindx]['line'] + '"  data-toggle="tooltip" title="Delete" class="pdcbtns btndeletepdc btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-trash" disabled></i></button>&nbsp');
		strhtml = strhtml.concat('<button id="pdcvoid-' + pdcdata[dataindx]['line'] + '"  data-toggle="tooltip" title="Void" class="pdcbtns btnvoidpdc btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-ban" disabled></i></button></td>');
		strhtml = strhtml.concat('<td style="margin-bottom:-5px;"><input class="pdcbtns pdcselect" type ="checkbox" id="' + pdcdata[dataindx]['line'] + '"  value="' + pdcdata[dataindx]['tr'] + '"/></td>');
		strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="pdcdateid-' + pdcdata[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + pdcdata[dataindx]['dateid'] + '</td>');
		strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="pdcclient-' + pdcdata[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + pdcdata[dataindx]['client'] + '</td>');
		strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="pdcclientname-' + pdcdata[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + pdcdata[dataindx]['clientname'] + '</td>');
		strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="pdccheckdate-' + pdcdata[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + pdcdata[dataindx]['checkdate'] + '</td>');
		strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="pdccheckno-' + pdcdata[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + pdcdata[dataindx]['checkno'] + '</td>');
		strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="pdcamount-' + pdcdata[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + $.number(pdcdata[dataindx]['amount'], 2) + '</td>');
		strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="pdccreateby-' + pdcdata[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + pdcdata[dataindx]['createby'] + '</td>');
		strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="pdcnotes-' + pdcdata[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + pdcdata[dataindx]['notes'] + '</td>');
		strhtml = strhtml.concat('</tr>');

		$('.pdc-modulebody').append(strhtml);
		alert(pdcdata[dataindx]['tr']);
		if (pdcdata[dataindx]['tr'] == 'P') { //determine if posted or not
			$('#pdcedit-' + pdcdata[dataindx]['line']).prop('disabled', true);
			$('#pdcdelete-' + pdcdata[dataindx]['line']).prop('disabled', true);
			$('#pdcvoid-' + pdcdata[dataindx]['line']).prop('disabled', true);
		} else {
			if (pdcdata[dataindx]['void'] == 1) {
				$('#pdcedit-' + pdcdata[dataindx]['line']).prop('disabled', true);
				$('#pdcdelete-' + pdcdata[dataindx]['line']).prop('disabled', true);
				$('#pdcvoid-' + pdcdata[dataindx]['line']).prop('disabled', true);
			} else {
				$('#pdcedit-' + pdcdata[dataindx]['line']).prop('disabled', false);
				$('#pdcdelete-' + pdcdata[dataindx]['line']).prop('disabled', false);
				$('#pdcvoid-' + pdcdata[dataindx]['line']).prop('disabled', false);
			} //end
		} //end if
	});
} // end function plotpdc

