function comparePdclinedata(data, line) {
	var moduleid = $('#moduleid').val();
	$.ajax({
		type: "POST",
		url: domain + '/' + moduleid + '/comparepdclines',
		data: {
			line: data['line'],
			client: data['client'],
			clientname: data['clientname'],
			checkdate: data['checkdate'],
			checkno: data['checkno'],
			amount: data['amount'],
			dateid: data['dateid'],
			refx: data['refx'],
			linex: data['linex'],
			notes: data['notes']
		},
		success: function (result) {
			//alert($('.txtcheckno').val());

			var params = {
				checkno: $('.txtcheckno').val()
			};

			if (result.ischanged) {
				//IF CHANGED
				generateMessagebox("Module data is not latest, do you want to <b>SAVE</b> all your changes and <b>REFRESH</b> module data?", "REFRESH", params);
			} else if (result.pdcdata[0]['refx'] != 0 && result.pdcdata[0]['linex'] != 0) {
				generateError("Unable to edit check. Already served.");
				$('#overlay').css('display', 'none');
			} else {
				//IF NOT CHANGED
				pdclineTotextbox(result.pdcdata[0]['line'], result.pdcdata[0]);
			}
		}
	});
} //END COMPARE PDCLINE DATA

