function getpdcdata() {
	var row = 0,
		rowarr = [],
		rowid = 0,
		moduleid = $('#viewmoduleid').val(),
		gridviewid = '';
	switch (moduleid) {
		case 'CR':
			gridviewid = 'crstockview';
			break;
	}
	$('#table-pdcchecks tbody tr input.gridcheckbox:checked').each(function () {
		row += 1;
		rowid = $(this).parent().parent().attr('id');
		rowid = rowid.split('-');
		rowid = rowid[1];
		rowarr.push({
			line: rowid
		});
	});
	switch (moduleid) {
		case 'customer':
		case 'supplier':
			var clientcode = $('.txtclient').val();
			break;
		default:
			var clientcode = $('.txtclientcode').val();
			break;
	} //end switch
	if (rowarr.length >= 1) {
		$.get(domain + '/' + moduleid + '/retrievepdc', {
			params: rowarr,
			ccode: clientcode
		}, function (data) {

			$.each(data.pdcchecksdata, function (arrkey, index) {
				rowcount = stockview.getTemprowIndex();
				stockview.addNewRow(gridviewid, rowcount, 'detail');
				arr = [];
				index[0]['postdate'] = index[0]['checkdate'];
				index[0]['pdcline'] = index[0]['line'];
				index[0]['line'] = 0;
				index[0]['db'] = index[0]['amount'];;
				arr['primarydata'] = index;
				stockview.plotNewRowData(rowcount, arr);
			});
			stockview.saveAllButtons('show');
			$('#modal-pdcchecks').modal('hide');
		});
	}
}
//end pdc clicks

