$(document).on('click', '.module-btnsavegenitem', debounce(function () { //save
	verifyaccess('save', function (data) {
		if (data) {
			var moduleid = $('#viewmoduleid').val();
			var values = $(".moduletxt").serializeArray();
			values.push({
				name: "line",
				value: $('#lines').val()
			});
			$('#overlay').css('display', 'block');
			$.ajax({
				type: "POST",
				url: domain + '/' + moduleid + '/savegenitem',
				data: values,
				success: function (result) {

					plotgenitem(result.generalitem);
					$('.gitemtext').css('display', 'none');
					$('.moduletxt').val('');
					$('.module-btnnewgenitem').css('display', 'inline');
					$('.module-btnsavegenitem').css('display', 'none');
					$('.module-btncancelgenitem').css('display', 'none');
					$('#overlay').css('display', 'none');
				}
			});
		} else {
			generateAlert('error', 'Invalid Access!', 'ERROR');
		} //end if verfied
	});
}, 300));


