function comparegenitemlinedata(data, line) {
	var moduleid = $('#moduleid').val();
	$.ajax({
		type: "POST",
		url: domain + '/' + moduleid + '/comparegenitemlines',
		data: {
			line: data['line'],
			bcode: data['bcode'],
			itemdesc: data['itemdesc'],
			itemshortname: data['itemshortname'],
			itemuom: data['itemuom'],
			itembrand: data['itembrand'],
			itemcolor: data['itemcolor'],
			itemgroup: data['itemgroup'],
			itempart: data['itempart'],
			itemmodel: data['itemmodel'],
			itemclass: data['itemclass'],
			itemsize: data['itemsize']
		},
		success: function (result) {

			var params = {
				bcode: $('.txtbcode').val()
			};

			if (result.ischanged) {
				//IF CHANGED
				generateMessagebox("Module data is not latest, do you want to <b>SAVE</b> all your changes and <b>REFRESH</b> module data?", "REFRESH", params);
			} else {
				//IF NOT CHANGED
				genitemlineTotextbox(result.genitem[0]['line'], result.genitem[0]);
			}
		}
	});
} //END COMPARE

