function getfaitemdata() {
	var moduleid = $('#moduleid').val();
	var ccode = $('.txtclientcode').val();
	var dateid = $('.txtdateid').val();
	var rem = $('.txtrem').val();
	var ref = $('.txtref').val();
	$.get(domain + '/' + moduleid + '/retrievefaitem', {
		params: arrayofvalues,
		ccode: ccode,
		dateid: dateid,
		rem: rem,
		ref: ref
	}, function (data) {

		//plotfaitem(data.faitem);
		var strhtml = "";
		$('.faitem-modulebody').html("");
		$.each(data.faitem, function (itemindex, iteminfo) {
			strhtml = strhtml.concat('<tr>');
			strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="faitemtagcode-' + data.faitem[itemindex][0]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + data.faitem[itemindex][0]['barcode'] + '</td>');
			strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="faitembcode-' + data.faitem[itemindex][0]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + data.faitem[itemindex][0]['bcode'] + '</td>');
			strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="faitemname-' + data.faitem[itemindex][0]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + data.faitem[itemindex][0]['itemname'] + '</td>');
			strhtml = strhtml.concat('<td style="margin-bottom:-5px;" id="faitemshortname-' + data.faitem[itemindex][0]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + data.faitem[itemindex][0]['shortname'] + '</td>');

			if (data.faitem[itemindex][0]['tr'] == 'P') {
				$('.module-btnaddfaitem').prop('disabled', true);
				$('.module-btnpostta').prop('disabled', true);
				$('.module-btnpostta').css('display', 'none');
			} else {
				$('.module-btnaddfaitem').prop('disabled', false);
				$('.module-btnpostta').prop('disabled', false);
				$('.module-btnpostta').css('display', 'inline');
			}

		});
		$('.faitem-modulebody').append(strhtml);

		$('#modal-faitemlookup').modal('hide');
	}); //end ajax
}

function plotfaitem(faitem) {
	$.each(faitem, function (dataindx, datainfo) {
		$('.faitem-modulebody').append('<tr>\
					<td style="margin-bottom:-5px;" id="faitemtagcode-' + faitem[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + faitem[dataindx]['barcode'] + '</td>\
		            <td style="margin-bottom:-5px;" id="faitembcode-' + faitem[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + faitem[dataindx]['bcode'] + '</td>\
		            <td style="margin-bottom:-5px;" id="faitemname-' + faitem[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + faitem[dataindx]['itemname'] + '</td>\
		            <td style="margin-bottom:-5px;" id="faitemshortname-' + faitem[dataindx]['line'] + '" class="origdata col-xs-5 aimslabelstock">' + faitem[dataindx]['shortname'] + '</td>\
		            </tr>');

		$('.txtclientcode').val(faitem[dataindx]['empcode']);
		$('.txtclientname').val(faitem[dataindx]['employee']);
		$('.txtloccode').val(faitem[dataindx]['dcode']);
		$('.txtlocation').val(faitem[dataindx]['department']);
		$('.txtrem').val(faitem[dataindx]['rem']);
		$('.txtdateid').val(faitem[dataindx]['dateid']);
		if (faitem[dataindx]['tr'] == 'P') {
			$('.module-btnaddfaitem').prop('disabled', true);
			$('.module-btnpostta').prop('disabled', true);
			$('.module-btnpostta').css('display', 'none');
		} else {
			$('.module-btnaddfaitem').prop('disabled', false);
			$('.module-btnpostta').prop('disabled', false);
			$('.module-btnpostta').css('display', 'inline');
		}

	});
}

