function saveFrontendLane(params) {
	$.get(domain + '/lanemanager/savelane', {
		params: params
	}, function (data) {

		if (data.status) {
			plotLanes(data.lanes);
			generateAlert('information', data.msg, 'DEFAULT');
			$('.module-btnnewlane').css('display', 'block');
			$('.module-btnsavelane').css('display', 'none');
			$('.module-btncancellane').css('display', 'none');
			$('.newlaneform').css('display', 'none');
			$('.lanelist').css('display', 'block');
			$('.txtnewlane').val('');
		} else {
			generateAlert('error', data.msg, 'ERROR');
		} //end if
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function save frontend lane

