function tooltipsterInitializer(type, obj) {
	switch (type) {
		case 'LANE_OPT':
			var objid = obj.prop('id').split('-');
			var options = {
				contentAsHTML: true,
				content: '<button id="managelane-' + objid[1] + '" class="managelane btn btn-flat btn-xs btn-primary"><i class="fa fa-pencil"></i> UPDATE</button>\
						 <button id="removelane-' + objid[1] + '" class="removelane btn btn-flat btn-xs btn-danger"><i class="fa fa-times"></i> REMOVE</button>',
				interactive: true,
				close: function () {
					// reset the content back to the loading image
					obj.tooltip('destroy');
					obj.tooltip($tooltip_options);
				},
			};

			obj.tooltipster(options);
			break;

		case 'CAT_OPT':
			var objid = obj.prop('id').split('-');
			var options = {
				contentAsHTML: true,
				content: '<button id="managecat-' + objid[1] + '" class="managecat btn btn-flat btn-xs btn-primary"><i class="fa fa-pencil"></i> UPDATE</button>\
						 <button id="removecat-' + objid[1] + '" class="removecat btn btn-flat btn-xs btn-danger"><i class="fa fa-times"></i> REMOVE</button>',
				interactive: true,
				close: function () {
					// reset the content back to the loading image
					obj.tooltip('destroy');
					obj.tooltip($tooltip_options);
				},
			};

			obj.tooltipster(options);
			break;
	} //end switch

} //end function


