function checkifvoidPosted() {
	var moduleid = $('#viewmoduleid').val(),
		tableid = '';

	switch (moduleid) {
		case 'CK':
			tableid = '#ckstockview';
			break;
		case 'PO':
			tableid = '#postockview';
			break;
		case 'SO':
			tableid = '#sostockview';
			break;

		case 'TR':
			tableid = '#trstockview';
			break;
		case 'quotation':
			tableid = '#quotestockview';
			break;

		case 'QA':
			tableid = '#qastockview';
			break;


		case 'pscheme':
		case 'PS':
			tableid = '#psstockview';
			break;
	} //end switch

	var islocked = $('#modulestockview').attr('lockedstatus'),
		isposted = $('#modulestockview').attr('poststatus');
	if (islocked == 1) {
		$(tableid + ' tbody tr .bodytextbox, ' + tableid + ' tbody tr input.gridcheckbox').attr("disabled", true);
		$(tableid + ' tbody tr .gvbtns').css("display", "none");
	} else {
		if (isposted == 1) {
			$('.multiplevoidbtn').prop('disabled', false);
		} else {
			$('.multiplevoidbtn').prop('disabled', true);
		}
		if ($(tableid + ' table tbody tr').length != 0) {
			$(tableid + ' table tbody tr:not(#null)').each(function () {
				if ($(this).is('#null') || $(this).find('td div').hasClass('empty')) {

				} else {
					var id = $(this).attr('id'),
						line = $(this).attr('id').split('-'),
						index = line[1],
						voidstat = $(this).find('input[coltype=void]').val(),
						posted = $(this).find('input[coltype=tr]').val();

					if (voidstat != 0) { // if void
						$('#gvrow-' + index).addClass('voidrow').css({
							'background': voidcolor
						});
						$('#gvrow-' + index + ' .bodytextbox, #gvrow-' + index + ' input.gridcheckbox').attr("disabled", true);
						$('#gvrow-' + index + ' .gv-options .unvoidbtn, #gvrow-' + index + ' .gv-options .voidbtn').remove();
						$('#gvrow-' + index + ' .gv-options').append(stockview.voidbtns['unvoid']);
						$('#gvrow-' + index + ' .gv-options .unvoidbtn').attr('btnid', index);
						$('#gvrow-' + index + ' .gvbtns').css("display", "none");
					} else { // not void
						if (isposted == 1) { // if posted
							$('#gvrow-' + index + ' .bodytextbox, #gvrow-' + index + ' input.gridcheckbox').attr("disabled", "disabled");
							$('#gvrow-' + index + ' .gvbtns').css("display", "none");
							$('#gvrow-' + index + ' .gv-options .voidbtn, #gvrow-' + index + ' .gv-options .unvoidbtn').remove();
							$('#gvrow-' + index + ' .gv-options').append(stockview.voidbtns['void']);
							$('#gvrow-' + index + ' .gv-options .voidbtn').attr('btnid', index);
						} else { // not void and not posted
							$('#gvrow-' + index + ' .bodytextbox, #gvrow-' + index + ' input.gridcheckbox').attr("disabled", false);
							$('#gvrow-' + index + ' .gv-options .voidbtn').css("display", "none");
							$('#gvrow-' + index + ' .gvbtns').css("display", "inline-block");
						}
					}
				}
			});
		}
	}
}

