function plotLaneChildren(childcat, type, headlabel, parentid) {
	var moduleid = $('#viewmoduleid').val();
	var strhtml = "";
	switch (moduleid) {
		case 'lanemanager':
			strhtml = strhtml.concat('<div class="col-md-6">');
			strhtml = strhtml.concat('<button class="btn btn-flat btn-danger settings-btn" style="width:100%;margin-top:3px;" disabled><b>' + headlabel + '</b></button>');
			strhtml = strhtml.concat('<button id="addsubcat~' + type + '~' + parentid + '" class="addsubcat btn btn-flat btn-success settings-btn" style="width:100%;margin-top:3px;" ><b><i class="fa fa-plus"></i> ADD SUB CATEGORY</b></button>');
			strhtml = strhtml.concat('<br>');
			strhtml = strhtml.concat('<br>');
			strhtml = strhtml.concat('<div class="subcatcontainer">');
			if (childcat.length > 0) {
				$.each(childcat, function (cat, kitten) {
					strhtml = strhtml.concat('<button id="fcat-' + kitten['catid'] + '" class="fcategory btn btn-flat btn-github settings-btn" style="width:100%;margin-top:3px;"><b>' + kitten['cat_desc'] + '</b></button>');
				}); //end for each
			} //end if
			strhtml = strhtml.concat('</div>');
			strhtml = strhtml.concat('</div>');
			break;

		case 'stockcard':
		case 'posstockcard':
			strhtml = strhtml.concat('<div class="col-md-6">');
			strhtml = strhtml.concat('<button class="btn btn-flat btn-danger settings-btn" style="width:100%;margin-top:3px;" disabled><b>' + headlabel + '</b></button>');
			if (type == "LANE") {
				strhtml = strhtml.concat('<button class="btn btn-flat btn-github settings-btn" style="width:100%;margin-top:3px;" disabled><b>Select Category below:</b></button>');
			} else {
				strhtml = strhtml.concat('<button id="tagitem~' + type + '~' + parentid + '" class="tagitem btn btn-flat btn-success settings-btn" style="width:100%;margin-top:3px;" ><b><i class="fa fa-sign-in"></i> TAG TO THIS CATEGORY</b></button>');
			} //end function
			strhtml = strhtml.concat('<br>');
			strhtml = strhtml.concat('<br>');
			strhtml = strhtml.concat('<div class="subcatcontainer">');
			if (childcat.length > 0) {
				$.each(childcat, function (cat, kitten) {
					strhtml = strhtml.concat('<button id="fcat-' + kitten['catid'] + '" class="fcategory btn btn-flat btn-github settings-btn" style="width:100%;margin-top:3px;"><b>' + kitten['cat_desc'] + '</b></button>');
				}); //end for each
			} //end if
			strhtml = strhtml.concat('</div>');
			strhtml = strhtml.concat('</div>');
			break;
	} //end 

	$('#lanechildlisting').append(strhtml);
} //end function lane children plotting


