$(document).on('submit', '.bannerupload', function (e) {
	e.preventDefault();

	var thisid = $(this).prop('id').split('-');
	var moduleid = $('#viewmoduleid').val();
	var formvalues = new FormData(this);

	switch (moduleid) {
		case 'lanemanager':
			formvalues.append("codeid", $('#managelaneid').val());
			formvalues.append("index", thisid[1]);
			$('.bannerpic-' + thisid[1]).prop('src', '');
			break;

		case 'fhighlights':
			formvalues.append("codeid", $('.modifyhighkey').val());
			break;

		case 'fbmanager':
			formvalues.append("index", thisid[1]);
			break;

		case 'managedod':
			formvalues.append("codeid", $('.modifydodkey').val());
			break;

		case 'managefdeals':
			formvalues.append("codeid", $('.modifyfdkey').val());
			break;
	} //end switch

	$('#overlay').css('display', 'block');
	$.ajax({
		type: "POST",
		url: domain + '/' + moduleid + '/uploadbannerslider',
		data: formvalues,
		processData: false,
		contentType: false,
		success: function (result) {


			switch (moduleid) {
				case 'lanemanager':
				case 'fbmanager':
					$('.bannerpic-' + thisid[1]).prop('src', result.picture + "?" + new Date().valueOf());
					break;

				case 'fhighlights':
				case 'managedod':
				case 'managefdeals':
					$('.bannerpic').prop('src', result.picture + "?" + new Date().valueOf());
					break;
			} //end switch

			$('#overlay').css('display', 'none');
			$('#buploadsave-' + thisid[1]).css('display', 'none');
			$('#buploadcancel-' + thisid[1]).css('display', 'none');
			//$('.uploadedpicture').val('');
		}
	});
});

