function loadAvailableOrderStatuses() {
	var fstatuses = {
		0: 'FOR VERIFICATION',
		1: 'FOR PROCESSING',
		2: 'FOR PACKING',
		3: 'FOR DELIVERY',
		4: 'CLOSED'
	};
	$('#fstatus option:not(:selected)').remove();
	$('#fstatusfilter option:not(:selected)').remove();

	$.each(fstatuses, function (statusindex, status) {
		if (fstatuses[statusindex] != $('#fstatus option:selected').text()) {
			$('#fstatus').append('<option>' + fstatuses[statusindex] + '</option>');
		} //END IF

		if (fstatuses[statusindex] != $('#fstatusfilter option:selected').text()) {
			$('#fstatusfilter').append('<option>' + fstatuses[statusindex] + '</option>');
		} //END IF
	});
} //end function load avaialble order statuses



