function retrieve_Ebrands(tagging, searchstring) {
	//0 for frontend disabled ebrands
	//1 for frontend enabled ebrands
	//2 for all ebrands (mostly used on brand manager)

	$('.fbrbrandtbl').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
	$.get(domain + '/fbrmanager/managebrand', {
		type: 'retrieve',
		tag: tagging,
		v: searchstring
	}, function (data) {
		$('.fbrbrandtbl').html('');

		var strhtml = "";
		$.each(data.brands, function (brandindex, brandinfo) {
			strhtml = strhtml.concat('<tr>');
			strhtml = strhtml.concat('<td id="" class="col-checkbox btblcenter aimslabel">');
			if (brandinfo.status == 1) {
				strhtml = strhtml.concat('<input type="checkbox" class="fbrenablefrontend" id="fbrenable-' + brandinfo['brandid'] + '" checked>');
			} else {
				strhtml = strhtml.concat('<input type="checkbox" class="fbrenablefrontend" id="fbrenable-' + brandinfo['brandid'] + '">');
			} //end if
			strhtml = strhtml.concat('</td>');
			strhtml = strhtml.concat('<td id="fbrbuttons-' + brandinfo['brandid'] + '" style="margin-bottom:-5px;" class="btblcenter aimslabel col-min">');
			strhtml = strhtml.concat('<button id="fbredit-' + brandinfo['brandid'] + '" data-toggle="tooltip" title="Edit Item" class="fbreditbtn btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-pencil"></i></button>&nbsp');
			strhtml = strhtml.concat('<button id="fbrdelete-' + brandinfo['brandid'] + '" data-toggle="tooltip" title="Delete Item" class="fbrdeletebtn btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-trash"></i></button>&nbsp');
			strhtml = strhtml.concat('</td>');
			strhtml = strhtml.concat('<td id="fbrdescription-' + brandinfo['brandid'] + '" class="clickable fbrdescription col-codes aimslabel">' + brandinfo['brand'] + '</td>');
			strhtml = strhtml.concat('</tr>');
		}); //end for each
		$('.fbrbrandtbl').html(strhtml);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function retrieve e brands

