$(document).on('click', '.fbrsavebrand', debounce(function () {
	var brand = $('#txtnewbrand').val();
	var params = {
		brand: brand
	};
	if (brand == "") {
		generateAlert('warning', 'Error', 'ERROR')
	} else {
		saveFBRBrand(params, 'NEW');
	}
}, 300));

function saveFBRBrand(params, type) {
	switch (type) {
		case 'NEW':
			paramxz = {
				type: 'new',
				brand: params['brand']
			};
			break;

		case 'EDIT':
			paramxz = {
				type: 'edit',
				q: params['keyid'],
				brand: params['brand']
			};
			break
	} //end switch

	$.get(domain + '/fbrmanager/managebrand', paramxz, function (data) {


		if (data.status) {
			generateAlert('information', data.msg, 'DEFAULT');
			switch (type) {
				case 'NEW':
					$('#modal-addnewbrand').modal('hide');
					$('#txtnewbrand.txtnewbrand').val('');
					retrieve_Ebrands(2, ''); // retrieves all brands
					break;

				case 'EDIT':
					plotBrandDetailPerLine(data.brdetails[0]);
					break;
			} //end switch
		} else {
			generateAlert('error', data.msg, 'ERROR');
			switch (type) {
				case 'NEW':
					$('#txtnewbrand.txtnewbrand').val('');
					$('#txtnewbrand').focus();
					break;

				case 'EDIT':
					plotBrandDetailPerLine(data.brdetails[0]);
					break;
			} //end switch
		} //end if

	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function FBR Brands

