function multipleVoid() {
	var moduleid = $('#viewmoduleid').val();
	voidMultipleItems(function (data) {
		if (data) {
			var msg = '';
			$('#modal-multivoid').modal('hide');
			$.each(data.return, function (i, info) {
				if (info.status == 1) {
					switch (moduleid) {
						case 'SO':
						case 'PO':
						case 'QA':
							$('#gvrow-' + info.line + ' input[coltype=void]').attr('value', '1');
							break;
					}
					msg = msg.concat('Line ' + info.line + ': [SUCCESS] ' + info.msg + '<br>');
				} else {
					msg = msg.concat('<b>Line ' + info.line + ': [ERROR] ' + info.msg + '</b><br>');
				} //end if
			});
			checkifvoidPosted();
			generateAlert('information', msg, 'ERROR');
		} //end if
	});
} //end function

function voidMultipleItems(callback) {
	var moduleid = $('#viewmoduleid').val(),
		rowarr = [],
		trno = $('.txtboxtrno').val();
	$('#tbl-multivoid tbody tr input.gridcheckbox:checked').each(function () {
		rowid = $(this).parent().parent().attr('id');
		rowid = rowid.split('-');
		rowid = rowid[1];
		rowarr.push({
			trno: trno,
			line: rowid
		});
	});

	$.get(domain + '/' + moduleid + '/voidmultipleitems', {
		params: rowarr
	}, function (data) {

		callback(data);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end fucntion

