function retrieveAvailableOnSaleItems(searchstring) {
	var moduleid = $('#viewmoduleid').val();
	$('.fsalelisttbl').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
	$.get(domain + '/' + moduleid + '/getonsaleitems', {
		searchstring: searchstring
	}, function (data) {

		var strhtml = '';
		var disablethis = '';
		$.each(data.onsaleitems, function (i, info) {
			if (info['underhighlight'] == 1) {
				disablethis = 'disabled';
				strhtml = strhtml.concat('<tr bgcolor ="#EC7063">');
			} else {
				disablethis = '';
				strhtml = strhtml.concat('<tr>');
			} //end

			strhtml = strhtml.concat('<td id="fbtngrp-' + info['itemid'] + '" class="col-checkbox btblcenter aimslabel">');

			if (arrayofvalues[info['itemid']]) {
				strhtml = strhtml.concat('<input ' + disablethis + ' checked type="checkbox" class="fsalechecker" id="fsalechecker-' + info['itemid'] + '">');
			} else {
				strhtml = strhtml.concat('<input ' + disablethis + ' type="checkbox" class="fsalechecker" id="fsalechecker-' + info['itemid'] + '">');
			} //end if

			strhtml = strhtml.concat('</td>');
			strhtml = strhtml.concat('<td id="fsalestart-' + info['itemid'] + '" class="col-min aimslabel">' + info['promostart'] + '</td>');
			strhtml = strhtml.concat('<td id="fsaleend-' + info['itemid'] + '" class="col-min aimslabel">' + info['promoend'] + '</td>');
			strhtml = strhtml.concat('<td id="fbarcode-' + info['itemid'] + '" class="col-description aimslabel">' + info['barcode'] + '</td>');
			strhtml = strhtml.concat('<td id="fitemname-' + info['itemid'] + '" class="col-description aimslabel">' + info['itemname'] + '</td>');
			strhtml = strhtml.concat('<td id="fhighlight-' + info['itemid'] + '" class="col-description aimslabel">' + info['highlight'] + '</td>');
			strhtml = strhtml.concat('<td id="fqty-' + info['itemid'] + '" class="col-quantity aimslabel">' + info['qty'] + '</td>');
			strhtml = strhtml.concat('<td id="famt-' + info['itemid'] + '" class="col-currency aimslabel">' + info['saleprice'] + '</td>');
			strhtml = strhtml.concat('</tr>');
		});
		$('.fsalelisttbl').html(strhtml);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function

