$(document).on('click', '.addnewhighlightbtn', function () {
	$('#modal-addnewhighlight').modal();
});


function modifyHighlight(params, modif_type) {
	switch (modif_type) {
		case 'new':
			var parameters = {
				type: modif_type,
				hnew: params
			};
			break;

		case 'edit':
			var parameters = {
				type: modif_type,
				hupdate: params
			};
			break;
	} //end switch

	$.get(domain + '/' + 'fhighlights/modifyhighlight', parameters, function (data) {

		if (data.status) {
			switch (modif_type) {
				case 'new':
					$('#modal-addnewhighlight').modal('hide');
					$('#txtnewhighlight').val('');
					retrieveHighlights(2, '');
					break;

				case 'edit':
					var highcode = $('.modifyhighkey').val();
					$('.fhform').prop('disabled', true);
					$('.highupdateinfobtn').css('display', 'none');
					$('.highcancelinfobtn').css('display', 'none');
					$('.higheditinfobtn').css('display', 'inline');
					$('.highlightsadditembtn').prop('disabled', false);
					$('.highlightsdeleteselectedbtn').prop('disabled', false);
					retrieveHighlights(2, '');
					retrieveHighlightItem(highcode, function (data) {
						plotHighlightItems(data.hitems);
					});
					break;
			} //end switch
			generateAlert('information', data.msg, 'DEFAULT');
		} else {
			generateAlert('error', data.msg, 'ERROR');
		} //end if
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function new highlight


