function retrieveHighlights(tagging, searchstring) {
	//0 for frontend disabled highlights
	//1 for frontend enabled highlights
	//2 for all highlights (mostly used on highlights)

	$('.fhighlighttbl').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
	$.get(domain + '/fhighlights/modifyhighlight', {
		type: 'retrieve',
		tag: tagging,
		v: searchstring
	}, function (data) {
		$('.fhighlighttbl').html('');

		var strhtml = "";
		$.each(data.highlights, function (highindex, highinfo) {
			strhtml = strhtml.concat('<tr>');
			strhtml = strhtml.concat('<td id="" class="col-checkbox btblleft aimslabel">');
			if (highinfo.isfeatured == 1) {
				strhtml = strhtml.concat('<input type="checkbox" class="fhenablefrontend" id="fhenable-' + highinfo['highkey'] + '" checked>');
			} else {
				strhtml = strhtml.concat('<input type="checkbox" class="fhenablefrontend" id="fhenable-' + highinfo['highkey'] + '">');
			} //end if
			strhtml = strhtml.concat('</td>');
			strhtml = strhtml.concat('<td id="fhbuttons-' + highinfo['highkey'] + '" style="margin-bottom:-5px;" class="fhbuttons btblleft aimslabel col-min">');
			strhtml = strhtml.concat('<button id="fhedit-' + highinfo['highkey'] + '" data-toggle="tooltip" title="Edit Item" class="fheditbtn btn btn-social-icon btn-github" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-eye"></i></button>&nbsp');
			strhtml = strhtml.concat('<button id="fhdelete-' + highinfo['highkey'] + '" data-toggle="tooltip" title="Delete Item" class="fhdeletebtn btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-trash"></i></button>&nbsp');
			strhtml = strhtml.concat('</td>');
			strhtml = strhtml.concat('<td id="fhdescription-' + highinfo['highkey'] + '" class="clickable fhdescription col-codes aimslabel">' + highinfo['high_desc'] + '</td>');
			strhtml = strhtml.concat('</tr>');
		}); //end for each
		$('.fhighlighttbl').html(strhtml);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //
} //end function retrieve e brands

