$(document).on('submit', '.headerupload', function (e) {
	e.preventDefault();

	var thisid = $(this).prop('id').split('-');
	var moduleid = $('#viewmoduleid').val();
	var formvalues = new FormData(this);

	switch (moduleid) {
		case 'lanemanager':
			formvalues.append("codeid", $('#managelaneid').val());
			$('.headerpic').prop('src', '');
			break;
	} //end switch

	$('#overlay').css('display', 'block');
	$.ajax({
		type: "POST",
		url: domain + '/' + moduleid + '/uploadheaderimage',
		data: formvalues,
		processData: false,
		contentType: false,
		success: function (result) {


			switch (moduleid) {
				case 'lanemanager':
					$('.headerpic').prop('src', result.picture + "?" + new Date().valueOf());
					break;
			} //end switch

			$('#overlay').css('display', 'none');
			$('#huploadsave').css('display', 'none');
			$('#huploadcancel').css('display', 'none');
			//$('.uploadedpicture').val('');
		}
	});
});

