function insertItemToDOD() {
	var doditemid = $('#txtdoditemid_setprice').val();
	var dodsaleprice = $('#txtdoditemprice').val();
	var dodkey = $('.modifydodkey').val();

	$.get(domain + '/managedod/modifydod', {
		type: 'INSERT_DOD_ITEM',
		v: doditemid,
		price: dodsaleprice,
		dodk: dodkey
	}, function (data) {

		if (data.status) {
			$('#modal-dodsetprice').modal('hide');
			manageDOD(dodkey, 'RETRIEVE_DOD_ITEMS', function (data) {
				plotDODItems(data);
			}); //end function manage dod
		} else {
			generateAlert('error', data.msg, 'ERROR');
		} //end function
	});
} //end funciton insert item to dod

