$(document).on('click', '.btnsavecategory', debounce(function () {
	var btnobj = $(this);
	var liner = btnobj.attr('id').split('-');
	var line = liner[1];
	$('#lines').val(line);
	$('#overlay').css('display', 'block');
	var moduleid = $('#moduleid').val();
	var catcode = $('#edittxtcatcode-' + line).val();
	var catname = $('#edittxtcatname-' + line).val();
	$.get(domain + '/' + moduleid + '/updatecategory', {
		catcode: catcode,
		catname: catname,
		line: line
	}, function (data) {

		alert(data);
		$('#overlay').css('display', 'none');
		$('#catcode-' + line).html(data.catcode);
		$('#catname-' + line).html(data.catname);

		$('#stockbuttons-' + line).html('<button id="categoryedit-' + line + '"class="stockbtn btneditcategory btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></button>\
	        		<button id="categorydelete-' + line + '" class="stockbtn btndeletecategory btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-trash"></i></button>');

	});


}, 300)); //end save terms line

$(document).on('click', '.btndeletecategory', debounce(function () { // delete terms
	var liner = $(this).prop("id").split('-');
	var line = liner[1];

	var params = {
		line: line
	};

	generateMessagebox("Do you want to delete this category data?", "REMOVE_CATEGORY", params);

	$('.module-btncancelcategory').css('display', 'none');
	$('.module-btnsavecategory').css('display', 'none');
	$('.module-btnnewcategory').css('display', 'inline');

}, 300)); // END DELETE TERMS


function removecategories(line) {
	var moduleid = $('#viewmoduleid').val();

	$.get(domain + '/' + moduleid + '/deletecategory', {
		line: line
	}, function (data) {

		$('#overlay').css('display', 'none');
		$('#cat-modulebody').html("");
		plotcategorytable(data.catdata);
		$('#categorytext').css('display', 'none');

	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax

}

$(document).on('click', '.btncancelcategory', debounce(function () {

	$('#overlay').css('display', 'block');
	var liner = $(this).prop("id").split('-');
	var moduleid = $('#moduleid').val();
	var line = liner[1];
	$.get(domain + '/' + moduleid + '/canceleditcategory', {
			line: line
		},
		function (data) {


			$('#orgrow-' + line).removeClass('editing saveable');
			$('#overlay').css('display', 'none');
			$('#catcode-' + line).html(data.catcode);
			$('#catname-' + line).html(data.catname);

			$('#stockbuttons-' + line).html('<button id="categoryedit-' + line + '"class="stockbtn btneditcategory btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></button>\
	        		<button id="categorydelete-' + line + '" class="stockbtn btndeletecategory btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-trash"></i></button>');
		});
}, 300)); //end cancel tax line


$(document).on('click', '.module-btnnewclass', debounce(function () { // new
	var moduleid = $('#viewmoduleid').val();
	$('.aimslabel3').css('display', 'block');
	$('.input-sm').val('');
	$('#classtext').css('display', 'block');
	$('#classfocus').focus();
	$('.module-btnnewclass').css('display', 'none');
	$('.module-btnsaveclass').css('display', 'inline');
	$('.module-btncancelclass').css('display', 'inline');
	$('#savingtype').val('new');
}, 300)); // NEW TERMS


$(document).on('click', '.module-btnsaveclass', debounce(function () {
	var action = $('#savingtype').val();
	if (action == 'new') {
		var moduleid = $('#viewmoduleid').val();
		var classcode = $('.txtclasscode').val();
		var classname = $('.txtclassname').val();
		$('#overlay').css('display', 'block');
		$.get(domain + '/' + moduleid + '/insertclass', {
			classcode: classcode,
			classname: classname
		}, function (data) {

			$('#overlay').css('display', 'none');
			$('#class-modulebody').html("");
			plotclasstable(data.classdata);
			$('#classtext').css('display', 'none');
		}).fail(function (jqXHR, textStatus, error) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		}); //end ajax
	} else {
		var liner = $(this).prop("id").split('-');
		var line = $('#catid').val();
		var moduleid = $('#viewmoduleid').val();
		var classcode = $('.edittxtclasscode').val();
		var classname = $('.edittxtclassname').val();
		$('#overlay').css('display', 'block');
		$.get(domain + '/' + moduleid + '/updateclass', {
			classcode: classcode,
			classname: classname,
			line: line
		}, function (data) {

			$('#overlay').css('display', 'none');
			$('#class-modulebody').html("");
			plotclasstable(data.classdata);
			$('#classtext').css('display', 'none');
		}).fail(function (jqXHR, textStatus, error) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		}); //end ajax
	} //end if
	$('.module-btnnewclass').css('display', 'inline');
	$('.module-btncancelclass').css('display', 'none');
	$('.module-btnsaveclass').css('display', 'none');
}, 300)); // END SAVE TERMS

function plotclasstable(classdata) {
	$.each(classdata, function (dataindx, datainfo) {
		$('.class-modulebody').append('<tr>\
		           	<td style="margin-bottom:-5px;" id="classcode-' + classdata[dataindx]['cl_id'] + '" class="origdata col-xs-3 aimslabelstock">' + classdata[dataindx]['cl_code'] + '</td>\
		            <td style="margin-bottom:-5px;" id="classname-' + classdata[dataindx]['cl_id'] + '" class="origdata col-xs-7 aimslabelstock">' + classdata[dataindx]['cl_name'] + '</td>\
		            <td id="stockbuttons-' + classdata[dataindx]['cl_id'] + '" style="margin-bottom:-5px;" class="origdata btnstockopt col-xs-2 aimslabelstock">\
	                <button id="classedit-' + classdata[dataindx]['cl_id'] + '" data-toggle="tooltip" title="Edit" class="btneditclass btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-pencil"></i></button>\
	                <button id="classdelete-' + classdata[dataindx]['cl_id'] + '"  data-toggle="tooltip" title="Delete" class="btndeleteclass btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-trash"></i></button></td>\
		            </tr>');

	});
} // end function plotusers



