function insertFlashDealItem() {
	var fdkey = $('.modifyfdkey').val();
	var params = {
		q: $('#txtflashitemid_setprice').val(),
		fd: fdkey,
		'saleprice': $('#txtflashitemprice').val()
	};
	manageFlashDeals(params, 'INSERT_FLASHDEAL_ITEMS', function (data) {
		if (data.status) {
			var params = {
				q: fdkey
			};
			var strhtml = '';
			manageFlashDeals(params, 'RETRIEVE_FLASHDEAL_DETAIL', function (data) {
				$('.fditems').html('');
				$.each(data.flashitems, function (flashindex, flashinfo) {
					strhtml = strhtml.concat('<tr>');
					strhtml = strhtml.concat('<td class="col-min btblleft aimslabel"><span class="text">');
					strhtml = strhtml.concat('<button id="fditemdelete-' + flashinfo['itemid'] + '" data-toggle="tooltip" class="fditemdeletebtn btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;">');
					strhtml = strhtml.concat('<i style="font-size:12px;margin-top:-8px;" class="fa fa-trash"></i></button>&nbsp');
					strhtml = strhtml.concat('</span></td>');
					strhtml = strhtml.concat('<td class="col-codes aimslabel"><span class="text">' + flashinfo['barcode'] + '</span></td>');
					strhtml = strhtml.concat('<td class="col-description aimslabel"><span class="text">' + flashinfo['itemname'] + '</span></td>');
					strhtml = strhtml.concat('<td class="col-currency aimslabel"><span class="text">' + flashinfo['saleprice'] + '</span></td>');
					strhtml = strhtml.concat('</tr>');
				}); //end each
				$('.fditems').append(strhtml);
			}); //end manage flash deals
			$('#modal-itemlookup').modal('hide');
			$('#modal-flashsetprice').modal('hide');
		} else {
			generateAlert('error', 'Error inserting item to this Flash deal! Please try again.', 'ERROR');
		} //end if data.status
	});
} //end function

