function addNewSONote() {
	var moduleid = $('#viewmoduleid').val(),
		formvalues = $('.sonoteform').serializeArray(),
		trno = $('.txtboxtrno').val()

	formvalues.push({
		name: "trno",
		value: trno
	});

	$.ajax({
		type: "POST",
		url: domain + '/' + moduleid + '/savesonote',
		data: formvalues,
		success: function (result) {

			if (result.status) {
				generateAlert('information', result.msg, 'DEFAULT');
				$('#modal-so-note-form').modal('hide');
				$('.sonoteform').val('');
			} else {
				generateAlert('error', result.msg, 'ERROR');
			} //end if
			$('.clicksonotes').click();
		}
	});
} //end function add new sonote

