function retrieveAttachments(trno) {
	$('.attach-1').prop('src', '');
	$('.attach-2').prop('src', '');
	$('.attach-3').prop('src', '');
	$('.attach-4').prop('src', '');
	//RETRIEVES UNLIMITED NUMBER OF ATTACHMENTS PER TRNO
	var moduleid = $('#viewmoduleid').val();
	if (trno != '' && trno != 0) {
		$.get(domain + '/' + moduleid + '/retrieveattachments', {
			q: trno
		}, function (data) {

			//LOOPS EACH FIELDS ON THE ATTACHMENT ARRAY
			$.each(data.attachments[0], function (ainfo) {
				var dsplitter = ainfo.split('_'); // THESE WILL GET THE INDEX PER ATTACHMENT
				if (data.attachments[0]['attach_' + dsplitter[1]] != '') {
					$('.attach-' + dsplitter[1]).prop('src', data.attachments[0]['attach_' + dsplitter[1]]); //THIS LINE WILL PICK THE RIGHT INDEX PIC PER ATTACHMENT INDEX
					$('.attach-' + dsplitter[1]).wrap('<a class="clickable" id="' + data.attachments[0]['attach_' + dsplitter[1]] + '"></a>');
				} //end if
			}); //end each
		}).fail(function (jqXHR, textStatus, error) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		});
	}
} //end function retrieveattachments
