$(document).on('click', '.module-btnsavemaster', debounce(function () {
	var moduleid = $('#viewmoduleid').val(),
		initdiv = masterfilegrid.getProperty('initdiv'),
		savedarray,
		coltype = '',
		vals = '',
		newrowid = '',
		waw = 0,
		rowclass = '',
		temp_masterarraydata = {};

	$(initdiv + ' table tbody tr.edited').each(function () {
		var thisrow = $(this).prop('id');

		//FOR EDITED ROWS (FOR FIELDS WITH CHANGED VALUE)
		$('#' + thisrow + '.edited .mastertextbox.txtrequired').each(function (a, val) {
			if ($(this).val() == '') {
				waw = 1;
			}
		});

		if (waw == 1) {
			generateAlert('warning', 'Please fill-up all Fields!', 'ERROR');
			$('#' + thisrow + '.edited .mastertextbox.txtrequired').css('border', 'solid 1px red');
		} else {
			var formvalues = $("#" + thisrow + ".edited .mastertextbox").serializeArray(),
				arrval = {};
			savedarray = formvalues;

			$.each(savedarray, function (indexx, datum) {
				arrval[datum['name']] = datum['value'];
			});
			if (!$.isEmptyObject(arrval)) {
				$.get(domain + '/' + moduleid + '/savemaster', formvalues, function (data) {


					if (data.status) {
						newrowid = 'gvrow-' + data['data'][0]['line'];
						$('#' + thisrow + '.edited .mastertextbox').each(function () {
							coltype = $(this).attr('coltype');
							vals = data['data'][0][coltype];
							$(this).val(vals);

						});
						$('#' + thisrow + '.edited').css('background', masterfilegrid.savedrowcolor).removeClass();
						generateAlert('success', data.msg, 'SUCCESS');
					} else {
						$('#' + thisrow + '.edited .mastertextbox').each(function () {
							coltype = $(this).attr('coltype');
							vals = data['data'][0][coltype];
							$(this).val(vals);
						});
						$('#' + thisrow + '.edited').removeClass('edited').css('background', '');
						generateAlert('error', data.msg, 'ERROR');
					} //end if
				}).fail(function (jqXHR, textStatus, error) {
					generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
				}); //end ajax
			} //end if	
		} //end if
	}); //en for each

	//FOR TEMPORARY ROWS (FROM NEW BUTTON)
	$(initdiv + ' table tbody tr.temprow').each(function () {
		var thisrow = $(this).prop('id');

		$('#' + thisrow + '.temprow .mastertextbox.txtrequired').each(function (a, val) {
			if ($(this).val() == '') {
				waw = 1;
			}
		}); //end each

		if (waw == 1) {
			generateAlert('warning', 'Please fill-up all Fields!', 'ERROR');
			$('#' + thisrow + '.temprow .mastertextbox.txtrequired').css('border', 'solid 1px red');
		} else {
			var formvalues = $("#" + thisrow + ".temprow .mastertextbox").serializeArray(),
				arrval = {};

			savedarray = formvalues;

			$.each(savedarray, function (indexx, datum) {
				arrval[datum['name']] = datum['value'];
			});

			if (!$.isEmptyObject(arrval)) {
				$.get(domain + '/' + moduleid + '/savemaster', formvalues, function (data) {


					if (data.status) {
						newrowid = 'gvrow-' + data['data'][0]['line'];

						$('#' + thisrow + '.temprow .mastertextbox').each(function () {
							coltype = $(this).attr('coltype');
							vals = data['data'][0][coltype];
							$(this).val(vals);
						});

						$('#' + thisrow + '.temprow .gv-options').html(masterfilegrid.availablebtns);
						$('#' + thisrow + '.temprow').css('background', masterfilegrid.savedrowcolor).attr('id', newrowid).removeClass();
						generateAlert('success', data.msg, 'SUCCESS');
					} else {
						$('#' + thisrow + '.temprow').remove();
						generateAlert('error', data.msg, 'ERROR');
					} //end if


				}).fail(function (jqXHR, textStatus, error) {
					generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
				}); //end ajax
			} //end if	
		} //end if
	}); // end for each
}, 300));

