$(document).on('click', '.mastersave', debounce(function () {
	var btnsave = $(this),
		parentrow = btnsave.parent().parent(),
		parentid = parentrow.attr('id'),
		moduleid = $('#viewmoduleid').val(),
		coltype = '',
		vals = '',
		newrowid = '',
		waw = 0,
		rowclass = '';
	if (parentrow.hasClass('temprow') || parentrow.hasClass('edited')) {
		if (parentrow.hasClass('temprow')) {
			rowclass = 'temprow';
		} else {
			rowclass = 'edited';
		}

		$('#' + parentid + '.' + rowclass + ' .mastertextbox.txtrequired').each(function (a, val) {
			if ($(this).val() == '') {
				waw = 1;
			} //end if
		});

		if (waw == 1) {
			generateAlert('warning', 'Please fill-up required fields!', 'ERROR');
			$('#' + parentid + '.temprow .mastertextbox.txtrequired').css('border', 'solid 1px red');
			$('#' + parentid + '.edited .mastertextbox.txtrequired').css('border', 'solid 1px red');
		} else {
			var formval = $('#' + parentid + ' .mastertextbox').serializeArray();
			$.get(domain + '/' + moduleid + '/savemaster', formval, function (data) {

				newrowid = 'gvrow-' + data['data'][0]['line'];


				if (parentrow.hasClass('temprow')) {
					if (data.status) {
						$('#' + parentid + '.temprow .mastertextbox').each(function () {
							coltype = $(this).attr('coltype');
							vals = data['data'][0][coltype];
							$(this).val(vals);
						});

						$('#' + parentid + '.temprow .gv-options').html(masterfilegrid.availablebtns);
						$('#' + parentid + '.temprow').css('background', masterfilegrid.savedrowcolor).attr('id', newrowid).removeClass();

						generateAlert('success', data.msg, 'SUCCESS');
					} else {
						$('#' + parentid + '.temprow').remove();
						generateAlert('error', data.msg, 'ERROR');
					} //end if							
				} else {
					if (data.status) {
						$('#' + parentid + '.edited .mastertextbox').each(function () {
							coltype = $(this).attr('coltype');
							vals = data['data'][0][coltype];
							$(this).val(vals);
						}); //end each

						$('#' + parentid + '.edited').css('background', masterfilegrid.savedrowcolor).removeClass();
						generateAlert('success', data.msg, 'SUCCESS');
					} else {
						$('#' + parentid + '.edited .mastertextbox').each(function () {
							coltype = $(this).attr('coltype');
							vals = data['data'][0][coltype];
							$(this).val(vals);
						}); //end each
						$('#' + parentid + '.edited').removeClass('edited').css('background', '');
						generateAlert('error', data.msg, 'ERROR');
					} //end if							
				} //end if

			}).fail(function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			}); //end ajax
		}
	}
}, 300));


