$(document).on('click', '.btnsavetg', debounce(function () {
	var btnobj = $(this);
	var liner = btnobj.attr('id').split('-');
	var line = liner[1];
	$('#lines').val(line);
	$('#overlay').css('display', 'block');
	var moduleid = $('#moduleid').val();
	var tgname = $('#edittxttgname-' + line).val();
	var terms = $('#edittxtterms-' + line).val();
	var mgrp = $('#edittxtmgid-' + line).attr('mgid');

	$.get(domain + '/' + moduleid + '/updatetg', {
		tgname: tgname,
		line: line,
		mgrp: mgrp,
		terms: terms
	}, function (data) {

		$('#overlay').css('display', 'none');
		$('#tgname-' + line).html(data.tgname);
		$('#mgid-' + line).html(data.mgid);
		$('#mgterms-' + line).html(data.terms);
		$('#stockbuttons-' + line).html('<button id="tgedit-' + line + '"class="stockbtn btnedittg btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></button>\
	        		<button id="tgdelete-' + line + '" class="stockbtn btndeletetg btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-trash"></i></button>');

	});


}, 300)); //end save terms line


