$(document).on('click', '#refreshroute', function () {
	var urlto = $(this).attr('urlto');
	loadroutes(urlto);
});

$(document).on('click', '.btnnewroute', function () {
	$('#overlay').hide().fadeIn(300);
	$('#routediv').hide().slideDown(300);

	$('.input-sm').val('');
	$('.txtroutecode').focus();
	$('.btnnewroute').css('display', 'none');
	$('.btnsaveroute').css('display', 'inline');
	$('.btncancelroute').css('display', 'inline');

	$('#routeid').val('');
	$('#savingtype').val('new');

	$('#overlay').show().fadeOut(300);
});

$(document).on('click', '.btncancelroute', function () {
	$('#overlay').hide().fadeIn(300);
	$('#routediv').show().slideUp(300);

	$('.btnnewroute').css('display', 'inline');
	$('.btnsaveroute').css('display', 'none');
	$('.btncancelroute').css('display', 'none');

	$('#savingtype').val('edit');

	$('#overlay').show().fadeOut(300);
});

$(document).on('click', '.btnsaveroute', function () {
	var type = $('#savingtype').val(),
		rcode = $('.txtroutecode').val(),
		rname = $('.txtroutename').val(),
		rid = $('#routeid').val(),
		urlto = $(this).attr('urlto');

	if (rcode != '' && rname != '') {
		$.ajax({
			type: 'post',
			url: urlto,
			data: {
				'rid': rid,
				'rcode': rcode,
				'rname': rname,
				'type': type
			},
			success: function (waw) {
				generateAlert('success', waw, 'SUCCESS');
				$('#routediv').show().slideUp(300);
				$('#refreshroute').click();
			},
			error: function (jqXHR, textStatus, error) {
				generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
			}
		});

		$('.btnnewroute').css('display', 'inline');
		$('.btnsaveroute').css('display', 'none');
		$('.btncancelroute').css('display', 'none');
	} else {
		generateAlert('warning', 'Please fill-up all fields', 'SUCCESS');
	}
});

$(document).on('click', '.btneditroute', function () {
	$('#overlay').hide().fadeIn(300);

	var rcode = $(this).attr('routecode'),
		rname = $(this).attr('routename'),
		rid = $(this).attr('id'),
		urlto = $(this).attr('urlto');

	$('#routeid').val(rid);
	$('.txtroutecode').val(rcode);
	$('.txtroutename').val(rname);
	$('#savingtype').val('edit');


	$('.btnnewroute').css('display', 'none');
	$('.btnsaveroute').css('display', 'inline');
	$('.btncancelroute').css('display', 'inline');

	$('#routediv').hide().slideDown(300);
	$('#overlay').show().fadeOut(300);
});

$(document).on('click', '.btndeleteroute', function () {

	var rid = $(this).attr('id'),
		urlto = $(this).attr('urlto');

	$('#routeto').val(urlto);

	var params = {
		line: rid
	};

	generateMessagebox('Do you want to delete this route data?', 'REMOVE_ROUTE', params);

	$('.module-btncancelcategory').css('display', 'none');
	$('.module-btnsavecategory').css('display', 'none');
	$('.module-btnnewcategory').css('display', 'inline');

});

function loadroutes(urlto) {
	$.ajax({
		type: 'post',
		url: urlto,
		success: function (waw) {
			// alert(waw);
			$('.routecontent').html(waw);
		},
		error: function (jqXHR, textStatus, error) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		}
	});
}

function removeroute(line) {
	var urlto = $('#routeto').val();
	$.ajax({
		type: 'post',
		url: urlto,
		data: {
			line: line
		},
		success: function (waw) {
			generateAlert('success', 'Route Deleted', 'SUCCESS');
			$('#refreshroute').click();
		},
		error: function (jqXHR, textStatus, error) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		}
	});
}


