function loadRoutes() {
	var moduleid = $('#viewmoduleid').val(),
		routelookup = new GridViewGenerator(domain + '/' + moduleid + '/getroutes', '.routediv');
	routelookup.initializeGrid();
}


function retrieveAvailableRoutes() {
	var moduleid = $('#viewmoduleid').val();
	var strhtml = ''
	$('.tbl-route').html('');
	$.get(domain + '/' + moduleid + '/getavailroutes', {}, function (data) {

		$('#modal-routelookup').modal();
		$.each(data.routes, function (routeindex, routename) {
			strhtml = strhtml.concat('<tr>');
			strhtml = strhtml.concat('<td class="aimslabel col-min">');
			strhtml = strhtml.concat('<button id="pickroute-' + routename['route_id'] + '" class="pickroute btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-sign-in"></i></button>');
			strhtml = strhtml.concat('</td>');
			strhtml = strhtml.concat('<td id="routename-' + routename['route_id'] + '" class="aimslabel col-description">' + routename['route_name'] + '</td>');
			strhtml = strhtml.concat('</tr>');
		}); //end for each
		$('.tbl-route').html(strhtml);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function retrieva available

