function getSubcCategories() {
	var moduleid = $('#viewmoduleid').val();
	$('.tbl-subcategorygroup').html('');
	$.get(domain + '/' + moduleid + '/getsubcategories', {}, function (data) {
		var strhtml = '';


		$.each(data.subcat, function (sindex, info) {
			strhtml = strhtml.concat('<tr>');
			strhtml = strhtml.concat('<td class="col-min aimslabel">');
			strhtml = strhtml.concat('<a href="#" id="' + info['id'] + '" class="picksgrp btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"> \
        		<i style="font-size:12px; margin-top:-8px;" class="fa fa-sign-in"></i></a></td>');
			strhtml = strhtml.concat('<td id="subgrp-' + info['id'] + '" class="col-codes aimslabel"><span class="text">' + info['sgrp'] + '</span></td>');
			strhtml = strhtml.concat('<td id="maingrp-' + info['id'] + '" class="col-codes aimslabel"><span class="text">' + info['maingrp'] + '</span></td>');
			strhtml = strhtml.concat('<td id="termgrp-' + info['id'] + '" class="col-codes aimslabel"><span class="text">' + info['termgrp'] + '</span></td>');
			strhtml = strhtml.concat('<td id="catgrp-' + info['id'] + '" class="col-codes aimslabel"><span class="text">' + info['catgrp'] + '</span></td>');
			strhtml = strhtml.concat('</tr>');
		}); //end each

		$('.tbl-subcategorygroup').html(strhtml);
		$('#modal-subcategorygroup').modal();
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //enc funciton


