function loadcommission() {
	var moduleid = $('#viewmoduleid').val(),
		comid = $('#comid').val(),
		urlto = domain + '/' + moduleid + '/loadcommission';
	$.ajax({
		type: 'post',
		url: urlto,
		data: {
			comid: comid
		},
		success: function (waw) {
			$('.commcontent1').show();
			$('.commcontent').html(waw).slideDown(300);
		}
	});
}

$(document).on('keyup', '.txtcomcode', function (e) {
	if (e.keyCode == 13) {
		$('#overlay').hide().fadeIn(300);
		var code = $('.txtcomcode').val(),
			moduleid = $('#viewmoduleid').val(),
			urlto = domain + '/' + moduleid + '/searchcom';
		$.ajax({
			type: 'post',
			url: urlto,
			data: {
				code: code
			},
			success: function (wew) {
				if (wew !== '') {

					$('.txtcomcode').val(wew[0].code);
					$('#comcode').val(wew[0].code);
					$('.txtcomname').val(wew[0].name);
					$('.btneditcom').show();
					$('.btndeletecom').show();
					$('#comid').val(wew[0].id);
					loadcommission();
				} else {
					$('.txtcomname').val('');
					$('.btnnewcom').show();
					$('.btneditcom').hide();
					$('.btndeletecom').hide();
					$('.btncancelcom').hide();
					$('.btnsavecom').hide();
					$('.commcontent1').hide();
				}
			}
		});
		$('#overlay').show().fadeOut(300);
	}
});

$(document).on('click', '.btneditcom', function () {
	$('#overlay').hide().fadeIn(300);
	var code = $('.txtcomcode').val();
	$('.txtcomcode1').val(code);
	$('.txtcomcode1').show();
	$('.txtcomcode').hide();
	$('.commcontent1').hide();
	$('#btncommlookup').hide();
	$('.txtcomname').prop('readonly', false);
	setTimeout(function () {
		$('.txtcomcode1').focus();
	}, 300);

	$('#savingtype').val('edit');
	$(this).hide();
	$('.btnnewcom').hide();
	$('.btncancelcom').show();
	$('.btnsavecom').show();
	$('.btndeletecom').hide();
	$('#overlay').show().fadeOut(300);
});

