$(document).on('click', '.arrangelanes', debounce(function () {
	var strhtml = "";
	maxlaneindex = 0;
	$('.currentarrangediv').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
	strhtml = strhtml.concat('<label class="aimslabel">Current Lane Arrangement</label>');
	retrieveFrontendLanes('', function (data) {
		$.each(data.lanes, function (laneindx, lane) {
			maxlaneindex += 1;
			strhtml = strhtml.concat('<button lane="' + lane['navid'] + '" class="arrangelane_current btn btn-flat btn-github settings-btn" style="width:100%;margin-top:3px;">' + lane['nav_desc'] + '</button>');
		}); //end for each
		$('.currentarrangediv').html(strhtml);
		$('.newarrangediv').html("");
		$('#modal-arrangelanes').modal();
	});
}, 300));

$(document).on('click', '.arrangelane_current', debounce(function () {
	if (laneindex_perclick > maxlaneindex) {
		generateAlert('error', 'Indexing Error, Please refresh the page and try again.', 'ERROR');
	} else {
		var myval = $(this).attr('lane');
		$(this).removeClass('arrangelane_current');
		$(this).addClass('arrangelane_new');
		$(this).removeClass('btn-github');
		$(this).addClass('btn-bitbucket');
		$(this).appendTo('.newarrangediv');
		laneindex_perclick += 1;
		laneindexing[myval] = laneindex_perclick;
	} //end if
}, 300));


$(document).on('click', '.arrangelane_new', debounce(function () {
	var myval = $(this).attr('lane');
	$(this).addClass('arrangelane_current');
	$(this).removeClass('arrangelane_new');
	$(this).addClass('btn-github');
	$(this).removeClass('btn-bitbucket');
	$(this).appendTo('.currentarrangediv');
	laneindex_perclick -= 1;
	delete laneindexing[myval];
}, 300));

$(document).on('click', '.rearrange_lanes', debounce(function () {
	if (laneindex_perclick != maxlaneindex) {
		generateAlert('error', 'Before rearangement, all lanes must have specified index. Please set them all first.', 'ERROR');
	} else {
		//EXECUTE REARRANGEMENT
		reArrangeLanes();
	} //end if
}, 300));

function reArrangeLanes() {
	$.get(domain + '/lanemanager/rearrangelanes', {
		arrangement: laneindexing
	}, function (data) {

		if (data.status) {
			laneindex_perclick = 0;
			laneindexing = {};
			maxlaneindex = 0;
			var strhtml = "";
			$('.newarrangediv').html("<label class='aimslabel'>New Lane Arrangement</label>");
			generateAlert('information', data.msg, 'DEFAULT');
			$('.currentarrangediv').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
			$('#lanelisting').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
			strhtml = strhtml.concat('<label class="aimslabel">Current Lane Arrangement</label>');
			retrieveFrontendLanes('', function (data) {
				plotLanes(data.lanes);
				$.each(data.lanes, function (laneindx, lane) {
					maxlaneindex += 1;
					strhtml = strhtml.concat('<button lane="' + lane['navid'] + '" class="arrangelane_current btn btn-flat btn-github settings-btn" style="width:100%;margin-top:3px;">' + lane['nav_desc'] + '</button>');
				}); //end for each
				$('.currentarrangediv').html(strhtml);
			});
		} //end if
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function rearrangelanes

