function plotCollectionList(head, arlist) {
	var strhtml = '';
	var count = 0;

	if (head[0]) {
		$('.txtagentcode').val(head[0]['agentcode'] + '~' + head[0]['agentname']);
		$('.txtagentcodeview').val(head[0]['agentcode'] + '~' + head[0]['agentname']);
		$('.txtnotes').val(head[0]['notes']);
	} //end if

	$('.collect-list').html('');

	$.each(arlist, function (arindex, arinfo) {
		count += 1;
		strhtml = strhtml.concat('<tr>');
		strhtml = strhtml.concat('<td class="aimslabel col-min"><button id="' + arinfo['trno'] + '-' + arinfo['line'] + '" class="btn-remove-kl btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px;margin-top:-8px;" class="fa fa-trash"></i></button></td>');
		strhtml = strhtml.concat('<td class="aimslabel col-codes">' + arinfo['client'] + '</td>');
		strhtml = strhtml.concat('<td class="aimslabel col-description">' + arinfo['clientname'] + '</td>');
		strhtml = strhtml.concat('<td class="aimslabel col-codes">' + arinfo['docno'] + '</td>');
		strhtml = strhtml.concat('<td class="aimslabel col-min">' + arinfo['docdate'] + '</td>');

		if (arinfo['doc'] == 'SJ') {
			strhtml = strhtml.concat('<td class="aimslabel col-min">' + arinfo['docduedate'] + '</td>');
		} else {
			strhtml = strhtml.concat('<td class="aimslabel col-min">------</td>');
		} //end if

		strhtml = strhtml.concat('<td class="aimslabel col-currency">' + $.number(arinfo['db'], amtdecimal) + '</td>');
		strhtml = strhtml.concat('<td class="aimslabel col-currency">' + $.number(arinfo['cr'], amtdecimal) + '</td>');
		strhtml = strhtml.concat('<td class="aimslabel col-currency">' + $.number(arinfo['amt'], amtdecimal) + '</td>');
		strhtml = strhtml.concat('</tr>');
	});

	if (count == 0) {
		$('.kl-btn-addar').css('display', 'none');
		$('.module-btnprint').css('display', 'none');
	} else {
		$('.kl-btn-addar').css('display', 'inline');
		$('.module-btnprint').css('display', 'inline');
	} //end if
	$('.collect-list').append(strhtml);
} //end function collection list

