function retrieveRFSalesOrders(ordertype, route, trnxtype) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/retrieverfso', {
		otype: ordertype,
		route: route,
		trnx: trnxtype
	}, function (data) {

		var strhtml = '';
		$('.tbl-pickpo-detail').html('');
		$('.tbl-pickpo-summary').html('');
		$.each(data.clientpo, function (poindex) {
			strhtml = strhtml.concat('<tr>');
			strhtml = strhtml.concat('<td class="col-min">');
			if (arrayofvalues[data.clientpo[poindex]['trno'] + '-0']) {
				strhtml = strhtml.concat('<input class="ordertaker" type ="checkbox" id="' + data.clientpo[poindex]['trno'] + '-0" checked/>');
			} else {
				strhtml = strhtml.concat('<input class="ordertaker" type ="checkbox" id="' + data.clientpo[poindex]['trno'] + '-0"/>');
			}
			strhtml = strhtml.concat('</td>');
			//strhtml = strhtml.concat('<td class="col-codes">'+data.clientpo[poindex]['yourref']+'</td>');
			strhtml = strhtml.concat('<td class="aimslabel col-codes">' + data.clientpo[poindex]['docno'] + '</td>');
			strhtml = strhtml.concat('<td class="aimslabel col-description">' + data.clientpo[poindex]['customername'] + '</td>');
			strhtml = strhtml.concat('<td class="aimslabel col-min">' + data.clientpo[poindex]['dateid'] + '</td>');
			strhtml = strhtml.concat('<td class="aimslabel col-currency">' + data.clientpo[poindex]['totalamt'] + '</td>');
			strhtml = strhtml.concat('</tr>');
		}); //END EACH
		$('.tbl-pickpo-summary').append(strhtml);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end ufnction retrieve RF Sales Orders

