function retrieveRouteGuide(q) {
	var moduleid = $('#viewmoduleid').val();
	if (q != '') {
		$('#overlay').css('display', 'block');
		$('.tx-routeguide').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
		$.get(domain + '/' + moduleid + '/retrieverouteguide', {
			q: q
		}, function (data) {
			$('.tx-routeguide').html("");
			var strhtml = "";
			$('#overlay').css('display', 'none');


			if (!data.isrg) {
				$('.tx-generaterouteguide').css('display', 'block');
				$('.tx-printout').css('display', 'none');
			} else {
				$('.tx-generaterouteguide').css('display', 'none');
				$('.tx-printout').css('display', 'block');
			} //end if

			$.each(data.routeguide, function (rgindex, rginfo) {
				strhtml = strhtml.concat('<tr>');
				strhtml = strhtml.concat('<td class="col-min aimslabel">');
				strhtml = strhtml.concat('<button id="btnrgedit_' + rginfo['txtrno'] + '_' + rginfo['client'] + '" class="btneditrouteguide btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></button>&nbsp');
				strhtml = strhtml.concat('<button id="btnrgsave_' + rginfo['txtrno'] + '_' + rginfo['client'] + '" class="btnsaverouteguide btn btn-social-icon btn-bitbucket" style="display:none;width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-save"></i></button>&nbsp');
				strhtml = strhtml.concat('<button id="btnrgcancel_' + rginfo['txtrno'] + '_' + rginfo['client'] + '" class="btncancelrouteguide btn btn-social-icon btn-github" style="display:none;width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-times"></i></button></td>');
				strhtml = strhtml.concat('<td class="col-min aimslabel" id="rgno_' + rginfo['txtrno'] + '_' + rginfo['client'] + '">' + rginfo['no'] + '</td>');
				strhtml = strhtml.concat('<td class="col-min aimslabel" id="rgkm_' + rginfo['txtrno'] + '_' + rginfo['client'] + '">' + rginfo['kilometers'] + '</td>');
				strhtml = strhtml.concat('<td class="col-codes aimslabel">' + rginfo['client'] + '</td>');
				strhtml = strhtml.concat('<td class="col-description aimslabel">' + rginfo['clientname'] + '</td>');
				strhtml = strhtml.concat('<td class="col-description aimslabel">' + rginfo['address'] + '</td>');
				strhtml = strhtml.concat('</tr>');
			}); //end for each
			$('.tx-routeguide').append(strhtml);
		}).fail(function (jqXHR, textStatus, error) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		}); //END AJAX1
	} else {
		$('.tx-routeguide').html("");
	} //end if
} //end function


