function searchsoa() {

	var searchthis = $('.txtsearchsoadocno').val();
	var moduleid = $('#viewmoduleid').val();

	var url = domain + '/' + moduleid + '/soadocnolookupsearch';
	$('.tbl-soamodalsearch').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:45%;margin-top:10%;' width='5%'/>");
	$.get(url, {
			searchstring: searchthis
		},
		function (data) {

			$('.tbl-soamodalsearch').html("");
			$.each(data.searchitems, function (searchindex) {
				$('.tbl-soamodalsearch').append('<tr> \
					<td id="stockbuttons" style="margin-bottom:-5px;" class="col-min aimslabelstock"> \
					<a id="' + data.searchitems[searchindex]['docno'] + '" class="searchsoadocumentbtn btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-sign-in"></i></a> \
	               	<td id="soadateid" class="col-description aimslabelstock">' + data.searchitems[searchindex]['docno'] + '</td> \
	               	<td id="soadateid" class="col-description aimslabelstock">' + data.searchitems[searchindex]['dateid'].substring(0, 10) + '</td> \
					<td id="soaclientdoc" class="col-description aimslabelstock">' + data.searchitems[searchindex]['client'] + '</td> \
	              	<td id="soaclientname" class="col-description aimslabelstock">' + data.searchitems[searchindex]['clientname'] + '</td> \
	              	<td id="soarem" class="col-description aimslabelstock">' + data.searchitems[searchindex]['rem'] + '</td> \
	              </td> \
	        	</tr>');
			});
		}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //END AJAX

}


