function plotSoaDetails(docno) {


	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/soaplot', {
		docno: docno
	}, function (data) {

		var strhtml = "";
		$.each(data.soadata, function (indx, info) {

			$('.txtsoadocno').val(data.soadata[indx]['docno']);
			$('.soatxtagent').val(data.soadata[indx]['agentcode'] + '~' + data.soadata[indx]['agentname']);
			$('.soatxtcustomerstatus').val(data.soadata[indx]['cstatus']);
			$('.txtsoadate').val(data.soadata[indx]['dateid']);
			$('.txtsoaclientcode').val(data.soadata[indx]['client']);
			$('.txtsoaclientname').val(data.soadata[indx]['clientname']);


			$('.txtsoatotal').val(data.soadata[indx]['grandtotal']);
			$('.txtsoaunserved').val(data.soadata[indx]['unserved']);
			$('.txtsoaunpaid').val(data.soadata[indx]['db2']);
			$('.txtsoapdc').val(data.soadata[indx]['db']);
			$('.txtgrandtotal').val(parseFloat(data.soadata[indx]['grandtotal']) + parseFloat(data.soadata[indx]['unserved']) + parseFloat(data.soadata[indx]['db2']) + parseFloat(data.soadata[indx]['db']));

			$('.txtsoacrlimit').val(data.soadata[indx]['crlimit']);
			$('.txtsoarem').val(data.soadata[indx]['rem']);
			$('.txtsoareason2').val(data.soadata[indx]['reason1']);
			$('#modal-soadocnolookup').modal('hide');
		}); //end each
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax

} //end plotsoadetails 


