$(document).on('click', '#frontendrelatedtag', debounce(function () {
	var itemid = $('#itemid').val();
	getRelatedItems(itemid);
	$('#modal-frontenditemrelated').modal();
}, 300));

$(document).on('click', '.btnaddrelated', debounce(function () {
	$('#item-lookuptype').val('F_RELATED_ITEM');
	$('#modal-itemlookup').modal().css('z-index', 99999);
}, 300));

$(document).on('click', '.removerelateitem', debounce(function () {
	var i = $('#itemid').val();
	var q = $(this).attr('iitemid');
	var line = $(this).attr('iline');
	removeItemRelation(i, q, line);
}, 300));

function tagtorelatedItems(itag) {
	var itemid = $('#itemid').val();
	$('#overlay').css('display', 'block');
	$.get(domain + '/stockcard/tagrelateditem', {
		q: itag,
		i: itemid
	}, function (data) {

		$('#overlay').css('display', 'none');
		if (!data.status) {
			generateAlert('error', data.msg, 'ERROR');
		} else {
			getRelatedItems(itemid);
		} //end if
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function

function getRelatedItems(itemid) {
	$('#overlay').css('display', 'block');
	$.get(domain + '/stockcard/getrelateditem', {
		i: itemid
	}, function (data) {

		$('#overlay').css('display', 'none');
		plotRelatedItems(data.relateditems);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function

function plotRelatedItems(data) {
	var strhtml = "";
	$('.tbl-modalrelateditem').html('');
	$.each(data, function (x, i) {
		strhtml += '<tr>';
		strhtml += '<td class="col-min aimslabel"><button class="removerelateitem btn btn-social-icon btn-google" iitemid = "' + i['tagitemid'] + '" iline = "' + i['line'] + '"  style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-trash"></i></button></td>';
		strhtml += '<td class="col-description aimslabel">' + i['barcode'] + '</td>';
		strhtml += '<td class="col-description aimslabel">' + i['itemname'] + '</td>';
		strhtml += '</tr>';
	}); //end for each
	$('.tbl-modalrelateditem').html(strhtml);
} //end fnction

function removeItemRelation(i, q, line) {
	$('#overlay').css('display', 'block');
	$.get(domain + '/stockcard/removeitemrelation', {
		i: i,
		q: q,
		line: line
	}, function (data) {

		$('#overlay').css('display', 'none');
		getRelatedItems(i);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end if

$(document).on('click', '.costcenterlookup', debounce(function () {
	varstorage.data('costcenter-plotlocation', 'HEAD');
	var moduleid = $('#viewmoduleid').val(),
		costcenterlookup = new GridViewGenerator(domain + '/' + moduleid + '/getcostcenters', '.costcenterdiv');
	costcenterlookup.initializeGrid();
	$('#modal-costcenter').modal();
}, 300));

$(document).on('click', '.selectcostcenter', debounce(function () {
	var code = $(this).attr('costcode'),
		name = $(this).attr('costname');
	switch (varstorage.data('costcenter-plotlocation')) {
		case 'HEAD':
			$('.txtcostcenter').val(code + '~' + name);
			break;

		default:
			var rowid = varstorage.data('costcenter-plotlocation').prop('id');
			if (varstorage.data('costcenter-plotlocation').hasClass('temprow')) {
				$('#' + rowid + '.temprow input[name="costcenter"]').val(code + '~' + name);
			} else {
				$('#' + rowid + ':not(.temprow) input[name="costcenter"]').val(code + '~' + name);
			} //end if
			break;
	} //end switch case

	$('#modal-costcenter').modal('hide');
	varstorage.removeData('costcenter-plotlocation');
}, 300));


function getAvailableCostCenters(callback) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/getcostcenters', {}, function (data) {

		callback(data);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function

function plotCostCenterList(data, type) {
	var strhtml = '';
	switch (type) {
		case 'lookup':
			var table = '.tbl-costcenter';
			$.each(data, function (i, z) {
				strhtml += '<tr>';
				strhtml += '<td class="col-min aimslabel"><a quickval="' + z.code + '~' + z.name + '" class="selectcostcenter btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-sign-in"></i></a></td>';
				strhtml += '<td class="col-codes aimslabel">' + z.code + '</td>';
				strhtml += '<td class="col-description aimslabel">' + z.name + '</td>';
				strhtml += '</tr>';
			});
			break;

		case 'listform':
			var table = '.costcentertbl';
			$.each(data, function (i, z) {
				strhtml += '<tr>';
				strhtml += '<td class="col-min aimslabel" id="costcenterbtns-' + z.line + '">';
				strhtml += '<a id="editcostcenter-' + z.line + '" quickval="' + z.code + '~' + z.name + '" class="editcostcenter btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-pencil"></i></a>&nbsp';
				strhtml += '<a toremove="' + z.line + '" class="removecostcenter btn btn-social-icon btn-google" style="width:18px;height:18px;margin-top:-2px;"><i style="font-size:12px; margin-top:-8px;" class="fa fa-trash"></i></a>';
				strhtml += '</td>';
				strhtml += '<td id="costcentercode-' + z.line + '" class="col-codes aimslabel">' + z.code + '</td>';
				strhtml += '<td id="costcentername-' + z.line + '" class="col-description aimslabel">' + z.name + '</td>';
				strhtml += '</tr>';
			});
			break;
	} //end swtich case
	$(table).html('');
	$(table).html(strhtml);
} //end function


