$(document).on('click', '.savecostcenter', debounce(function () {
	var tr = $(this).closest('tr').attr('id'),
		line = $(this).closest('tr').find('input[coltype=line]').val(),
		code = $(this).closest('tr').find('input[coltype=code]').val(),
		name = $(this).closest('tr').find('input[coltype=name]').val();
	if ($('#costcentertbl tr#' + tr).hasClass('edited') || $('#costcentertbl tr#' + tr).hasClass('temprow')) {
		saveCostCenter(code, name, line, tr);
	}
}, 300));

function saveCostCenter(c, n, l, tr) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/savecostcenter', {
		code: c,
		name: n,
		line: l
	}, function (data) {

		if (data.status) {
			if (l == 0) {
				$('#' + tr + '.temprow input[coltype=line]').val(data.line);
				$('#' + tr + '.temprow').css('background', costcentergrid.savedrowcolor);
			} else {
				$('#' + tr + '.edited').css('background', costcentergrid.savedrowcolor);
			}
			$('#' + tr + '.temprow .gv-options').html(costcentergrid.availablebtns);
			$('#' + tr).removeClass();
			generateAlert('information', data.msg, 'DEFAULT');
		} else {
			generateAlert('error', data.msg, 'ERROR');
		} //end if
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function


$(document).on('click', '.deletecostcenter', debounce(function () {
	var removeline = $(this).closest('tr').attr('id').split('-');
	removeline = removeline[1];
	removeCostCenter(removeline);
}, 300));

function removeCostCenter(line) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/removecostcenter', {
		q: line
	}, function (data) {

		if (data.status) {
			generateAlert('information', data.msg, 'DEFAULT');
			$('#gvrow-' + line + ':not(.temprow)').remove();
		} else {
			generateAlert('error', data.msg, 'ERROR');
		} //end if
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end function

