function setImgBlank(type, params) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/setimgblank', {
		type: type,
		i: params.i,
		q: params.q
	}, function (data) {

		switch (type) {
			case 'stockcard_gallery':
				if (data.status) {
					$('.gallerypic-' + params.i).prop('src', data.img + "?" + new Date().valueOf());
				} //end if
				break;
		} //end switch
		$('#modal-showattachment').modal('hide');
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end switch

