$(document).on('click', '.reportcostcenterlookup', function () {
	$('#modal-costcenterfilter').modal();
	loadCostCenters();
});


function loadCostCenters() {
	$('.tbl-center').html("<img src='" + domain + "/backendassets/img/loading.gif' class='preloader' style='position:absolute;margin-left:37%;margin-top:20%;' width='15%'/>");
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/getcostcenters', function (data) {
		$('.tbl-center').html("");

		$.each(data.centers, function (dataindx, dataname) {
			$('.tbl-center').append('<tr>\
			<td class="col-xs-2 aimslabel"><a href="#" id="' + data.centers[dataindx]['line'] + '" class="pickcostcenter btn btn-social-icon btn-bitbucket" style="width:18px;height:18px;margin-top:-2px;"> \
        	<i style="font-size:12px; margin-top:-8px;" class="fa fa-sign-in"></i></a></td>\
			<td class="col-xs-6 aimslabel" id ="costcentercode-' + data.centers[dataindx]['line'] + '">' + data.centers[dataindx]['code'] + '</td>\
        	<td class="col-xs-4 aimslabel" id ="costcenterame-' + data.centers[dataindx]['line'] + '">' + data.centers[dataindx]['name'] + '</td>\
        	</tr>');
		}); //END FOR EACH
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //END GET ITEM BALANCE


$(document).on('click', '.pickcostcenter', debounce(function () {
	var myid = $(this).attr('id');
	var code = $('#costcentercode-' + myid).html();
	$('.txtcostcenterfilter').val(code);
	$('#modal-costcenterfilter').modal('hide');
}, 300));


$(document).on('click', '.saveotherremarks', debounce(() => {
	var formvalues = $(".othernote.activeform").serializeArray();
	var moduleid = $('#viewmoduleid').val();
	var clientid = $('#clientid').val();
	formvalues.push({
		name: "clientid",
		value: clientid
	});
	$('#overlay').css('display', 'block');
	$.ajax({
		type: 'post',
		url: domain + '/' + moduleid + '/saveremarks',
		data: formvalues,
		success: function (data) {

			$('#overlay').css('display', 'none');
			if (data.status) {
				generateAlert('information', data.msg, 'DEFAULT');
			} else {
				generateAlert('error', data.msg, 'ERROR');
			} //end funciton
		}, //end switch success
		fail: function (xhr, textStatus, errorThrown) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		} //end switch fail
	}); //end ajax
}, 300));

$(document).on('click', '#otherinfotab', debounce(() => {
	var q = $('#clientid').val();
	getOtherRemarks(q);
}, 300));

function getOtherRemarks(q) {
	var formvalues = $(".othernote.activeform").serializeArray();
	$(".othernote.activeform").val('');
	var moduleid = $('#viewmoduleid').val();
	formvalues.push({
		name: "clientid",
		value: q
	});
	$('#overlay').css('display', 'block');
	$.ajax({
		type: 'post',
		url: domain + '/' + moduleid + '/getothernotes',
		data: formvalues,
		success: function (data) {

			$('#overlay').css('display', 'none');
			$.each(data.notes, function (i, x) {
				$.each(x, function (ii, iii) {
					$("#" + ii).val(iii);
				});
			});
		}, //end switch success
		fail: function (xhr, textStatus, errorThrown) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		} //end switch fail
	}); //end ajax
} //end function

$(document).on('click', '.discplotbtn', debounce(function () {
	var discval = $('.newdisc').val();
	if (discval == '') {
		discval = 0;
	} //end if
	$('#modulestockview tbody tr').each(function () {
		var rowobj = $(this).closest('tr');
		if (!$(this).hasClass('temprow')) {
			var thisrow = $(this).prop('id');
			var formvalues = $("#" + thisrow + " .bodytextbox").serializeArray();
			checkrowrecord(formvalues, rowobj, function (data) {
				plotcheckrowrecords(data, rowobj, 'textedit', '');
				var vat = $('.txttax').val();
				$('.txtisdisc').val(discval);
				stockview.changeRowColor(rowobj);
				stockview.saveAllButtons();
				computeStock(rowobj, vat);
			});
		} //end if
	});
	$('#modal-showdisc').modal('hide');
}, 300));

