function clearStockcardGridviews() {
	var moduleid = $('#viewmoduleid').val();
	switch (moduleid) {
		case 'stockcard':
			$('.stockpo').html('');
			$('.stockso').html('');
			$('.stockreceiving').html('');
			$('.stockcardledger').html('');
			$('.stockcard-spc').html('');
			$('.stockwh').html('');

			$('.stockcardtabs').removeClass('active');
			$('.tab-pane').removeClass('active');
			$('#tab_6').addClass('active');
			$('#clickprop').addClass('active').click();
			break;


		case 'posstockcard':
			$('.stockcardledger').html('');
			$('.stockreceiving').html('');
			$('.stockpacking').html('');
			$('.stockcomponents').html('');
			break;

		case 'supplier':
		case 'customer':
			$('.accttable').html('');
			$('.computeinvdiv').html('');
			break;
	} //end switch
} //end function


