$(document).on('click', '.savecomponentitem', debounce(function () {
	var btnsave = $(this),
		parentrow = btnsave.parent().parent(),
		parentid = parentrow.attr('id'),
		moduleid = $('#viewmoduleid').val(),
		rowclass = '';

	if (parentrow.hasClass('temprow') || parentrow.hasClass('edited')) {
		if (parentrow.hasClass('temprow')) {
			rowclass = 'temprow';
		} else {
			rowclass = 'edited';
		}
		var formval = $('#' + parentid + '.' + rowclass + ' input.componentitemtextbox').serializeArray();

		switch (moduleid) {
			case 'posstockcard':
			case 'stockcard':
				var itemid = $('#itemid').val();
				break;

			case 'manageitem':
				var itemid = $('.txtmenuitemid').val();
				break;
		} //end swtich

		formval.push({
			name: 'itemid',
			value: itemid
		});
		$.get(domain + '/' + moduleid + '/savecomponentitem', formval, function (data) {

			if (data.status === true) {
				if (parentrow.hasClass('temprow')) { // new row
					$('#' + parentid + '.temprow td input[coltype=itemid]').val(data['data'][0].itemid);
					$('#' + parentid + '.temprow td input[coltype=line]').val(data['data'][0].line);
					$('#' + parentid + '.temprow .gv-options').html(componentmenugrid.availablebtns);
					$('#' + parentid + '.temprow').css('background', componentmenugrid.savedrowcolor).attr('id', 'gvrow-' + data['data'][0].line).removeClass();
				} else { // update row
					$('#' + parentid + '.edited').css('background', componentmenugrid.savedrowcolor).removeClass();
				}
				generateAlert('success', data.msg, 'SUCCESS');
			} else {
				generateAlert('error', data.msg, 'WARNING');
			}
		});
	}
}, 300));


