$(document).on('click', '.btnsavequickadds', debounce(function () {
	var txt = $('.txtquickadds').val(),
		type = $('.quickaddstype').val(),
		moduleid = $('#viewmoduleid').val();
	$.ajax({
		type: 'post',
		url: domain + '/' + moduleid + '/savequickadds',
		data: {
			txt: txt,
			type: type
		},
		success: function (waw) {

			$(".txtquickadds").val('');
			$('#modal-quickadds').modal('hide');

			if (waw.status === true) {
				switch (type) {
					case 'Category':
						$('.txtmenucat').val(txt).attr('classid', waw.data[0].line);
						break;
					case 'Major Category':
						$('.txtmenumajcat').val(txt).attr('brandid', waw.data[0].line);
						break;
					case 'Groupings':
						$('.txtmenugroup').val(txt).attr('groupid', waw.data[0].line);
						break;
					case 'Printer':
						$('.txtmenuprinter1').val(txt).attr('modelid', waw.data[0].line);
						break;
				}
				generateAlert('success', waw.msg, 'SUCCESS');
				$('.txtquickadds, .quickaddstype').val('');

			} else {
				generateAlert('warning', waw.msg, 'ERROR');
			} //end success
		} //end success
	});
}, 300));


