function deletechoicemenuitem(type, line) {
	var moduleid = $('#viewmoduleid').val();
	$.ajax({
		type: 'post',
		url: domain + '/' + moduleid + '/deletechoicemenuitem',
		data: {
			type: type,
			line: line
		},
		success: function (waw) {

			if (waw.status === true) {
				generateAlert('success', waw.msg, 'SUCCESS');
				if (type == 'choice') {
					var itemid = $('.txtmenuitemid').val();

					$('#gvrow-' + line).remove();
					setmenuchoicesgrid = new GridViewGenerator(domain + '/' + moduleid + '/loadsetchoices', '.setmenuchoicesdiv');

					setmenuchoicesgrid.initializeGrid(itemid);
					$('.setmenuchoicesparentdiv').show();
					//END
				} else {
					var itemid = $('.txtsetmenuitemid').val();
					var menuid = $('.txtmenuitemid').val();
					var addedparams = [];
					addedparams.push({
						name: "choices",
						value: choices
					}, {
						name: "menuid",
						value: menuid
					});
					setmenuchoicesgrid = new GridViewGenerator(domain + '/' + moduleid + '/loadsetmenuchoicesmenu', '.setmenuchoicesdiv');
					setmenuchoicesgrid.initializeGrid(itemid, null, addedparams);
					$('.setmenuchoicesparentdiv').show();
				}
			} else {
				generateAlert('error', waw.msg, 'WARNING');
			}
		}
	});
}


