$(document).on('click', '.chktablesinactive', function () {
	$('#overlay').css('display', 'block');
	var moduleid = $('#viewmoduleid').val();
	var row = $(this).parent().parent();
	var rowid = row.prop('id');

	if (row.hasClass('temprow')) {
		var cid = $('#' + rowid + '.temprow input[coltype="clientid"]').val();
	} else {
		var cid = $('#' + rowid + ':not(.temprow) input[coltype="clientid"]').val();
	} //end if

	//var cid = ''
	if ($(this).is(":checked")) {
		//ENBLES BRAND ON FRONTEND
		var q = 1;
	} else {
		//DISABLES BRAND ON FRONTEND
		var q = 0;
	} //END IF

	$.get(domain + '/' + moduleid + '/enabletables', {
		q: q,
		qq: cid
	}, function (data) {
		$('#overlay').css('display', 'none');


		switch (data.status) {
			case '1':
				$(this).prop('checked', true);
				break;

			case '0':
				$(this).prop('checked', false);
				break;
		} //end switch
	});
});


