$(document).on('keyup', '.autocomputenet', debounce(function () {
	computeAddItemModal();
}, 300));

function computeAddItemModal() {
	var moduleid = $('#viewmoduleid').val();
	switch (cconfig) {
		case 'UNIVERSE': {
			switch (moduleid) {
				case 'SO':
				case 'SJ':
				case 'CM':
				case 'MI':
				case 'PR':
				case 'PO':
				case 'RR':
				case 'DM':
				case 'IS':
				case 'TS':
				case 'AJ':
				case 'PC':
				case 'TR':
					var qty = 1;
					var amount = $('.qtyitemamt').val();
					var disc = $('.qtydisc').val();
					var uomfactor = $('.selectuompopup').attr('factor');
					var forex = $('.txtforex').val();

					$.get(domain + '/' + moduleid + '/computestock', {
						vat: 0,
						forex: forex,
						displayamt: amount,
						displayqty: qty,
						disc: disc,
						uomfactor: uomfactor
					}, function (data) {

						$('.txtNet').val(data.computeddata['ext']);
					}).fail(function (jqXHR, textStatus, error) {
						generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
					}); //end ajax
					break;
			} //modules

		} //cconfig
		break;
	} //end switch
} //end f


