$(document).on('click', '.btnsavefggrid', function () {
	var tr = $(this).closest('tr'),
		trid = tr.attr('id'),
		tablename = tr.find('input[coltype=tablename]').val(),
		moduleid = $('#viewmoduleid').val(),
		formval = tr.find('input').serializeArray(),
		itemid = $('#itemid').val();
	formval.push({
		name: 'itemid',
		value: itemid
	});
	if (tr.hasClass('edited') || tr.hasClass('temprow')) {
		$.ajax({
			type: 'post',
			url: domain + '/' + moduleid + '/savefggrid',
			data: formval,
			success: function (data) {

				if (data.status === true) {
					generateAlert('success', data.msg, 'SUCCESS');
					switch (tablename) {
						case 'colors':
							if (tr.hasClass('temprow')) {
								$('#fgstockgrid1 tr#' + trid + '.temprow td input[coltype=id]').val(data.data[0]['id']);
								$('#fgstockgrid1 tr#' + trid + '.temprow td input[coltype=color]').val(data.data[0]['color']);
								$('#fgstockgrid1 tr#' + trid + '.temprow td input[coltype=line]').val(data.data[0]['line']);
								$('#fgstockgrid1 tr#' + trid + '.temprow .gv-options').html(fgtabgrid1.availablebtns);
								$('#fgstockgrid1 tr#' + trid + '.temprow').prop('id', 'gvrow-' + data.data[0]['line']).css('background', fgtabgrid1.savedrowcolor).removeClass();
							} else {
								$('#fgstockgrid1 tr#' + trid + '.edited td input[coltype=id]').val(data.data[0]['id']);
								$('#fgstockgrid1 tr#' + trid + '.edited').css('background', fgtabgrid1.savedrowcolor).removeClass();
							}
							break;
						case 'material':
							if (tr.hasClass('temprow')) {
								$('#fgstockgrid2 tr#' + trid + '.temprow td input[coltype=id]').val(data.data[0]['id']);
								$('#fgstockgrid2 tr#' + trid + '.temprow td input[coltype=material]').val(data.data[0]['material']);
								$('#fgstockgrid2 tr#' + trid + '.temprow td input[coltype=line]').val(data.data[0]['line']);
								$('#fgstockgrid2 tr#' + trid + '.temprow .gv-options').html(fgtabgrid2.availablebtns);
								$('#fgstockgrid2 tr#' + trid + '.temprow').prop('id', 'gvrow-' + data.data[0]['line']).css('background', fgtabgrid2.savedrowcolor).removeClass();
							} else {
								$('#fgstockgrid2 tr#' + trid + '.edited td input[coltype=id]').val(data.data[0]['id']);
								$('#fgstockgrid2 tr#' + trid + '.edited').css('background', fgtabgrid2.savedrowcolor).removeClass();
							}
							break;
						case 'cylinder':
							if (tr.hasClass('temprow')) {
								$('#fgstockgrid3 tr#' + trid + '.temprow td input[coltype=id]').val(data.data[0]['id']);
								$('#fgstockgrid3 tr#' + trid + '.temprow td input[coltype=code]').val(data.data[0]['code']);
								$('#fgstockgrid3 tr#' + trid + '.temprow td input[coltype=cylinder]').val(data.data[0]['cylinder']);
								$('#fgstockgrid3 tr#' + trid + '.temprow .gv-options').html(fgtabgrid3.availablebtns);
								$('#fgstockgrid3 tr#' + trid + '.temprow').prop('id', 'gvrow-' + data.data[0]['line']).css('background', fgtabgrid3.savedrowcolor).removeClass();
							} else {
								$('#fgstockgrid3 tr#' + trid + '.edited td input[coltype=id]').val(data.data[0]['id']);
								$('#fgstockgrid3 tr#' + trid + '.edited').css('background', fgtabgrid3.savedrowcolor).removeClass();
							}
							break;
						case 'process':
							if (tr.hasClass('temprow')) {
								$('#fgstockgrid4 tr#' + trid + '.temprow td input[coltype=id]').val(data.data[0]['id']);
								$('#fgstockgrid4 tr#' + trid + '.temprow td input[coltype=code]').val(data.data[0]['code']);
								$('#fgstockgrid4 tr#' + trid + '.temprow td input[coltype=process]').val(data.data[0]['process']);
								$('#fgstockgrid4 tr#' + trid + '.temprow .gv-options').html(fgtabgrid4.availablebtns);
								$('#fgstockgrid4 tr#' + trid + '.temprow').prop('id', 'gvrow-' + data.data[0]['line']).css('background', fgtabgrid4.savedrowcolor).removeClass();
							} else {
								$('#fgstockgrid4 tr#' + trid + '.edited td input[coltype=id]').val(data.data[0]['id']);
								$('#fgstockgrid4 tr#' + trid + '.edited').css('background', fgtabgrid4.savedrowcolor).removeClass();
							}
							break;
					}
				} else {
					generateAlert('error', data.msg, 'ERROR');
				}
				$('#overlay').hide();
			},
			beforeSend: function () {
				$('#overlay').show();
			}
		});
	}
});

