$(document).on('click', '.btndeletefggrid', function () {
	var moduleid = $('#viewmoduleid').val(),
		tr = $(this).closest('tr'),
		trid = tr.attr('id').split('-'),
		type = tr.find('input[coltype=tablename]').val();
	trid = trid[1];
	var params = {
		trid: trid,
		type: type
	};
	deletefggrid(params);
});

function deletefggrid(params) {
	var moduleid = $('#viewmoduleid').val();
	$.ajax({
		type: 'post',
		url: domain + '/' + moduleid + '/deletefggrid',
		data: {
			id: params['trid'],
			type: params['type']
		},
		success: function (data) {

			if (data.status === true) {
				generateAlert('success', data.msg, 'SUCCESS');
				switch (params['type']) {
					case 'colors':
						$('#fgstockgrid1 tr#gvrow-' + params['trid'] + ':not(.temprow)').remove();
						break;
					case 'material':
						$('#fgstockgrid2 tr#gvrow-' + params['trid'] + ':not(.temprow)').remove();
						break;
					case 'cylinder':
						$('#fgstockgrid3 tr#gvrow-' + params['trid'] + ':not(.temprow)').remove();
						break;
					case 'process':
						$('#fgstockgrid4 tr#gvrow-' + params['trid'] + ':not(.temprow)').remove();
						break;
				}
			} else {
				generateAlert('error', data.msg, 'ERROR');
			}
		}
	});
}

