function loadTranstype() {
	var transgroup = {
		0: 'REGULAR',
		1: 'SENIOR'
	};

	$('#transtype option:not(:selected)').remove();
	$.each(transgroup, function (modeindx, modename) {
		if (transgroup[modeindx] != $('#transtype option:selected').text()) {
			$('#transtype').append('<option>' + transgroup[modeindx] + '</option>');
		} //END IF
	});
}

