function insertCommissionData() {
	var trno = $('.txtboxtrno').val(),
		moduleid = $('#viewmoduleid').val(),
		agent = $('.commagent').val(),
		grandtotal = $('.commgrandtotal').val(),
		baseamt = $('.commbaseamt').val(),
		standardpercent = $('.commstandardcomm').val(),
		standardamt = $('.commstandardamt').val(),
		standardsharepercent = $('.commsharecomm').val(),
		standardsharedamt = $('.commshareamt').val(),
		commcutoff = $('.commcutoff').val();
	baseamt = baseamt.replace(",", "");
	standardamt = standardamt.replace(",", "");
	standardsharedamt = standardsharedamt.replace(",", "");
	if (agent == "" || baseamt == "" || standardpercent == "" || standardamt == "" || standardsharepercent == "" || standardsharedamt == "") {
		generateAlert('error', 'Please fill up all fields first!', 'ERROR');
	} else {
		$.get(domain + '/' + moduleid + '/insertcommdata', {
			cdate: commcutoff,
			ag: agent,
			q: trno,
			gtotal: grandtotal,
			bamt: baseamt,
			spercent: standardpercent,
			samt: standardamt,
			sspercent: standardsharepercent,
			ssamt: standardsharedamt
		}, function (data) {

			if (data.status) {
				$('.clickcomm').click();
				$('.commsharecomm').val(0);
				$('.commshareamt').val(0);
				$('.commagent').val('');
			} else {
				generateAlert('error', 'Problem occured please try again.', 'ERROR');
			} //end if
		}).fail(function (jqXHR, textStatus, error) {
			generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
		}); //end 
	} //end if
} //end function
