$(document).on('keydown', '#modulestockview tbody tr input', debounce(function (e) {
	var coltype = $(this).attr('coltype');
	e.preventDefault(); // prevent the default action (scroll / move caret)
	switch (e.which) {
		case 37: // left
			var rowobj = $(this).closest('tr');
			var i = rowobj.prop('id').split('-');
			var nextcol_i = parseInt($(this).closest('td').index()) - parseInt(1);
			var nextindex = parseInt(i[1]) - parseInt(1);
			rowobj.find("td:eq(" + nextcol_i + ") input").focus().select();
			break;

		case 39: // right
			var rowobj = $(this).closest('tr');
			var i = rowobj.prop('id').split('-');
			var nextcol_i = parseInt($(this).closest('td').index()) + parseInt(1);
			rowobj.find("td:eq(" + nextcol_i + ") input").focus().select();
			break;

		case 38: // up
			var rowobj = $(this).closest('tr');
			var i = rowobj.prop('id').split('-');
			var nextindex = parseInt(i[1]) - parseInt(1);
			$("#modulestockview tbody #gvrow-" + nextindex + " input[coltype=" + coltype + "]").focus().select();
			break;

		case 40: // down
			var rowobj = $(this).closest('tr');
			var i = rowobj.prop('id').split('-');
			var nextindex = parseInt(i[1]) + parseInt(1);
			$("#modulestockview tbody #gvrow-" + nextindex + " input[coltype=" + coltype + "]").focus().select();
			break;

		case 27: // down
			$(this).blur();
			break;
	} //end switch
}, 10));


