function generateDateParameter(type, counter, callback) {
	if (typeof counter === "undefined" || counter === null) {
		counter = 0;
	} //end if

	if (typeof type === "undefined" || type === null) {
		type = 'CURRENT';
	} //end if

	$.get(domain + '/admin/generatedateparameter', {
		type: type,
		counter: counter
	}, function (data) {

		callback(data);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end function



