function validateSeries(series, callback) {
	$.get(domain + '/admin/checkseries', {
		series: series
	}, function (data) {

		callback(data);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end fn

$(document).on('keyup', '.txtsetdocno', debounce(function (e) {
	var txt = $(this).val();
	let match = 0;
	let prefixlist = '';
	var q = varstorage.data("copytranskey");

	if (e.keyCode == "13") {
		if (txt == "") {
			generateAlert('error', "Please enter desired Document #, Document # can`t be blank", 'ERROR');
		} else {
			requestAvailPrefixes(function (data) {
				$.each(data.prefixes, function (i, x) {
					if (prefixlist == "") {
						prefixlist += x;
					} else {
						prefixlist += ',' + x;
					} //enf if

					if (txt.substring(0, 2) == x) {
						match = 1;
					} //END IF
				}); //END FOR EACH

				if (txt.length <= 2) {
					generateAlert('error', 'Please enter valid series', 'ERROR');
				} else {
					if (match == 0) {
						generateAlert('error', 'Please enter valid prefix. Available Prefix Are :' + prefixlist, 'ERROR');
					} else {
						validateSeries(txt, function (data) {
							if (data.status) {
								copyTransactionDetails(q, 'SO', txt, function (data) {
									ajaxSearchDoc(data.docno);
									$('#modal-copyso').modal('hide');
									$('#modal-setdocno').modal('hide');
									$('.txtsetdocno').val('');
								});
							} else {
								generateAlert('error', 'Series already used (' + data.docno + '). Please try another', 'ERROR');
							} //end if
						});
					} //end if
				} //end if
			});
		} //end if
	} //end if
}, 300));

function requestAvailPrefixes(callback) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/availprefixes', {}, function (data) {

		callback(data);
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end fn

