$(document).on('click', '.btnclickprocess', debounce(function () {
	varstorage.data('fgu_processtrno', $(this).attr('trno'));
	varstorage.data('fgu_processline', $(this).attr('line'));
	varstorage.data('fgu_processbarcode', $(this).attr('barcode'));

	getProcessDetails($(this).attr('trno'), $(this).attr('line'), $(this).attr('barcode'), function (data) {
		$('#processstatus').html('<option>' + data.details[0]['process_status'] + '</option>');
		$('.txtfbuupdate.txtdateid').val(data.details[0]['process_date']);
		$('.txtfbuupdate.txtmachinenum').val(data.details[0]['process_machine']);
		$('.txtfbuupdate.txtoperator').val(data.details[0]['process_operator']);
		$('.txtfbuupdate.txtqa').val(data.details[0]['process_qa']);
		$('.txtfbuupdate.txtdateidstart').val(data.details[0]['process_startdate']);
		$('.txtfbuupdate.txtdateidend').val(data.details[0]['process_enddate']);
		$('.txtfbuupdate.txthrs').val(data.details[0]['process_hrs']);
		$('.txtfbuupdate.txtnotes').val(data.details[0]['process_notes']);
		$('.txtfbuupdate.txttimestart').val(data.details[0]['process_timestart']);
		$('.txtfbuupdate.txttimefinish').val(data.details[0]['process_timeed']);
		loadAvailableProcessStatus();
		$('#modal_viewfguprocess_details').modal();
	});

	getDiscrepancy(varstorage.data('fgu_processtrno'), function (data) {
		$('.jbu_disc_kgs').html(data.dis_kgs);
		$('.jbu_disc_m').html(data.dis_m);
		$('.jbu_disc_mpercent').html(data.m_per);
	});
}, 300));

function loadAvailableProcessStatus() {
	var processstatus = {
		0: 'HALFWAY',
		1: 'COMPLETED'
	};
	$('#processstatus option:not(:selected)').remove();
	$.each(processstatus, function (modeindx, modename) {
		if (processstatus[modeindx] != $('#processstatus option:selected').text()) {
			$('#processstatus').append('<option>' + processstatus[modeindx] + '</option>');
		} //END IF
	});
} //end if

