$(document).on('click', '.selectquarterling', debounce(function () {
	var quarter = $(this).attr('txt');
	$(".viewbyquarter").val(quarter);

	var d = new Date();
	var startd;
	var endd;

	switch (quarter) {
		case '1st Quarter':
			startd = d.getFullYear() + '-01-01';
			endd = d.getFullYear() + '-03-31';
			break;
		case '2nd Quarter':
			startd = d.getFullYear() + '-04-01';
			endd = d.getFullYear() + '-06-30';
			break;
		case '3rd Quarter':
			startd = d.getFullYear() + '-07-01';
			endd = d.getFullYear() + '-09-30';
			break;
		case '4th Quarter':
			startd = d.getFullYear() + '-10-01';
			endd = d.getFullYear() + '-12-31';
			break;
	} //END SWITCH


	$('.txtdateid').val(startd);
	$('.txtdateid2').val(endd);

	$('#modal-quarters').modal('hide');
}, 300));



$(document).on('keyup', '.twincome,.twtaxrate', function (event) {
	var income = $('.twincome').val();
	var rate = $('.twtaxrate').val();
	var wheld = 0.00;

	if (!$.isNumeric(income) || !$.isNumeric(rate)) {
		wheld = 0.00;
	} else {
		wheld = (parseFloat(rate) / 100) * parseFloat(income);
	} //en

	$('.twtaxwithheld').val(wheld);
});


