function loadAvailableTaxMonth() {
	var taxmonth = {
		0: '1',
		1: '2',
		2: '3'
	};

	$('#twtaxmonth option:not(:selected)').remove();
	$.each(taxmonth, function (modeindx, modename) {
		if (taxmonth[modeindx] != $('#twtaxmonth option:selected').text()) {
			$('#twtaxmonth').append('<option>' + taxmonth[modeindx] + '</option>');
		} //END IF
	});
} //end if

function quickaddtax(taxname, taxatc, taxrate, taxincome, taxwheld, taxmonth, x, line) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/quickadditem', {
		taxname: taxname,
		taxatc: taxatc,
		taxrate: taxrate,
		taxincome: taxincome,
		taxwheld: taxwheld,
		taxmonth: taxmonth,
		x: x,
		line: line
	}, function (data) {

		if (data.data.status) {
			var x = $('.txtboxtrno').val();
			loadstockview();

			if (data.data.runningdb == 0 || data.data.runningdb == null) {
				$('.txtitemcount').html('NUMBER OF ITEMS: 0.00');
			} else {
				$('.txtitemcount').html('NUMBER OF ITEMS: ' + data.data.runningdb);
			}
			if (data.data.runningcr == 0 || data.data.runningcr == null) {
				$('.txtgrandtotal').html('GRAND TOTAL: 0.00');
			} else {
				$('.txtgrandtotal').html('GRAND TOTAL: ' + data.data.runningcr);
			}
		} else {
			generateAlert('error', 'Error adding new tax menu', 'ERROR');
		} //END ELSE
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //END FUNCTION QUICK ADD ITEM


