function removeProcessDataTab(q, line, type, tline = 0) {
	var moduleid = $('#viewmoduleid').val();
	var addedparams = [];

	var qtrno = varstorage.data('fgu_processtrno');
	var qline = varstorage.data('fgu_processline');
	var qbarcode = varstorage.data('fgu_processbarcode');

	addedparams.push({
		name: "trno",
		value: qtrno
	});
	addedparams.push({
		name: "line",
		value: qline
	});
	addedparams.push({
		name: "barcode",
		value: qbarcode
	});

	$.get(domain + '/' + moduleid + '/removeproctabs', {
		q: q,
		line: line,
		tline: tline,
		type: type
	}, function (data) {

		if (data.status) {
			switch (type) {
				case 'INK':
					jbuproc_inkgrid = new GridViewGenerator(domain + '/' + moduleid + '/tabjbuinkgrid', '#jbuprocinkgrid');
					jbuproc_inkgrid.initializeGrid('', null, addedparams);
					break;

				case 'REJECT':
					jbuproc_rejectgrid = new GridViewGenerator(domain + '/' + moduleid + '/tabjburejectgrid', '#jbuprocrejectgrid');
					jbuproc_rejectgrid.initializeGrid('', null, addedparams);
					break;

				case 'OUTPUT':
					jbuproc_outputgrid = new GridViewGenerator(domain + '/' + moduleid + '/tabjbuoutputgrid', '#jbuprocoutputgrid');
					jbuproc_outputgrid.initializeGrid('', null, addedparams);
					break;

				case 'INPUT':
					jbuproc_inputgrid = new GridViewGenerator(domain + '/' + moduleid + '/tabjbuinputgrid', '#jbuprocinputgrid');
					jbuproc_inputgrid.initializeGrid('', null, addedparams);
					break;
			} //end swithc
		} else {
			generateAlert('error', data.msg, 'ERROR');
		} //end if
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	}); //end ajax
} //end fn

