$(document).on('click', '.load-dashboarddata', debounce(function () {
	$('#overlay').css('display', 'block');
	generateAlert('information', "<b>Loading data... Please wait ...</b><br><h6>(Click to Dismiss)</h6>", 'ERROR');
	generatechangeItemamtdates(function (data) {
		$('.tbl-changedates').html("");
		$.each(data.dates, function (idx) {
			$('.tbl-changedates').append('<tr><td class="aimslabel clickable btnviewitemupdates" style="font-weight:bold;">' + data.dates[idx]['dateupdate'] + '</td>\
			<td class="aimslabel">' + data.dates[idx]['updates'] + '</td></tr>');
		});

		generateIndexPageTransCounting(function (data2) {
			$('.frontindex-txtexpenses').text(data2.value['expns'][0]['expenses']);
			$('.frontindex-txtsalespercent').text(data2.value['collect'][0]['collections']);

			$('.frontindex-txttotalsales').text(data2.value['sales']);
			$('.frontindex-txttotalpurchases').text(data2.value['prchs']);
			$('.frontindex-txttotalap').text(data2.value['outap']);
			$('.frontindex-txttotalar').text(data2.value['outar']);

			$('#countunpostrr').html(data2.value['unpostrr']);
			$('#countunpostsj').html(data2.value['unpostsj']);
			$('#countallrr').html(data2.value['prchs']);
			$('#countallsj').html(data2.value['sales']);

			$('#countpaidar').html(data2.value['paidar']);
			$('#countpaidap').html(data2.value['paidap']);
			$('#countallar').html(data2.value['allar']);
			$('#countallap').html(data2.value['allap']);

			var percentageunpostrr = 0;
			var percentageunpostsj = 0;
			percentageunpostrr = (parseFloat(data2.value['unpostrr']) / parseFloat(data2.value['prchs'])) * 100;
			percentageunpostsj = (parseFloat(data2.value['unpostsj']) / parseFloat(data2.value['sales'])) * 100;
			$('#progressbarunpostrr').css('width', percentageunpostrr + '%');
			$('#progressbarunpostsj').css('width', percentageunpostsj + '%');

			var percentagepaidar = 0;
			var percentagepaidap = 0;
			percentagepaidar = (parseFloat(data2.value['paidar']) / parseFloat(data2.value['allar'])) * 100;
			percentagepaidap = (parseFloat(data2.value['paidap']) / parseFloat(data2.value['allap'])) * 100;
			$('#progressbarpaidar').css('width', percentagepaidar + '%');
			$('#progressbarpaidap').css('width', percentagepaidap + '%');


			$('.displayofsales').append('<p class="text-center"> \
		        <strong><span class="pull-left" style="color:#76797e;">[2 Year Ago  %: ' + data2.value['slsper_lls'] + '%' + ']</span>\
		        <span class="pull-left" style="color:#ffe500;">[Previous  Sales %: ' + data2.value['slsper_ls'] + '%' + ']</span>&nbsp;\
		        <span class="pull-left" style="color:#09b500;">[Current Sales %: ' + data2.value['slsper'] + '%' + ']</span>&nbsp;\
		    </strong></p>');

			generateIndexpageLineChart(function (data3) {
				//NEWLY CREATED CHART CLASS CREATOR
				var salesChartDataSet = [];
				//SETS LABELS FOR LINE CHART
				var salesChartLabels = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

				//GETTINGS PREVIOUS YEAR SALES
				$.each(data3.prev, function (arrkey, index) {
					salesChartDataSet.push({
						label: index['yr'],
						strokeColor: '#ffe500',
						pointColor: '#ffe500',
						pointStrokeColor: '#c1c7d1',
						pointHighlightFill: '#ffe500',
						pointHighlightStroke: 'rgb(220,220,220)',
						data: [index['mojan'], index['mofeb'], index['momar'], index['moapr'], index['momay'], index['mojun'], index['mojul'], index['moaug'], index['mosep'], index['mooct'], index['monov'], index['modec']]
					});
				});
				//GETTING THIS CURRENT YEAR SALES
				$.each(data3.current, function (arrkey, index) {
					salesChartDataSet.push({
						label: index['yr'],
						strokeColor: '#09b500',
						pointColor: '#09b500',
						pointStrokeColor: '#c1c7d1',
						pointHighlightFill: '#09b500',
						pointHighlightStroke: 'rgb(220,220,220)',
						data: [index['mojan'], index['mofeb'], index['momar'], index['moapr'], index['momay'], index['mojun'], index['mojul'], index['moaug'], index['mosep'], index['mooct'], index['monov'], index['modec']]
					});
				});

				//GETTING THIS LAST LAST YEAR SALES
				$.each(data3.llys, function (arrkey, index) {
					salesChartDataSet.push({
						label: index['yr'],
						strokeColor: '#76797e',
						pointColor: '#76797e',
						pointStrokeColor: '#c1c7d1',
						pointHighlightFill: '#76797e',
						pointHighlightStroke: 'rgb(220,220,220)',
						data: [index['mojan'], index['mofeb'], index['momar'], index['moapr'], index['momay'], index['mojun'], index['mojul'], index['moaug'], index['mosep'], index['mooct'], index['monov'], index['modec']]
					});
				});

				//GENERATION OF CHART OBJECT
				var linechart1 = new chartGenerator('#salesChart', 'line', {
					'chartlabels': salesChartLabels,
					'chartdata': salesChartDataSet
				});

				linechart1.initialize();

				generateIndexpageSJList(function (data4) {
					$('.tbl-recentsjtrans').html(data4);

					generateIndexPageDocList();
					generateIndexPageTransList();

					$('#overlay').css('display', 'none');
				});
			}); // end generate chart line
		}); //end generate index page trans count
	}); //end generate change item amt dates


	//generateIndexPageSchedList();
	//generateIndexPageTotalUsers();
}, 300))

