$(document).on('click', '.rttupdatetrans', debounce(function () {
	var vattype = $('#vattype option:selected').val();
	var transtype = $('#trnxtype option:selected').val();
	var ttype = $('#transtype option:selected').val();
	var yourref = $('.rttransupdateyourref').val();
	var ourref = $('.rttransupdateourref').val();
	var params = {
		'yref': yourref,
		'vtype': vattype,
		'ttype': transtype,
		'oref': ourref,
		'trtype': ttype
	};
	RTTUpdateTrans(varstorage.data('transtoupdate'), params);
	varstorage.removeData('transtoupdate');
}, 300));

function RTTUpdateTrans(key, params) {
	var moduleid = $('#viewmoduleid').val();
	$.get(domain + '/' + moduleid + '/updatetransaction', {
		q: key,
		qq: params
	}, function (data) {
		if (data.status) {
			var searchstring = $('.txtsearchupdatedocno').val();
			var ttype = $('#transtype option:selected').val();
			searchDocumentToUpdate(ttype, searchstring);
			generateAlert('information', data.msg, 'DEFAULT');
			$('#modal-transupdate').modal('hide');
		} else {
			generateAlert('error', data.msg, 'ERROR');
		} //end if
	}).fail(function (jqXHR, textStatus, error) {
		generateAlert('error', 'System Error: Status Code ' + jqXHR.status, 'ERROR');
	});
} //end f

function searchDocumentToUpdate(ttype, searchstring) {
	var moduleid = $('#viewmoduleid').val();
	transupdatetbl = new GridViewGenerator(domain + '/' + moduleid + '/getdocuments', '.transupdatediv');
	var addedparams = [];

	addedparams.push({
		name: "d",
		value: ttype
	});

	transupdatetbl.initializeGrid(searchstring, null, addedparams);
} //end f


